window.__D("text/zohar-hebrew-translation/c031",{"p":[[9522012348,"<p>כָּעֵת, רַבִּי, נַחֲזֹּר לַדְּבָרִים הָרִאשׁוֹנִים, וּכְשֶׁנַּחֲזֹר לִמְקוֹמֵנוּ נִטֹּל רְשׁוּת מֵרֹאשׁ הַיְשִׁיבָה בְּאוֹתָם דְּבָרִים שֶׁנְּקַבֵּל מִמֶּנּוּ, וְנֹאמַר לְפָנֶיךְ. אַשְׁרֵי חֶלְקְךְ שֶׁאַתָּה זוֹכֶה לְאוֹרוֹת נִסְתָּרִים מִכָּל הַצְּדָדִים מִלְמַעְלָה וּמִלְּמַטָּה מֵהָעוֹלָם הַזֶּה וּמֵעוֹלָם אַחֵר. אָמַר רַבִּי שִׁמְעוֹן, דָּבָר אֶחָד רָצִיתִי לָדַעַת, אִם תּוּכַל לְהוֹדִיעַ לִי. נָשִׁים בְּאוֹתוֹ עוֹלָם אִם זַכָּאִיּוֹת לַעֲלוֹת לְמַעְלָה, אוֹ אֵיךְ הֵן שָׁם? אָמַר לוֹ, אִי רַבִּי אִי רַבִּי, בָּזֶה יֵשׁ לָנוּ סוֹד יָתֵר (נכבד) כְּדֵי לֹא לְגַלּוֹת סוֹדוֹת שֶׁל שָׁם, אֲבָל זֶה יֵלֵךְ וְיִטֹּל רְשׁוּת, וְנֹאמַר לְךְ. בֵּין כָּךְ פָּרַח אֶחָד וְהִתְכַּסָּה מֵהֶם וְהָלַךְ לוֹ.</p>\n<p>וּלְפִי שָׁעָה שָׁב אֲלֵיהֶם. אָמַר לָהֶם, עָתִיד הָיִיתִי לְהִכָּנֵס, וְהָיוּ כֻלָּם בְּעִטּוּר אֶחָד, שֶׁדָּנוּ דִין בֶּן אָדָם אֶחָד שֶׁעָמַד עַל פֶּתַח הַגַּן עֵדֶן, וְאוֹתָם כְּרוּבִים אָחֲזוּ בוֹ, וְלֹא נָתְנוּ אוֹתוֹ לְהִכָּנֵס שָׁם, וְהָיָה בְצַעַר בֵּינֵיהֶם, וְצָוַח צְוָחוֹת עַל גַּבֵּי הַפֶּתַח, וְשָׁמְעוּ כָּל הַצַּדִּיקִים שֶׁשָּׁם, וְכָעֵת הָיוּ מִתְכַּנְּסִים כָּל בְּנֵי הַיְשִׁיבָה לְהִכָּנֵס אֶל מֶלֶךְ הַמָּשִׁיחַ לְעַיֵּן בְּדִינוֹ. וּבָאתִי לְהוֹדִיעַ לָכֶם, וְזֶה חֲבֵרִי הִצְטָרֵךְ לָלֶכֶת לְשָׁם, שֶׁכָּרוֹז הָעֳבַר בְּכָל אוֹתָם בְּנֵי הַיְשִׁיבוֹת שֶׁיִּהְיוּ מִתְכַּנְּסִים כָּעֵת לִפְנֵי הַמָּשִׁיחַ. לָקַח פִּתְקָה אַחַת וְנָתַן לְרַבִּי שִׁמְעוֹן. אָמַר, קַח אֶת זֶה וְעַיֵּן בְּמַה שֶּׁשָּׁם עַד שֶׁנָּבֹא אֵלֶיךְ. וּפָרְחוּ שְׁנֵיהֶם.</p>\n<p>וְרַבִּי שִׁמְעוֹן לָקַח הַפִּתְקָה וְרָאָה מַה שֶּׁרָאָה בַּסּוֹדוֹת שֶׁשָּׁם כָּל אוֹתוֹ יוֹם. בַּלַּיְלָה רָאָה נֵר, וְנָפְלָה עָלָיו שֵׁנָה, וְנִרְדַּם עַד הַבֹּקֶר. כְּשֶׁהֵאִיר הַיּוֹם קָם, וּפָרְחָה אוֹתָהּ פִּתְקָה מִמֶּנּוּ, וְהִנֵּה שְׁנֵיהֶם בָּאִים. אָמַר לוֹ, עֲמֹד רַבִּי, אַשְׁרֵי חֶלְקְךְ. עֲמֹד. בִּגְלָלְךְ רָאִינוּ וְזָכִינוּ לְכַמָּה סְתָרִים עֶלְיוֹנִים, כַּמָּה חֶדְוָה הֶרְאוּ לָנוּ כְּשֶׁנָּתְנוּ רְשׁוּת לְגַלּוֹת לְךְ כָּל מַה שֶּׁאַתָּה רוֹצֶה. רֹאשׁ הַיְשִׁיבָה הָעֶלְיוֹנָה יָצָא אֵלֵינוּ וְאָמַר: שַׁאֲלוּ בִשְׁלוֹם בַּר יוֹחַאי, מְקוֹמוֹ שֶׁל בַּר יוֹחַאי הֲרֵי פָּנוּי לוֹ מִכַּמָּה יָמִים, אֵין מִי שֶׁיִּקְרַב אֵלָיו, אַשְׁרָיו!</p>\n<p>רַבִּי רַבִּי, כְּשֶׁפָּרַחְנוּ מִמְּךְ (בשבילך), נִכְנַסְנוּ וְרָאִינוּ כָּל בְּנֵי הַיְשִׁיבוֹת שֶׁהֲרֵי מִתְכַּנְּסִים לְתוֹךְ הֵיכָל אֶחָד שֶׁשָּׁם הַמָּשִׁיחַ, וְדָנוּ דִין שֶׁל אוֹתוֹ אָדָם שֶׁעָמַד עַל הַפֶּתַח, שֶׁשְּׁמוֹ אֵין לָנוּ רְשׁוּת לְגַלּוֹת. הִצְטַעֵר רַבִּי שִׁמְעוֹן עַל זֶה. אָמַר לוֹ, אַל תִּצְטַעֵר רַבִּי עַל זֶה, אַתָּה תֵּדַע בַּלַּיְלָה הַזֶּה בַּחֲלוֹמְךְ. אֲבָל דִּין דָּנוּ עָלָיו, שֶׁגָּזַר מָשִׁיחַ שֶׁיִּהְיֶה אוֹתוֹ אָדָם בַּחוּץ בְּאוֹתוֹ צַעַר אַרְבָּעִים יוֹם, וּלְסוֹף אַרְבָּעִים יוֹם יְצַעֲרוּ אוֹתוֹ בְּדִין בְּצַעַר הַגֵּיהִנֹּם שָׁעָה וָחֵצִי.</p>\n<p>וְכָל זֶה מִשּׁוּם שֶׁיּוֹם אֶחָד אֶחָד מִן הַחֲבֵרִים הָיָה מְפָרֵשׁ דִּבְרֵי תוֹרָה, וּכְשֶׁהִגִּיעַ לְדָבָר אֶחָד, יָדַע הָאָדָם הַזֶּה שֶׁיִּכָּשֵׁל בּוֹ, וְאָמַר לַחֲבֵרִים: שִׁתְקוּ, אַל תֹּאמְרוּ דָבָר. וּמִשּׁוּם שֶׁשָּׁתְקוּ הַחֲבֵרִים, נִכְשַׁל בְּאוֹתוֹ דָּבָר וְהִתְבַּיֵּשׁ. וְעַל אוֹתָהּ בּוּשָׁה שֶׁגָּרַם אָדָם זֶה, דַּנוּ אוֹתוֹ בַּדִּין הַזֶּה הַקָּשֶׁה, מִשּׁוּם שֶׁלֹּא רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׁאִיר עֲווֹן הַתּוֹרָה אֲפִלּוּ כִּמְלֹא נִימָה.</p>"],[9522012349,"<p>דָּנוּ דִינוֹ, וְיָצְאוּ כָּל בְּנֵי הַיְשִׁיבָה, וַאֲנִי שָׁאַלְתִּי רְשׁוּת, שֶׁהֲרֵי בַּר יוֹחַאי שָׁאַל שְׁאֵלָה זוֹ. וְעַל זֶה הֶרְאוּ לִי מַה שֶּׁלֹּא יָדַעְתִּי מִלִּפְנֵי כֵן. אִי רַבִּי, שִׁשָּׁה הֵיכָלוֹת הֶרְאוּ לִי, בְּכַמָּה עִנּוּגִים וְעִדּוּנִים, בְּמָקוֹם שֶׁפָּרֹכֶת פְּרוּשָׂה בַּגִּנָּה. שֶׁהֲרֵי מֵאוֹתָהּ פָּרֹכֶת וּלְהָלְאָה לֹא נִכְנָסִים זְכָרִים כְּלָל.</p>\n<p>בְּהֵיכָל אֶחָד יֵשׁ בַּתְיָה בַּת פַּרְעֹה, וְכַמָּה רִבּוֹא וְאַלְפֵי נָשִׁים זוֹכוֹת אִתָּהּ, וּלְכָל אַחַת וְאַחַת מֵהֶן יֵשׁ מְקוֹמוֹת שֶׁל אוֹרוֹת וְעִדּוּנִים לְלֹא דחַק כְּלָל. שָׁלֹשׁ פְּעָמִים בְּכָל יוֹם הַכָּרוֹזוֹת מַכְרִיזִים: הֲרֵי דְּמוּת מֹשֶׁה נָבִיא הַנֶּאֱמָן בָּאָה! וּבַתְיָה יוֹצֵאת לִמְקוֹם פַּרְגּוֹד אֶחָד שֶׁיֵּשׁ לָהּ, וְרוֹאָה דְמוּת מֹשֶׁה וּמִשְׁתַּחֲוָה אֵלָיו, וְאוֹמֶרֶת: אַשְׁרֵי חֶלְקִי שֶׁגִּדַּלְתִּי אוֹר זֶה. וְזֶה עִנּוּגִים שֶׁלָּהּ יוֹתֵר מִכֻּלָּם.</p>\n<p>חוֹזֶרֶת לַנָּשִׁים וּמִשְׁתַּדֶּלֶת בְּמִצְווֹת הַתּוֹרָה. כֻּלָּן בְּאוֹתָן דְּמֻיּוֹת שֶׁהָיוּ בָּעוֹלָם הַזֶּה בִּלְבוּשׁ אוֹר, (כלבוש) בִּלְבוּשׁ הַזְּכָרִים, פְּרָט שֶׁלֹּא מְאִירִים כָּךְ, מִצְווֹת הַתּוֹרָה שֶׁלֹּא זָכוּ לְקַיְּמָן בָּעוֹלָם הַזֶּה, מִשְׁתַּדְּלוֹת בָּהֶן וּבְטַעֲמֵיהֶן בְּאוֹתוֹ עוֹלָם. וְכָל הַנָּשִׁים הַלָּלוּ שֶׁיּוֹשְׁבוֹת יַחַד עִם בַּת פַּרְעֹה נִקְרָאוֹת (ישעיה לב) נָשִׁים שַׁאֲנַנּוֹת, שֶׁלֹּא הִצְטַעֲרוּ כְלָל בְּצַעַר הַגֵּיהִנֹּם.</p>\n<p>בְּהֵיכָל אַחֵר יֵשׁ סֶרַח בַּת אָשֵׁר, וְכַמָּה נָשִׁים רִבּוֹא וַאֲלָפִים יַחַד אִתָּהּ. שָׁלֹשׁ פְּעָמִים בְּיוֹם מַכְרִיזִים לְפָנֶיהָ: הֲרֵי דְּמוּת יוֹסֵף הַצַּדִּיק בָּאָה! וְהִיא שְׂמֵחָה וְיוֹצֵאת לְגַבֵּי פַרְגּוֹד אֶחָד שֶׁיֵּשׁ לָהּ, וְרוֹאָה אוֹר דְּמוּת יוֹסֵף, וּשְׂמֵחָה, וּמִשְׁתַּחֲוָה אֵלָיו וְאוֹמֶרֶת: אַשְׁרֵי הַיּוֹם שֶׁעוֹרַרְתִּי בְשׂוֹרָתְךְ לְסָבִי. אַחַר כָּךְ חוֹזֶרֶת לִשְׁאָר הַנָּשִׁים, וּמִשְׁתַּדְּלוֹת בְּתִשְׁבְּחוֹת רִבּוֹן הָעוֹלָם וּלְהוֹדוֹת לִשְׁמוֹ. וְכַמָּה מְקוֹמוֹת וְשִׂמְחָה יֵשׁ לְכָל אַחַת וְאַחַת. אַחַר כָּךְ חוֹזְרוֹת לְהִשְׁתַּדֵּל בְּמִצְווֹת הַתּוֹרָה וּבְטַעֲמֵיהֶן.</p>\n<p>בְּהֵיכָל אַחֵר יֵשׁ יוֹכֶבֶד אֵם מֹשֶׁה נָבִיא הַנֶּאֱמָן, וְכַמָּה אֲלָפִים וּרְבָבוֹת עִמָּהּ. בְּהֵיכָל זֶה לֹא מַכְרִיזִים כְּלָל, אֶלָּא שָׁלֹשׁ פְּעָמִים בְּכָל יוֹם וָיוֹם מוֹדָה וּמְשַׁבַּחַת לְרִבּוֹן הָעוֹלָם הִיא וְכָל הַנָּשִׁים שֶׁאִתָּהּ. וְשִׁירַת הַיָּם מְזַמְּרוֹת בְּכָל יוֹם, וְהִיא לְבַדָּהּ אוֹמֶרֶת מִכָּאן, (שמות טו) וַתִּקַּח מִרְיָם הַנְּבִיאָה וְגוֹ', אֶת הַתֹּף בְּיָדָהּ וְגוֹ'. וְכָל אוֹתָם צַדִּיקֵי גַּן עֵדֶן מַקְשִׁיבִים לִנְעִימוּת קוֹלָהּ, וְכַמָּה מַלְאָכִים קְדוֹשִׁים מוֹדִים וּמְשַׁבְּחִים עִמָּהּ לַשֵּׁם הַקָּדוֹשׁ.</p>\n<p>בְּהֵיכָל אַחֵר יֵשׁ דְּבוֹרָה, גַּם כָּךְ וְכָל שְׁאָר הַנָּשִׁים אִתָּהּ מוֹדוֹת וּמְזַמְּרוֹת בְּאוֹתָהּ שִׁירָה שֶׁהִיא אָמְרָה בָּעוֹלָם הַזֶּה. אִי רַבִּי, אִי רַבִּי, מִי רָאָה חֶדְוַת הַצַּדִּיקִים וְשֶׁל נָשִׁים זַכָּאִיּוֹת שֶׁעוֹשׂוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. לִפְנַי וְלִפְנִים שֶׁל אוֹתָם הֵיכָלוֹת יֵשׁ אַרְבָּעָה הֵיכָלוֹת טְמִירִים שֶׁל הָאִמָּהוֹת הַקְּדוֹשׁוֹת שֶׁלֹּא נִמְסָר לְהִגָּלוֹת, וְאֵין מִי שֶׁרוֹאֶה אוֹתָן. בְּכָל הַיּוֹם הֵן לְבַדָּן, כְּמוֹ שֶׁאָמַרְתִּי לְךְ, וְהַגְּבָרִים גַּם כֵּן.</p>\n<p>וּבְכָל לַיְלָה נִכְלָלִים כֻּלָּם כְּאֶחָד, מִשּׁוּם שֶׁשְּׁעַת הַזִּוּוּג הִיא בַּחֲצוֹת הַלַּיְלָה, בֵּין בָּעוֹלָם הַזֶּה וּבֵין בָּעוֹלָם הַבָּא. זִוּוּג אוֹתוֹ עוֹלָם - הִתְדַבְּקוּת נְשָׁמָה בִּנְשָׁמָה, אוֹר בְּאוֹר. זִוּוּג הָעוֹלָם הַזֶּה - גּוּף בְּגוּף. וְהַכֹּל כְּמוֹ שֶׁרָאוּי, מִין אַחַר מִינוֹ, זִוּוּג אַחַר זִוּוּג, גּוּף אַחַר גּוּף, זִוּוּג אוֹתוֹ עוֹלָם אוֹר אַחַר אוֹר. הֵיכְלֵי אַרְבַּע הָאִמָּהוֹת נִקְרָאִים הֵיכָלוֹת שֶׁל בָּנוֹת בּטְחוֹת (ישעיה לב), וְלֹא זָכִינוּ בָהֶם לִרְאוֹת. אַשְׁרֵי חֵלֶק הַצַּדִּיקִים, גְּבָרִים וּנְקֵבוֹת שֶׁהוֹלְכִים בְּדֶרֶךְ יָשָׁר בָּעוֹלָם הַזֶּה, וְזַכָּאִים לְכָל הָעִנּוּגִים שֶׁל אוֹתוֹ עוֹלָם.</p>\n<p>אִי רַבִּי, אִי רַבִּי, אִלְמָלֵא בַּר יוֹחַאי י אַתָּה, לֹא נִמְסַר לְגַלּוֹת. זִוּוּג אוֹתוֹ עוֹלָם נַעֲשֶׂה פְרִי יוֹתֵר מִפְּרִי שֶׁנַּעֲשֶׂה בָּעוֹלָם הַזֶּה. בַּזִּוּוּג שֶׁלָּהֶם, בְּזִוּוּג אוֹתוֹ עוֹלָם, בָּעֶרְגָּה שֶׁלָּהֶם כְּאֶחָד, כְּשֶׁהַנְּשָׁמוֹת נִדְבָּקוֹת זוֹ בָּזוֹ, עוֹשׂוֹת פֵּרוֹת, וְיוֹצְאִים אוֹרוֹת מֵהֶם וְנַעֲשִׂים נֵרוֹת. וְהֵם הַנְּשָׁמוֹת לַגֵּרִים הַמִּתְגַּיְּרִים, וְכָל אֵלֶּה עוֹלִים לְהֵיכָל אֶחָד.</p>\n<p>וּכְשֶׁמִּתְגַּיֵּר גֵּר אֶחָד, פּוֹרַחַת מֵאוֹתוֹ הֵיכָל נְשָׁמָה, וְנִכְנֶסֶת תַּחַת כַּנְפֵי הַשְּׁכִינָה, וְנוֹשֶׁקֶת אוֹתָהּ, מִשּׁוּם שֶׁהִיא פְּרִי הַצַּדִּיקִים, וְשׁוֹלַחַת אוֹתָהּ לְתוֹךְ אוֹתוֹ גֵּר וְשׁוֹרָה בּוֹ, וּמֵאוֹתוֹ זְמַן נִקְרָא גֵר צֶדֶק. וְזֶהוּ סוֹד הַכָּתוּב, (משלי יא) פְּרִי צַדִּיק עֵץ חַיִּים. מָה עֵץ הַחַיִּים מוֹצִיא נְשָׁמוֹת, גַּם צַדִּיק פִּרְיוֹ עוֹשֶׂה נְשָׁמוֹת.</p>\n<p>רֹאשׁ הַיְשִׁיבָה אָמַר, כָּתוּב (בראשית יא) וַתְּהִי שָׂרַי עֲקָרָה אֵין לָהּ וָלָד. מִמַּה שֶּׁאָמַר וַתְּהִי שָׂרַי עֲקָרָה, אֵינִי יוֹדֵעַ שֶׁאֵין לָהּ וָלָד? מַה זֶּה אֵין לָהּ וָלָד? אֶלָּא כָּךְ אָמַר רֹאשׁ הַיְשִׁיבָה, וָלָד לֹא הָיְתָה מוֹלִידָה, אֲבָל נְשָׁמוֹת הָיְתָה מוֹלִידָה בְּהִתְדַּבְּקוּת עֶרְגָּה, שֶׁאוֹתָם שְׁנֵי צַדִּיקִים הָיוּ מוֹלִידִים נְשָׁמוֹת לַגֵּרִים כָּל אוֹתוֹ זְמַן שֶׁהָיוּ בְחָרָן כְּמוֹ שֶׁעָשׂוּ צַדִּיקִים בְּגַן עֵדֶן, כְּמוֹ שֶׁכָּתוּב (שם יב) וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן. נֶפֶשׁ עָשׂוּ בְּוַדַּאי.</p>\n<p>שָׂמַח רַבִּי שִׁמְעוֹן. אָמַר לוֹ אוֹתוֹ הָאִישׁ, אִי רַבִּי, מָה אֹמַר לְךְ, בְּכָל רֹאשׁ חֹדֶשׁ וְשַׁבָּתוֹת וּמוֹעֲדִים וּזְמַנִּים, אוֹתָם זְכָרִים עוֹלִים לְהֵרָאוֹת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, זְכָרִים וְלֹא נְקֵבוֹת, כְּמוֹ שֶׁנֶּאֱמַר (שמות כג) יֵרָאֶה כָּל זְכוּרְךְ. וּכְשֶׁחוֹזְרִים, חוֹזְרִים בְּכַמָּה דְבָרִים חֲדָשִׁים, וּמַחֲזִירִים דְּבָרִים לִפְנֵי רֹאשׁ הַיְשִׁיבָה.</p>\n<p>יוֹם זֶה הֶחֱזִירוּ דְבָרִים חֲדָשִׁים לִפְנֵי רֹאשׁ הַיְשִׁיבָה עַל סוֹדוֹת עַתִּיקִים - צַדִּיק וְטוֹב לוֹ, צַדִּיק וָרָע לוֹ. שֶׁכֻּלָּם עוֹלִים תּוֹךְ מִשְׁקַל הָאִילָן עַד שֶׁלֹּא יָבאוּ לָעוֹלָם, וּכְפִי מִשְׁקֹלֶת הַמִּשְׁקָל כָּךְ יֵשׁ לָהֶם בָּעוֹלָם הַזֶּה. רֹאשׁ הַיְשִׁיבָה יָרַד וְגִלָּה מִמַּה שֶּׁשָּׁמַע לְמַעְלָה, דָּבָר אֶחָד גִּלָּה וְלֹא יוֹתֵר. עֵץ שֶׁלֹּא עוֹלֶה אוֹרוֹ, יַכּוּ בוֹ וְיָאִיר. גּוּף שֶׁלֹּא עוֹלֶה בּוֹ אוֹר הַנְּשָׁמָה, יַכּוּ בוֹ וְיַעֲלֶה אוֹר הַנְּשָׁמָה, וְיֹאחֲזוּ זֶה בָזֶה לְהָאִיר. (שתי נסחאות)</p>\n<p>מִשּׁוּם שֶׁיֵּשׁ גּוּף שֶׁאוֹר הַנְּשָׁמָה לֹא מֵאִיר בּוֹ עַד שֶׁיַּכּוּ בוֹ, אָז מֵאִיר אוֹר הַנְּשָׁמָה וְנֶאֱחָז בַּגּוּף, וְהַגּוּף נֶאֱחָז בּוֹ. הַגּוּף אָז עוֹלֶה אוֹר מִתּוֹךְ הַנְּשָׁמָה, מְהַדֵּר מְרוֹמֵם וּמְשַׁבֵּחַ, מִתְפַּלֵּל תְּפִלָּתוֹ וּבַקָּשָׁתוֹ, מְבָרֵךְ לְרִבּוֹנוֹ. הֲרֵי אָז הַכֹּל מֵאִיר, מִשּׁוּם שֶׁיֵּשׁ גּוּף שֶׁאֵין הַנְּשָׁמָה יְכוֹלָה לְהָאִיר בּוֹ עַד שֶׁיַּכּוּ בוֹ, וְאָז מֵאִיר וְנֶאֱחָז זֶה בָזֶה. יֵשׁ עֵץ שֶׁלֹּא נֶאֱחָז בָּאוֹר, וְלֹא עוֹלֶה בּוֹ אוֹר עַד שֶׁיַּכּוּ בוֹ, וְאָז מֵאִיר.</p>\n<p>צַד הָאַחֵר רוֹצֶה לַעֲשׂוֹת כָּךְ, וּמַכֶּה בָרְשָׁעִים, וְכָל מַה שֶּׁמַּכֶּה, אָז (משלי יג) וְנֵר רְשָׁעִים יִדְעָךְ. מְחָרֵף וּמְגַדֵּף לְכָל הַצְּדָדִים וְלֹא יָכוֹל לְהָאִיר כְּלָל, וְאָז כָּתוּב (קהלת ב) כִּי מֶה הָאָדָם שֶׁיָּבוֹא אַחֲרֵי הַמֶּלֶךְ. וְרוֹצֶה לְהִדָּמוֹת לוֹ וְלֹא יָכוֹל. וְעַל זֶה (תהלים יא) ה' צַדִּיק יִבְחָן, וּמַכֶּה בּוֹ, וְאָז מֵאִיר וּמִתְחַזֵּק בָּאוֹר. יִבְחָן, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כח) אֶבֶן בּחַן. גָּחַן רַבִּי שִׁמְעוֹן וְנָשַׁק לֶעָפָר. אָמַר, דָּבָר דָּבָר אַחֲרֶיךְ רָדַפְתִּי מִיּוֹם שֶׁהָיִיתִי, וְכָעֵת נוֹדַע לִי הַדָּבָר מִתּוֹךְ שֹׁרֶשׁ וְעִקַּר הַכֹּל.</p>\n<p>אָמַר לוֹ, אִי רַבִּי, אִי רַבִּי, כְּשֶׁעוֹלִים לְמַעְלָה, כָּל אוֹתָם רוּחוֹת זְכָרִים וּנְקֵבוֹת בְּאוֹתוֹ זְמַן שׁוֹמְעִים (כמה) דְּבָרִים חֲדָשִׁים וְעַתִּיקִים, יוֹרְדִים וְנִכְנָסִים לְתוֹךְ הַיְשִׁיבָה, וּמַחֲזִירִים דְּבָרִים לִפְנֵי רֹאשׁ הַיְשִׁיבָה, וְהוּא מְלַמְּדָם דָּבָר עַל קִיּוּמוֹ. כְּשֶׁעוֹלִים, מִתְפַּשְּׁטִים מִלְּבוּשֵׁיהֶם וְעוֹלִים. כְּשֶׁיּוֹרְדִים, מִתְלַבְּשִׁים בִּלְבוּשֵׁיהֶם שֶׁל אוֹתוֹ גּוּף.</p>"],[9522012350,"<p>אִי רַבִּי, אִי רַבִּי, כַּמָּה דְבָרִים חֲדָשִׁים מִתּוֹךְ רֹאשׁ הַיְשִׁיבָה. אַשְׁרָיו מִי שֶׁמַּקְטִין עַצְמוֹ בָּעוֹלָם הַזֶּה, כַּמָּה הוּא גָּדוֹל וְעֶלְיוֹן בָּעוֹלָם הַהוּא. וְכָךְ פָּתַח רֹאשׁ הַיְשִׁיבָה: מִי שֶׁהוּא קָטָן - הוּא גָּדוֹל, וּמִי שֶׁהוּא גָּדוֹל - הוּא קָטָן, שֶׁכָּתוּב (בראשית כג) וַיִּהְיוּ חַיֵּי שָׂרָה מֵאָה שָׁנָה וְעֶשְׂרִים שָׁנָה וְשֶׁבַע שָׁנִים. מֵאָה, שֶׁהוּא חֶשְׁבּוֹן גָּדוֹל, כָּתוּב בּוֹ שָׁנָה, קְטַן הַשָּׁנִים, לְאֶחָד הִקְטִינוֹ. שֶׁבַע, שֶׁהוּא חֶשְׁבּוֹן קָטָן, הִגְדִּילוֹ וְרִבָּה אוֹתוֹ, שֶׁכָּתוּב שֶׁבַע שָׁנִים. בֹּא וּרְאֵה שֶׁלֹּא הִגְדִּיל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא לַמַּקְטִין. לֹא הִקְטִין אֶלָּא לְמִי שֶׁהִתְגַּדֵּל. אַשְׁרֵי מִי שֶׁמַּקְטִין עַצְמוֹ בָּעוֹלָם הַזֶּה, כַּמָּה הוּא גָּדוֹל בְּעִלּוּי בְּאוֹתוֹ הָעוֹלָם.</p>"],[9522012351,"<p>בֵּין כָּךְ שָׁמְעוּ שִׁירַת הַיָּם בְּקוֹל נָעִים שֶׁלֹּא שָׁמְעוּ מִיּוֹם שֶׁנִּבְרְאוּ, קוֹל נָעִים שֶׁל שִׁירָה כְּאוֹתָהּ נְעִימָה שֶׁהָיוּ אוֹמְרִים. וּכְשֶׁסִּיְּמוּ (שמות טו) ה' יִמְלֹךְ לְעֹלָם וָעֶד, רָאוּ אַרְבַּע דְמֻיּוֹת בָּרָקִיעַ, וְאֶחָד מֵהֶם גָּדוֹל וְעֶלְיוֹן מִכֻּלָּם. וְאוֹתוֹ גָּדוֹל וְעֶלְיוֹן מֵהֶם עוֹרֵר קוֹל וְאָמַר, (ירמיהב) כֹּה אָמַר ה' זָכַרְתִּי לָךְ חֶסֶד נְעוּרַיִךְ אַהֲבַת כְּלוּלֹתָיִךְ וְגוֹ'. שָׁט בָּרָקִיעַ וְנִגְנַז, עָמַד אַחֵר אַחֲרָיו וְאָמַר, (ישעיה מב) וְהוֹלַכְתִּי עִוְרִים בְּדֶרֶךְ לֹא יָדָעוּ בִּנְתִיבוֹת לֹא יָדְעוּ וְגוֹ'. סִיֵּם וְשָׁט בָּרָקִיעַ וְנִגְנַז.</p>\n<p>פָּתַח הָאַחֵר וְאָמַר, (שם לה) יְשֻׂשׂוּם מִדְבָּר וְצִיָּה וְתָגֵל עֲרָבָה וְתִפְרַח כַּחֲבַצָּלֶת. וְשָׁט בָּרָקִיעַ וְנִגְנַז. פָּתַח הָאַחֵר וְאָמַר, (שם מג) כֹּה אָמַר ה' בֹּרַאֲךְ יַעֲקֹב וְגוֹ'. (שם) כֹּה אָמַר ה' הַנּוֹתֵן בַּיָּם דָּרֶךְ וּבְמַיִם עַזִּים נְתִיבָה וְגוֹ', תְּכַבְּדֵנִי חַיַּת הַשָּׂדֶה תַּנִּים וּבְנוֹת יַעֲנָה וְגוֹ'. סִיֵּם וְשָׁט בָּרָקִיעַ וְנִגְנַז. אָז פַּחַד גָּדוֹל וְאֵימָה נָפַל עֲלֵיהֶם.</p>\n<p>כְּשֶׁהֵאִיר הַיּוֹם, קוֹל הִתְעוֹרֵר כְּמִקֹּדֶם וְאָמַר: עַם תַּקִּיף כְּאַרְיֵה, גִּבּוֹרִים כַּנְּמֵרִים, תְּנוּ כָבוֹד לְרִבּוֹנְכֶם, שֶׁכָּתוּב (שם כה) עַל כֵּן יְכַבְּדוּךְ עַם עָז וְגוֹ'. שָׁמְעוּ קוֹל, חֲיָלוֹת וּמֶרְכָּבוֹת שֶׁהָיוּ אוֹמְרִים, (דברי הימים א כט) לְךְ ה' הַגְּדֻלָּה וְהַגְּבוּרָה וְהַתִּפְאֶרֶת וְהַנֵּצַח וְהַהוֹד וְגוֹ', עַד (נחמיה ט) וּמְרוֹמַם עַל כָּל בְּרָכָה וּתְהִלָּה. תָּמְהוּ וְהָלְכוּ. בֵּין כָּךְ הֵאִיר הַיּוֹם, הֶחֱזִירוּ רֹאשׁ, וְרָאוּ כָּל הַמִּדְבָּר מְכֻסֶּה בְּעַנְנֵי כָבוֹד מְאִירִים, נוֹצְצִים בִּגְוָנִים רַבִּים.</p>\n<p>אָמְרוּ זֶה לָזֶה, וַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְהִשְׁתַּבֵּחַ בַּתִּשְׁבַּחַת שֶׁל דּוֹר הַמִּדְבָּר, שֶׁלֹּא הָיָה בָּעוֹלָם דּוֹר עֶלְיוֹן כְּדוֹר זֶה, וְלֹא יִהְיֶה עַד שֶׁיָּבֹא מֶלֶךְ הַמָּשִׁיחַ. וַדַּאי כָּל מַה שֶּׁהֶרְאָה לָנוּ הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא הָיָה אֶלָּא בִּשְׁבִיל לְהוֹדִיעֵנוּ חֲבִיבוּת רִבּוֹנָם עֲלֵיהֶם, לְהוֹדִיעַ שֶׁיֵּשׁ לָהֶם חֵלֶק טוֹב, וְהֵם בְּנֵי עוֹלָם הַבָּא. וְלֶעָתִיד לָבֹא כְּשֶׁיָּקִים הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַמֵּתִים, עֲתִידִים אֵלּוּ לַעֲמֹד לִתְחִיָּה בָּרִאשׁוֹנָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיהכו) יִחְיוּ מֵתֶיךְ, וְאֵלֶּה הֵם דּוֹר הַמִּדְבָּר.</p>"],[9522012352,"<p>אָמַר לוֹ, הַאִם דָּבָר חָדָשׁ יָדַעְתָּ שֶׁאֲנִי מְעֻרְטָל מִמֶּנּוּ? אָמַר לוֹ, אֱמֹר. אָמַר, קוֹל הַחוֹזֵר רָצִיתִי לָדַעַת. בֶּן אָדָם נוֹתֵן קוֹל בַּשָּׂדֶה אוֹ בְמָקוֹם אַחֵר, וְחוֹזֵר קוֹל אַחֵר וְלֹא יָדוּעַ. אָמַר לוֹ, אִי חָסִיד קָדוֹשׁ, עַל דָּבָר זֶה כַּמָּה קוֹלוֹת הִתְעוֹרְרוּ, וְכַמָּה דִקְדּוּקִים הָיו לִפְנֵי רֹאשׁ הַיְשִׁיבָה. וּכְשֶׁיָּרַד רֹאשׁ הַיְשִׁיבָה, אָמַר, כָּךְ פֵּרְשׁוּהָ דָּבָר בִּישִׁיבַת הָרָקִיעַ, וְסוֹד נִכְבָּד הוּא.</p>\n<p>בֹּא וּרְאֵה, שְׁלֹשָׁה קוֹלוֹת הֵם שֶׁלֹּא נֶאֱבָדִים לְעוֹלָמִים, פְּרָט לְקוֹל הַתּוֹרָה וְהַתְּפִלָּה, שֶׁאֵלֶּה עוֹלִים לְמַעְלָה וּבוֹקְעִים רְקִיעִים. אֲבָל קוֹלוֹת אֲחֵרִים הֵם שֶׁלֹּא עוֹלִים וְלֹא אוֹבְדִים.</p>\n<p>וְהֵם הַשְּׁלֹשָׁה: קוֹל הַחַיָּה בְּשָׁעָה שֶׁהִיא עַל הַמַּשְׁבֵּר, אוֹתוֹ קוֹל מְשׁוֹטֵט וְהוֹלֵךְ בָּאֲוִיר מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם. קוֹל הַבֶּן אָדָם בְּשָׁעָה שֶׁיּוֹצֵאת נִשְׁמָתוֹ מִגּוּפוֹ, אוֹתוֹ קוֹל מְשׁוֹטֵט וְהוֹלֵךְ בָּאֲוִיר מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם. קוֹל הַנָּחָשׁ בְּשָׁעָה שֶׁפּוֹשֵׁט עוֹרוֹ, אוֹתוֹ קוֹל מְשׁוֹטֵט בָּאֲוִיר וְהוֹלֵךְ מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם.</p>\n<p>אִי חָסִיד קָדוֹשׁ, כַּמָּה דָבָר זֶה גָּדוֹל וְנִכְבָּד. אֵלֶּה הַקּוֹלוֹת מַה נַּעֲשֶׂה מֵהֶם, וּלְאֵיזֶה מָקוֹם נִכְנָסִים וְשׁוֹרִים? אֵלֶּה הֵם קוֹלוֹת צַעַר, וְהוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם בָּאֲוִיר, וְהוֹלְכִים מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם, וְנִכְנָסִים לְתוֹךְ נְקִיקִים וּמְחִלּוֹת עָפָר וְנִסְתָּרִים שָׁם. וּכְשֶׁנּוֹתֵן אָדָם קוֹל, הֵם מִתְעוֹרְרִים לְאוֹתוֹ קוֹל. קוֹל נָחָשׁ לֹא מִתְעוֹרֵר לְקוֹל אָדָם. אֵיךְ יִתְעוֹרֵר? בְּמַכָּה. כְּשֶׁמַּכֶּה אָדָם מַכָּה, מִתְעוֹרֵר קוֹל הַנָּחָשׁ שֶׁנִּסְתָּר אֵלָיו אוֹתוֹ קוֹל, וְלֹא קוֹל אַחֵר. קוֹל מִתְעוֹרֵר אַחַר קוֹל, מִין אַחַר מִינוֹ.</p>\n<p>וְעַל כָּךְ בְּיוֹם רֹאשׁ הַשָּׁנָה קוֹל שׁוֹפָר מְעוֹרֵר קוֹל שׁוֹפָר אַחֵר, מִין אַחַר מִינוֹ הוֹלֵךְ. דֶּרֶךְ הַנָּחָשׁ הוּא לְרַע, לַהֲרֹג וּלְהַכּוֹת. בְּאוֹתוֹ קוֹל מַמָּשׁ לֹא מִתְעוֹרֵר קוֹל נָחָשׁ זֶה אֶלָּא אַחַר מִינוֹ. וְזֶהוּ כְּשֶׁאָדָם מַכֶּה בְּמַקֵּל בָּאָרֶץ וְקוֹרֵא לוֹ לְמִינוֹ, אָז מִתְעוֹרֵר אוֹתוֹ קוֹל הַנָּחָשׁ לְהָשִׁיב לְמִינוֹ. וְסוֹד זֶה הוּא נִסְתָּר.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, וַדַּאי דָּבָר זֶה הוּא דָּבָר נִסְתָּר, וְתָמַהְנוּ אֵיךְ שְׁלֹמֹה הַמֶּלֶךְ לֹא יָדַע דָּבָר זֶה. אָמַר לוֹ, שְׁלֹמֹה הַמֶּלֶךְ יָדוֹעַ יָדַע, וְלֹא כָּל כָּךְ. אֲבָל מַה שֶּׁלֹּא יָדַע, אוֹתוֹ קוֹל מַה תּוֹעֶלֶת יֵשׁ בּוֹ, וְאֵיךְ יוֹשֵׁב?</p>\n<p>וְרֹאשׁ הַיְשִׁיבָה כָּךְ אָמַר, דִּקְדּוּק זֶה לֹא יָדַע שְׁלֹמֹה הַמֶּלֶךְ, שֶׁהֲרֵי אוֹתוֹ קוֹל כָּלוּל רוּחַ וְנֶפֶשׁ, וְהֶבֶל עֲצָמוֹת מֵעִצְּבוֹן בָּשָׂר, וּמְשׁוֹטֵט בָּאֲוִיר, וְכָל אֶחָד נִפְרָד זֶה מִזֶּה. וּכְשֶׁמַּגִּיעַ לְאוֹתוֹ מָקוֹם שֶׁנִּכְנַס בּוֹ, יוֹשֵׁב כְּמֵת. וְכָל אוֹתָם מְכַשְּׁפִים וְקוֹסְמִים יוֹדְעִים מְקוֹמוֹת אֵלּוּ בְּכִשְׁפֵיהֶם, וְגוֹחֲנִים לָאָרֶץ, וְשׁוֹמְעִים קוֹל זֶה שֶׁמִּתְחַבְּרִים אוֹתָם רוּחַ וְנֶפֶשׁ וְהֶבֶל עֲצָמוֹת, וּמוֹדִיעִים דָּבָר, וְזֶהוּ (ישעיהכט) אוֹב מֵאֶרֶץ. וְעַל זֶה רָדַף שְׁלֹמֹה לָדַעַת מַה נַּעֲשָׂה מֵאוֹתוֹ קוֹל, וְלֹא יָדַע. אַשְׁרֵי חֶלְקְךְ, רַבִּי, שֶׁהֻבְרַר לְךְ דְּבַר אֱמֶת.</p>\n<p>כְּשֶׁבֶּן אָדָם מְעוֹרֵר קוֹל, מִיָּד (מתחברים) מִתְעוֹרֵר אוֹתוֹ קוֹל, וְאֵין לוֹ רְשׁוּת לְהַאֲרִיךְ יוֹתֵר, אֶלָּא כְּעֵין אוֹתוֹ קוֹל שֶׁעוֹרֵר הָאָדָם, וְלֹא יוֹתֵר. וְאִם הֶאֱרִיךְ הָאִישׁ קוֹלוֹ, הוּא לֹא מַאֲרִיךְ כָּל כָּךְ אִתּוֹ, אֶלָּא לְסוֹף הַקּוֹל, מִשּׁוּם שֶׁלֹּא יָכוֹל לְהַאֲרִיךְ. מָה הַטַּעַם? מִשּׁוּם שֶׁכְּשֶׁיּוֹצֵא בַּהַתְחָלָה, מִתְאָרֵךְ מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם. וְכָעֵת שֶׁנִּכְנָס לְשָׁם, לֹא יָכוֹל לְהַאֲרִיךְ קוֹל, שֶׁהֲרֵי אֵין לוֹ מָקוֹם לְהִתְפַּשֵּׁט שָׁם כְּבַתְּחִלָּה.</p>\n<p>שָׂמַח רַבִּי שִׁמְעוֹן וְאָמַר, אִלְמָלֵא לֹא זָכִיתִי לִשְׁמֹעַ אֶלָּא דָּבָר זֶה - דַּי לִי לִהְיוֹת שָׂמֵחַ שֶׁזָּכִיתִי לִשְׁמֹעַ דְּבַר אֱמֶת שֶׁל אוֹתוֹ עוֹלָם. אָמַר לוֹ, אִי חָסִיד קָדוֹשׁ, אִלְמָלֵא יָדַעְתָּ חֶדְוַת דִּבְרֵי אוֹתוֹ עוֹלָם לִפְנֵי רֹאשׁ הַיְשִׁיבָה, תִּשְׂמַח יוֹתֵר.</p>"],[9522012353,"<p>אָמַר לוֹ, מַה חִדּוּשׁ הָיָה כָעֵת כְּשֶׁבָּאתָ אֵלַי? אָמַר, רֹאשׁ הַיְשִׁיבָה פָּתַח וְאָמַר, (בראשית מו) וְיוֹסֵף יָשִׁית יָדוֹ עַל עֵינֶיךְ. חֶדְוָה הִיא. מַדּוּעַ סְתִימַת הָעֵינַיִם לְמֵת? מִשּׁוּם שֶׁהָעֵינַיִם הֵן גְּוָנִים שֶׁל הָעוֹלָם הַזֶּה, וּמַרְאֵה וּדְמוּת הָעוֹלָם בָּהֶן. הוּא נִסְתָּם מִמֶּנּוּ עוֹלָם הַזֶּה וּמַרְאֵה הָעוֹלָם הַזֶּה, נִסְתְּמוּ עֵינָיו. כָּל מַרְאֵה הָעוֹלָם הַזֶּה נֶחְשָׁךְ מִמֶּנּוּ, וְנֶחְשְׁכוּ מִמֶּנּוּ מַרְאֵה עֵינָיו, אֵין לוֹ מַרְאֶה בָּעוֹלָם הַזֶּה מִשָּׁם וָהָלְאָה. אָמַר רַבִּי שִׁמְעוֹן, נָאֶה תִקּוּן הַקַּדְמוֹנִים, וְחָכְמָתָם יְתֵרָה מִמַּלְאָכִים קְדוֹשִׁים.</p>\n<p>אָמַר לוֹ, לָמָּה יוֹסֵף יָשִׁית יָדוֹ מִכָּל בָּנָיו? וְאִם תֹּאמַר עַל בְּשׂוֹרָה שֶׁלּוֹ, צָרִיךְ לוֹמַר וְיוֹסֵף חַי תִּרְאֶה. אָמַר לוֹ יָשִׁית יָדוֹ, מִשּׁוּם שֶׁאַהֲבָתוֹ הָיָה, וּמִשּׁוּם כָּךְ זֶה נִסְתָּם מִמֶּנּוּ אוֹר הָעוֹלָם הַזֶּה, וְזֶה לָקַח אוֹתוֹ. מִי שֶׁסּוֹתֵם עֵינָיו, אֲהוּבוֹ מַרְאֶה כָּךְ: מַרְאֶה שֶׁלְּךְ שֶׁל הָעוֹלָם הַזֶּה אָבַד, הֲרֵינִי מַרְאֶה שֶׁלְּךְ בִּמְקוֹמְךְ. מִכָּאן וָהָלְאָה יְתַקְּנוּ לְךְ מַרְאֶה אַחֵר שֶׁל אוֹתוֹ עוֹלָם.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, מַה הֲנָאָה זוֹ לַמֵּת, וּמַה תּוֹעֶלֶת יֵשׁ לוֹ בָּזֶה? מִי שֶׁיִּרְצֶה לִשְׁאֹל יוֹם מַה שֶּׁהִצְטָרֵךְ לִפְקֹחַ עֵינָיו, בִּשְׁבִיל לְהַרְאוֹת שֶׁעֲדַיִן הוּא מִזְדַּמֵּן לְהָשִׁיב לְמַרְאֵה הָעוֹלָם הַזֶּה כְּמִקֹּדֶם.</p>"],[9522012354,"<p>אָמַר לוֹ, אִי חָסִיד קָדוֹשׁ, וַדַּאי אִם לֹא נִסְתָּם מִמֶּנּוּ כָּל מַרְאֵה הָעוֹלָם הַזֶּה וְלֹא נֶאֱבָד מִמֶּנּוּ הַכֹּל, לֹא יִהְיֶה לוֹ מַרְאֶה וְחֵלֶק שֶׁל הָעוֹלָם הַהוּא. עוֹלָם זֶה הוּא בְּהִפּוּךְ מֵאוֹתוֹ עוֹלָם שֶׁאָנוּ בוֹ, שֶׁבִּזְמַן תְּחִיַּת הַמֵּתִים אֲפִלּוּ כְּחוּט הַשַּׂעֲרָה לֹא יִהְיֶה מִמַּעֲשֵׂה הָעוֹלָם הַזֶּה, שֶׁהַכֹּל נֶאֱבָד בַּהַתְחָלָה (הטל יבטל אותו וישים אותו) בְּאוֹתוֹ הַטַּל (בהתחלה), וְיָעֳבַר מִמֶּנּוּ כָּל זֻהֲמָה, וְאַחַר כָּךְ יַעֲשֶׂה כְּחֹמֶץ זֶה, וּמִמֶּנּוּ יֵעָשֶׂה הַגּוּף בְּרִיָּה חֲדָשָׁה, כָּךְ כָּאן.</p>\n<p>אָמַר לוֹ רַבִּי שִׁמְעוֹן, וַדַּאי יָדַעְתִּי שֶׁאַתֶּם מְלֻבָּשִׁים שָׁם בִּלְבוּשׁ נִכְבָּד שֶׁל גּוּף זַךְ קָדוֹשׁ. הַאִם הָיָה כְּמוֹ זֶה בָּעוֹלָם הַזֶּה, אָדָם שֶׁנִּרְאֶה בְּאוֹתוֹ גּוּף כְּמוֹ שֶׁאַתֶּם עוֹמְדִים בְּאוֹתוֹ עוֹלָם?</p>\n<p>אָמַר לוֹ, דָּבָר זֶה שָׁאֲלוּ לִפְנֵי רֹאשׁ הַיְשִׁיבָה, שְׁנֵי עֲלָמִים שֶׁהִתְלַבְּשׁוּ בֵינֵינוּ אַחַר שֶׁסָּבְלוּ צַעַר עַל חֵטְא שֶׁלֹּא נִתָּן לְגַלּוֹת, וְשָׁאֲלוּ זֶה לִפְנֵי רֹאשׁ הַיְשִׁיבָה, וְהוּא אָמַר שֶׁזֶּה הָיָה כָּךְ בָּעוֹלָם הַזֶּה. מִנַּיִן לָנוּ? שֶׁכָּתוּב (אסתר ה) וַיְהִי בַּיּוֹם הַשְּׁלִישִׁי וַתִּלְבַּשׁ אֶסְתֵּר מַלְכוּת, הִתְלַבְּשָׁה בְאוֹתָהּ דְּמוּת שֶׁל הָעוֹלָם הַהוּא. מַלְכוּת - זוֹ רוּחַ הַקֹּדֶשׁ, שֶׁהֲרֵי מַלְכוּת הַשָּׁמַיִם נוֹשֶׁבֶת רוּחַ מֵאוֹתָהּ רוּחַ הָאֲוִיר שֶׁל אוֹתוֹ עוֹלָם, וּבָהּ הִתְלַבְּשָׁה אֶסְתֵּר.</p>\n<p>וּכְשֶׁנִּכְנְסָה לִפְנֵי הַמֶּלֶךְ אֲחַשְׁוֵרוֹשׁ וְרָאָה אוֹתוֹ לְבוּשׁ שֶׁל אוֹר, דְּמוּתָהּ נִדְמְתָה לְמַלְאַךְ אֱלֹהִים, וּפָרְחָה מִמֶּנּוּ נִשְׁמָתוֹ לְפִי שָׁעָה. מָרְדְּכַי גַּם כָּךְ, שֶׁכָּתוּב (שם ה) וּמָרְדֳּכַי יָצָא מִלִּפְנֵי הַמֶּלֶךְ בִּלְבוּשׁ מַלְכוּת. לְבוּשׁ מַלְכוּת וַדַּאי, דְּמוּת שֶׁל אוֹתוֹ עוֹלָם. וְעַל זֶה כָּתוּב (שם ט) כִּי נָפַל פַּחַד מָרְדֳּכַי עֲלֵיהֶם. פַּחַד מָרְדֳּכַי, וְלֹא פַּחַד אֲחַשְׁוֵרוֹשׁ. אָמַר רַבִּי שִׁמְעוֹן, כַּמָּה מְתוּקִים דְּבָרִים אֵלּוּ. אַשְׁרֵי חֶלְקִי. וַהֲרֵי יָדַעְתִּי שֶׁצַּדִּיקִים (בזה) בְּאוֹתוֹ עוֹלָם מִתְלַבְּשִׁים בִּלְבוּשׁ שֶׁנִּקְרָא לְבוּשׁ מַלְכוּת, וְכָךְ הוּא וַדַּאי.</p>\n<p>אָמַר לוֹ, אֲוִיר גַּן עֵדֶן, נְשִׁיבַת רוּחַ הַקֹּדֶשׁ הֵם, וּבוֹ מִתְלַבְּשִׁים הַצַּדִּיקִים כְּמוֹ שֶׁהָיוּ בָּעוֹלָם הַזֶּה. וְאַחַר כָּךְ רוּחַ הַקֹּדֶשׁ שׁוֹרָה עַל רֹאשׁ כָּל אֶחָד וְאֶחָד, וּמִתְעַטֵּר וְנַעֲשֵׂית לוֹ עֲטָרָה. וְכָךְ הָיָה לְמָרְדְּכַי, שֶׁכָּתוּב (שם ח) בִּלְבוּשׁ מַלְכוּת, דְּמוּת אוֹתוֹ הָעוֹלָם. אַחַר כָּךְ וַעֲטֶרֶת זָהָב גְּדוֹלָה - זוֹ עֲטֶרֶת שֶׁשּׁוֹרָה עַל רָאשֵׁי הַצַּדִּיקִים בְּאוֹתוֹ עוֹלָם. כְּשֶׁקִּבְּלוּ יִשְׂרָאֵל תּוֹרָה, כְּמוֹ זֶה הָיָה לָהֶם עַד שֶׁחָטְאוּ, שֶׁכָּתוּב בָּהֶם (שמות לג) וַיִּתְנַצְּלוּ בְנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חוֹרֵב. הִתְפַּשְּׁטוּ מֵאוֹתוֹ לְבוּשׁ.</p>\n<p>וְכֵן כָּתוּב בִּיהוֹשֻׁעַ כֹּהֵן גָּדוֹל, (זכריה ג) הָסִירוּ הַבְּגָדִים הַצֹּאִים מֵעָלָיו. וְכָתוּב וַיַּלְבִּישֻׁהוּ בְּגָדִים, אֵלּוּ לְבוּשֵׁי הָעוֹלָם הַהוּא. מִכָּאן דְּבָרִים רִאשׁוֹנִים. וּמִכָּאן, שֶׁכָּל זְמַן שֶׁגּוּף הָעוֹלָם הַזֶּה קַיָּם בַּקֶּבֶר בְּקִיּוּמוֹ, לֹא מִתְלַבֵּשׁ רוּחַ בִּלְבוּשׁ אוֹתוֹ עוֹלָם, שֶׁכָּתוּב וַיָּסִירוּ הַבְּגָדִים הַצּאִים מֵעָלָיו - בַּהַתְחָלָה, וְאַחַר כָּךְ - וַיַּלְבִּישֻׁהוּ בְּגָדִים. וּמַלְאַךְ ה' עֹמֵד. מַה זֶּה עֹמֵד? אֶלָּא זוֹהִי עֲטָרָה שֶׁנִּקְרֵאת מַלְאַךְ ה', שֶׁעוֹמֶדֶת עַל רָאשֵׁי הַצַּדִּיקִים. וְזֶהוּ עֹמֵד, עוֹמֵד עַל הָרֹאשׁ לְמַעְלָה לְאַחַר שֶׁמִּתְלַבְּשִׁים בִּלְבוּשׁ כָּבוֹד זֶה.</p>\n<p>שְׁנֵי גוּפִים כְּאֶחָד לֹא יְכוֹלִים לַעֲמֹד. כָּל זְמַן שֶׁזֶּה קַיָּם, הָרוּחַ לֹא מְקַבֶּלֶת אַחֵר. הָעֳבַר זֶה, הֲרֵי אַחֵר מְזֻמָּן מִיָּד וַדַּאי. זֶה יוֹצֵא וְזֶה נִכְנָס. כְּמוֹ שֶׁיֵּצֶר טוֹב וְיֵצֶר בָּעוֹלָם הַזֶּה לֹא רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁשְּׁנֵיהֶם יַעַמְדוּ כְאֶחָד.</p>\n<p>אָמַר לוֹ, תָּהִינוּ עַל מַה שֶּׁכָּתוּב, וְהַשָּׂטָן עֹמֵד עַל יְמִינוֹ לְשִׂטְנוֹ. וְכִי יְהוֹשֻׁעַ בֶּן יְהוֹצָדָק כָּךְ, שְׁאָר בְּנֵי הָעוֹלָם עַל אַחַת כַּמָּה וְכַמָּה. אָמַר לוֹ, חָסִיד קָדוֹשׁ, כַּמָּה טְמִירִים נִסְתָּרִים הַדְּבָרִים הַלָּלוּ. (אמר לו,) אַף עַל גַּב שֶׁהַחֲבֵרִים יוֹדְעִים בְּדִבְרֵי אוֹתוֹ עוֹלָם, לֹא יְכוֹלִים לָדַעַת בַּסּוֹדוֹת הַלָּלוּ.</p>\n<p>אָמַר לוֹ, כֵּיוָן שֶׁבֶּן אָדָם בְּאוֹתוֹ עוֹלָם, מַה תּוֹעֶלֶת יֵשׁ לְאוֹתוֹ שָׂטָן לְהַשְׂטִינוֹ? וְלֹא דַי לוֹ שֶׁהוֹצִיא נִשְׁמָתוֹ מִמֶּנּוּ וְהָרַג אוֹתוֹ?! אָמַר לוֹ, אִי חָסִיד קָדוֹשׁ, אַשְׁרֵי חֶלְקְךְ. בּא וּרְאֵה, תַּאֲוַת הַשָּׂטָן לֹא הָיְתָה, אֶלָּא כְּדֵי שֶׁלֹּא יִתְלַבֵּשׁ אוֹתוֹ צַדִּיק בִּלְבוּשׁ זַךְ קָדוֹשׁ, שֶׁכֵּיוָן שֶׁרוֹאֶה אוֹתוֹ שָׂטָן שֶׁלְּבוּשׁוֹ נִדְחֶה וְלֹא נֶחְשָׁב, עַל כָּךְ מַסְטֶה אוֹתוֹ. מָה הַטַּעַם? מִשּׁוּם שֶׁאִם יִתְלַבֵּשׁ בְּאוֹתוֹ לְבוּשׁ נִכְבָּד, מִיָּד לְבוּשׁ הַזֻּהֲמָה וּמַעֲשֵׂה אוֹתוֹ שָׂטָן יִתְבַּטֵּל וְיַעֲבֹר מֵהָעוֹלָם, וְלֹא נוֹחַ לוֹ לַשָּׂטָן.</p>\n<p>וְעוֹד, שֶׁבְּכָל זְמַן שֶׁלֹּא הִתְלַבֵּשׁ, פּוֹקֶדֶת הָרוּחַ לְאוֹתוֹ הַגּוּף שֶׁהַזֻּהֲמָה שֶׁלּוֹ, וְנוֹחַ לוֹ לַשָּׂטָן. וְכֵיוָן שֶׁהִתְלַבֵּשׁ בְּאוֹתוֹ לְבוּשׁ נִכְבָּד, הֲרֵי הִתְבַּטְּלוּ גּוֹנֵי יֵצֶר הָרָע וְהַגּוּף שֶׁלּוֹ, וְאֵין לוֹ זִכָּרוֹן עִמּוֹ לְעוֹלָמִים.</p>\n<p>וְאִם תֹּאמַר שֶׁאָנוּ פּוֹקְדִים בָּתֵּי הַקְּבָרוֹת בְּרֹאשׁ כָּל לַיְלָה - לֹא עַל הַגּוּף, אֶלָּא עַל הַנֶּפֶשׁ (שהולכת מערטלת). שֶׁהֲרֵי כָּל זְמַן שֶׁהַבָּשָׂר קַיָּם, הָרוּחַ פּוֹקֶדֶת עַל הַנֶּפֶשׁ, וְהַנֶּפֶשׁ פּוֹקֶדֶת עַל הַגּוּף. אֲבָל עַכְשָׁו פִּקְדוֹנֵנוּ הוּא לַנֶּפֶשׁ, שֶׁהִיא שׁוֹכֶכֶת, וְנִשְׁאֶרֶת שׁוֹכֶכֶת תּוֹךְ הָעֲצָמוֹת. וּמִשּׁוּם זֶה בְּרֹאשׁ כָּל לַיְלָה פִּקְדוֹן הָרוּחַ לַנֶּפֶשׁ, וְלֹא עַל הַבָּשָׂר.</p>"],[9522012355,"<p>אִי חָסִיד קָדוֹשׁ, בֹּא אֲגַלֶּה לְךְ דָּבָר נִסְתָּר. בִּנְיַן גּוּף הָאָדָם כָּךְ הוּא: הָרוּחַ מֵעִם רוּחַ הַקֹּדֶשׁ, הַנְּשָׁמָה מִתּוֹךְ עֵץ הַחַיִּים. כֵּיוָן שֶׁרוּחַ הַקֹּדֶשׁ נָתְנָה כֹּחַ, מִיָּד מַרְכְּבוֹתָיו נוֹתְנִים כֹּחָם. כֹּחָם הוּא עֲצָמוֹת וְאֵיבָרִים. כֻּלָּם מִצִּדָּם, וְתִקּוּנָם זֶה עַל זֶה. הַסִּטְרָא אַחֲרָא נוֹתֶנֶת בָּשָׂר, וּמִצִּדָּהּ בָּא הַבָּשָׂר, וְלֹא דָבָר אַחֵר. מַרְכְּבוֹתֶיהָ נוֹתְנִים כָּל אוֹתָם גִּידִים וְעוֹרְקִים לְהַמְשִׁיךְ דָּם לַבָּשָׂר. אַחֲרֵי שֶׁאֵלֶּה נוֹתְנִים חֵילָם, הַשָּׁמַיִם נוֹתְנִים חֵילָם, וּמִי הֵם? עוֹר שֶׁנִּמְשָׁךְ עַל הַכֹּל כְּמוֹהֶם.</p>\n<p>אַחַר כָּךְ מִתְחַבְּרִים שָׁמַיִם וָאָרֶץ כְּאֶחָד, וְנוֹתְנִים אַרְבָּעָה יְסוֹדוֹת אֵלּוּ: אֵשׁ וּמַיִם וַאֲוִיר וְעָפָר, לְהָגֵן עַל אֵלֶּה וּלְכַסּוֹת עַל הַכֹּל. אַחַר כָּךְ כָּל אֶחָד נוֹטֵל חֶלְקוֹ שֶׁנָּתַן, וְהִתְבַּטֵּל. רוּחַ הַקֹּדֶשׁ וּמַרְכְּבוֹתֶיהָ, חֶלְקָם קַיָּם. רוּחַ הַקֹּדֶשׁ, רוּחוֹ קַיָּם וְהַנְּשָׁמָה עוֹלָה. מַרְכְּבוֹת רוּחַ הַקֹּדֶשׁ עַצְמוֹתֵיהֶם קַיָּמִים, וְעַל זֶה חֲשִׁיבוּת הַגּוּף אֵלּוּ הָעֲצָמוֹת, וּמִשּׁוּם זֶה כָּתוּב (ישעיה נח) וְעַצְמֹתֶיךְ יַחֲלִיץ, וּבָשָׂר לֹא כָתוּב בּוֹ כָּךְ.</p>\n<p>וְכָל זְמַן שֶׁהַבָּשָׂר שֶׁל צַד הָאַחֵר עוֹמֵד בְּקִיּוּמוֹ, אוֹתוֹ שָׂטָן עוֹמֵד לְהַשְׂטִין. אָבַד הַבָּשָׂר, אֵין לוֹ רְשׁוּת לְהַשְׂטִין, שֶׁהֲרֵי אֵין לוֹ עַל מַה שֶּׁיִּסְמֹךְ. וְעַל זֶה כָּתוּב, (איוב לג) יִכֶל בְּשָׂרוֹ מֵרוֹאִי וְשֻׁפּוּ עַצְמֹתָיו לֹא רֻאוּ. מֵאוֹתוֹ מַרְאֵה שָׂטָן שֶׁעוֹמֵד לְהַשְׂטִין שֶׁלֹּא יָכוֹל, כֵּיוָן שֶׁיִּכֶל בְּשָׂרוֹ. וְשֻׁפּוּ עַצְמֹתָיו לֹא רֻאוּ, לֹא רְאוּיִים לִקְרַב אֵלָיו, שֶׁאֵין לוֹ חֵלֶק בָּהֶם, כֵּיוָן שֶׁזָּז כָּל אֶחָד וְאֶחָד מִמְּקוֹמוֹ, לֹא תוֹבֵעַ עֲלֵיהֶם וְלֹא עוֹמֵד לְהַשְׂטִין בִּגְלָלוֹ. לְאַחַר שֶׁמִּתְעַכֵּל הַבָּשָׂר הֲרֵי לֹא יִתְבַּע דִּין וְלֹא עוֹמֵד לְהַשְׂטִין, שֶׁהֲרֵי אֵין לוֹ עַל מַה שֶּׁיִּסְמֹךְ, וְלֹא מַזְכִּיר לָאָדָם בְּשׁוּם דָּבָר שֶׁל הָעוֹלָם. אָמַר רַבִּי שִׁמְעוֹן, כָּעֵת יָדַעְתִּי דְבָרִים עַל תִּקּוּנָם, וַדַּאי נָאֶה הוּא לוֹ לְקַטְרֵג.</p>"],[9522012356,"<p>אָמַר לוֹ רַבִּי (שמעון), חֲגֹר כְּלֵי זֵינְךְ וְהַתְקֵן עַצְמְךְ. אִם תִּרְצֶה לָדַעַת דְּבָרִים שֶׁהִתְחַלְתָּ, אוֹ אִם תִּשְׁאַל בַּדְּבָרִים הָאֵלֶּה, אֱמֹר לִי. אָמַר לוֹ, וַדַּאי, הֲרֵי יָדַעְתִּי שֶׁאִשְׁתִּי מֵתָה, שֶׁלֹּא יָדַעְתִּי מִמֶּנָּה כְלוּם. וְהַחֲבֵרִים יוֹדְעִים. נָשִׁים מָה הַטַּעַם דַּעְתָּן קַלָּה?</p>\n<p>אָמַר לוֹ, הַדַּעַת בָּאָה בְּשֵׁשׁ דְּרָגוֹת, וְכָל אַחַת לוֹקַחַת חֶלְקָהּ, מַה שֶּׁנִּשְׁאָר, הוּא קַל. אֲבָל נִכְבָּדָה זוֹ, אִם לֹא שֶׁאֵשֶׁת כְּסִילוּת מִשְׁתַּתֶּפֶת בָּהּ, בְּדָבָר זֶה אַל תִּשְׁאַל, שֶׁהֲרֵי יָדַעְתִּי שֶׁלֹּא עַל אִשְׁתְּךְ שָׁאַלְתָּ, אֶלָּא עַל מַה שֶּׁכָּתוּב, (ישעיה יט) הִנֵּה ה' רֹכֵב עַל עָב קַל. וְאוֹתוֹ עָב קַל נִקְרָא דַּעַת, מֵאוֹתָהּ כַּלָּה יִרְאַת ה', וְהִיא עוֹמֶדֶת בָּאֶמְצַע כְּמוֹ שֶׁדַּעַת עֶלְיוֹנָה, אֲבָל (ועל זה) נִקְרֵאת קַל. וַהֲרֵי יָדַעְתִּי שְׁאֵלָתְךְ מַהִי.</p>"],[9522012357,"<p>אֲבָל הַתֵּר וַחֲגֹר כְּלֵי זֵינְךְ וּקְשֹׁר קִשְׁרְךְ, שֶׁהֲרֵי זְמַן הוּא לְגַלּוֹת כְּמוֹ שֶׁהִתְחַלְתָּ אֶת הַמַּעֲשֶׂה. שֶׁעַל פְּנֵי רֹחַב הַבַּיִת אוּלַם הָעֲזָרָה לִפְנִים. בַּעֲזָרָה זוֹ יֵשׁ שְׁנֵים עָשָׂר פְּתָחִים לְפִי חֶשְׁבּוֹן שִׁבְטֵי יִשְׂרָאֵל. בְּפֶתַח אֶחָד כָּתוּב רְאוּבֵן, בְּפֶתַח אַחֵר כָּתוּב שִׁמְעוֹן, וְכֵן כָּל שִׁבְטֵי יִשְׂרָאֵל רְשׁוּמִים עַל אוֹתָם פְּתָחִים בִּזְמַן שֶׁיַּעֲלוּ לְהֵרָאוֹת לִפְנֵי רִבּוֹן הָעוֹלָם. מִי שֶׁיִּכָּנֵס בַּפֶּתַח שֶׁרָשׁוּם בּוֹ רְאוּבֵן - אִם מִשֵּׁבֶט רְאוּבֵן הוּא, הַפְּתָחִים מְקַבְּלִים אוֹתוֹ. וְאִם לֹא, פּוֹלְטִים אוֹתוֹ הַחוּצָה. וְכֵן בְּכֻלָּם, שֶׁלֹּא יְקַבְּלוּ הַפְּתָחִים אֶלָּא לְמִי שֶׁהוּא מֵאוֹתוֹ שֵׁבֶט שֶׁרָשׁוּם בָּהֶם, וּבָזֶה יִתְחַקְּקוּ וְיִוָּדְעוּ כָּל אֶחָד וְאֶחָד.</p>\n<p>שְׁלֹש מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה עַמּוּדֵי אוֹר לוֹהֵט יֵשׁ בְּכָל צַד מֵאוֹתָם אַרְבָּעָה צְדָדִים. כָּל הָעַמּוּדִים הַלָּלוּ נִקְרָאִים עַמּוּדִים חַיִּים, מִשּׁוּם שֶׁלֹּא עוֹמֵד אוֹרָם שׁוֹכֵךְ בְּמָקוֹם אֶחָד. וְכֻלָּם, אֵלּוּ עוֹלִים וְאֵלּוּ יוֹרְדִים, נוֹתְנִים מָקוֹם זֶה לָזֶה. אֵלּוּ שֶׁעוֹלִים מַכִּים זֶה בָּזֶה וּמְנַגְּנִים נִגּוּן, וְאֵלֶּה שֶׁיּוֹרְדִים גַּם כָּךְ. אֵלֶּה שֶׁעוֹלִים שֶׁמְּנַגְּנִים נִגּוּן, אֵיזֶה נִגּוּן מְנַגְּנִים? שִׁיר יָתוֹם. (תהלים צח) מִזְמוֹר שִׁירוּ לַה' שִׁיר חָדָשׁ כִּי נִפְלָאוֹת עָשָׂה וְגוֹ'. שִׁיר חָדָשׁ, וְכִי יֵשׁ שִׁיר עַתִּיק? אֶלָּא שִׁיר, שֶׁעַד כָּעֵת מַלְאָכִים קְדוֹשִׁים לֹא שִׁבְּחוּ לוֹ, מִשּׁוּם שֶׁהוּא חָדָשׁ. מָה הַטַּעַם הוּא חָדָשׁ? בִּגְלַל אוֹתוֹ אֶחָד שֶׁמְּחַדֵּשׁ עֲלוּמָיו, מְשַׁבְּחוֹ וְאוֹמֵר לוֹ. וְכָךְ אָמַר רֹאשׁ הַיְשִׁיבָה, זֶה נִקְרָא חָדָשׁ וְהוּא חָדָשׁ, מִשּׁוּם שֶׁדָּבֵק בַּשֶּׁמֶשׁ וְלֹא נִפְרָד מִמֶּנּוּ. לְהוֹצִיא סִטְרָא אַחֲרָא שֶׁאֵין בָּהּ חִדּוּשׁ, שֶׁכָּתוּב בָּהּ (קהלת א) וְאֵין כָּל חָדָשׁ. זָקֵן הוּא וּבָלֶה, וְלֹא הִתְחַדֵּשׁ. (ולא עושה תולדות. ואלמלא עשה תולדות, היה מטשטש העולם).</p>\n<p>עוֹד פָּתַח רֹאשׁ הַיְשִׁיבָה. שָׂרָה הִתְחַדְּשָׁה בְעִדּוּן, דַּרְגָּתָהּ גָּרְמָה, שֶׁכָּתוּב (בראשית יח) אַחֲרֵי בְלֹתִי הָיְתָה לִּי עֶדְנָה. מַה זֶּה עֶדְנָה? מְשִׁיכַת עֵדֶן הָעֶלְיוֹן. וּמִשּׁוּם שֶׁנִּמְשַׁךְ עָלֶיהָ מִצַּד נְקֵבָה, כָּתוּב עֶדְנָה בְּהֵ\"א, וּמִשּׁוּם זֶה כָּתוּב הָיְתָה, וְלֹא הָיָה.</p>\n<p>וַאדֹנִי זָקֵן. וְכִי אַף עַל גַּב שֶׁהוּא זָקֵן לֹא רָאוּי לְהוֹלִיד? אֶלָּא לֹא דָבָר קָטָן אָמְרָה עָלָיו, (שאברהם אלא) שֶׁבִּגְלַל (להקטין עצמה שנדבקה) אוֹתוֹ (מלך) זָקֵן (שנדבקה) (וכסיל), לֹא מִתְחַדֵּשׁ וְלֹא עוֹשֶׂה תוֹלָדוֹת, שֶׁאִלְמָלֵא הָיָה עוֹשֶׂה תוֹלָדוֹת, הָיָה מְטַשְׁטֵשׁ אֶת הָעוֹלָם. (אלא אמרה על אברהם, בגלל שהוא זקן לא יתחדש ולא יעשה תולדות) וְעַל זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא הֶחֱזִיר דְּבָרִים, לָמָּה זֶּה צָחֲקָה שָׂרָה וְגוֹ'. וְאִם תֹּאמַר, וַהֲרֵי כָּתוּב (שם כד) וְאַבְרָהָם זָקֵן בָּא בַּיָּמִים? אֶלָּא בָּא בַּיָּמִים, בְּאוֹתָם יָמִים עֶלְיוֹנִים שֶׁמְּחַדְּשִׁים עֲלוּמִים כַּנֶּשֶׁר. וְעַל זֶה נִגּוּן זֶה נִגּוּן שֶׁל אוֹתוֹ חָדָשׁ הוּא. הוֹשִׁיעָה לּוֹ, לְמִי? לְאוֹתוֹ חָדָשׁ, הוֹשִׁיעָה יְמִין הַמֶּלֶךְ הָעֶלְיוֹן וּזְרוֹעוֹ.</p>\n<p>אוֹתָם שֶׁיּוֹרְדִים גַּם כֵּן מְנַגְּנִים, וְאוֹמְרִים שִׁירָה יְתוֹמָה אַחֶרֶת. וּמַהִי? (תהלים ק) מִזְמוֹר לְתוֹדָה, שֶׁהוּא יָתוֹם, גַּם כָּךְ.</p>\n<p>אוֹרָם אֶחָד נִרְאֶה. וּכְשֶׁמִּתְגַּלְגֵּל, נִרְאִים חֲמִשָּׁה גְוָנִים שֶׁל אוֹרוֹת בְּכָל עַמּוּד וְעַמּוּד. הָעַמּוּדִים הַלָּלוּ כֻּלָּם חֲלוּלִים מִבִּפְנִים, וּכְשֶׁעוֹלִים וְיוֹרְדִים, יוֹצְאִים מֵהֶם שַׁלְהֲבוֹת אֵשׁ, כְּצוּרוֹת כַּפְתּוֹר וָפֶרַח. מֵעַל כָּל עַמּוּד וְעַמּוּד יֵשׁ שְׁלֹשָׁה תַפּוּחִים שֶׁמַּכִּים בָּהֶם שְׁלֹשָׁה גְוָנִים, אָדם יָרֹק וְלָבָן. בְּכָל גָּוֶן וְגָוֶן לוֹהֲטוֹת אוֹתִיּוֹת בּוֹלְטוֹת מִשַּׁלְהֶבֶת יְרֻקָּה שֶׁל אֵשׁ, וְלֹא שׁוֹכְכִים לְעוֹלָמִים, וְאֵין מִי שֶׁיָּקוּם עֲלֵיהֶם.</p>\n<p>אַרְבָּעָה גַלְגַּלִּים תּוֹחֲמִים מַעֲשֵׂה צִיּוּר בְּכָל עַמּוּד וְעַמּוּד. בְּאוֹתָם גַּלְגַּלִּים יֵשׁ פְּלִיאוֹת גְּדוֹלוֹת. כְּשֶׁמִּסְתּוֹבְבִים, מוֹצִיאִים מֵהֶם זַגִּים שֶׁל זָהָב וַאֲבָנִים יְקָרוֹת. וּמִיָּד מִתְכַּנְּסִים בְּתוֹכָם וְלֹא נוֹפְלִים לָאָרֶץ. כְּשֶׁיּוֹצְאִים אוֹתָם זַגֵּי זָהָב וְאוֹתָם אֲבָנִים יְקָרוֹת תּוֹךְ סִבּוּב הַגַּלְגַּלִּים, נִשְׁמָע קוֹל שֶׁאוֹמְרִים: (ישעיה נד) זֹּאת נַחֲלַת עַבְדֵי ה' וְצִדְקָתָם מֵאִתִּי נְאֻם ה'.</p>\n<p>שְׁנֵי אֲרָיוֹת בְּכָל גַּלְגַּל וְגַלְגַּל, אַרְיֵה אֶחָד מִצַּד אֶחָד, וְאַרְיֵה אֶחָד מִצַּד אֶחָד, וְכֻלָּם מֵאֵשׁ יְרֻקָּה, וּבַגִּלְגּוּל שֶׁמִּסְתּוֹבְבִים הַגַּלְגַּלִּים מִתְחַבְּקִים אֵלֶּה בְאֵלֶּה, וְהוֹלְכִים כֻּלָּם בְּגִלְגּוּל, מִתְדַּבְּקִים זֶה בָּזֶה. כְּשֶׁעוֹלִים הָעַמּוּדִים, נוֹהֲמִים הָאֲרָיוֹת אֵלֶּה בְאֵלֶּה, וְהַתַּפּוּחִים פּוֹרְחִים בָּאֲוִיר וְעוֹלִים לְמַעְלָה וּמַכִּים אֵלֶּה בְאֵלֶּה בָּאֲוִיר. וְשָׁבִים לִמְקוֹמוֹתֵיהֶם, וּמִשָּׁם נוֹפְלִים. וְהָאֲרָיוֹת פּוֹשְׁטִים יְדֵיהֶם לְקַבְּלָם, וְעוֹלִים אֵלֶּה מֵעַצְמָם. אִי חָסִיד קָדוֹשׁ, מִי רָאָה חָכְמַת הָאָמָּנוּת שֶׁצִּיֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעַמּוּדִים הַלָּלוּ?</p>\n<p>בַּחֲצוֹת הַיּוֹם יוֹצְאִים שְׁנֵי נְשָׁרִים בְּכָל גַּלְגַּל וְגַלְגַּל, וְלֹא יָדוּעַ מָקוֹם שֶׁמִּשָּׁם יוֹצְאִים, וְשׁוֹרִים עַל רֹאשׁ הָאֲרָיוֹת הַלָּלוּ, וְאָז שׁוֹכְכִים הָעַמּוּדִים וְהַגַּלְגַּלִּים, וְעוֹמְדִים בְּקִיּוּמָם. וְהַתַּפּוּחִים נוֹפְלִים עַל פִּיהֶם שֶׁל הַנְּשָׁרִים, וּמְקַבֶּלֶת אוֹתָם. וּמִיָּד פּוֹרְחִים מִפֶּה לְפֶה, וְהוֹלְכִים וּמְשׁוֹטְטִים בֵּינֵיהֶם, וְשָׁבִים לִמְקוֹמוֹתֵיהֶם, וְלֹא יָדוּעַ מִי הִיא. לְאַחַר שָׁעָה וָחֵצִי מְרִימִים הַנְּשָׁרִים קוֹל, וּמְנַגְּנִים נִגּוּן מָתוֹק, וְנִסְתָּרִים, וְלֹא יָדוּעַ בְּאֵיזֶה מָקוֹם.</p>"],[9522012358,"<p>סְבִיב אוֹתָם הָעַמּוּדִים יֵשׁ שְׂבָכִים מַעֲשֵׂה צִיּוּר. אֵשׁ אֲדֻמָּה וְאוֹר לָבָן וְחוּטֵי זָהָב סָבִיב סָבִיב סוֹבְבִים לְכָל צַד, וּמַעְיַן מַיִם, כְּמוֹ שֶׁנֶּאֱמַר (זכריה יד) וְהָיָה בַּיּוֹם הַהוּא יֵצְאוּ מַיִם חַיִּים מִירוּשָׁלם חֶצְיָם אֶל הַיָּם הַקַּדְמוֹנִי וְחֶצְיָם אֶל הַיָּם הָאַחֲרוֹן.</p>\n<p>כָּאן פֵּרַשׁ רֹאשׁ הַיְשִׁיבָה פָּסוּק זֶה לְפָנִים, וְקוֹלוֹ נִשְׁמַע הַחוּצָה. מִשֶּׁהָיָה מְפָרֵשׁ פָּסוּק זֶה, (אי קדוש, אי קדוש) קוֹל תִּינוֹק הִתְעוֹרֵר מִבַּחוּץ, אוֹתוֹ תִּינוֹק שֶׁהָיָה מְפָרֵשׁ תַּלְמוּדוֹ, וְלָמַד לִפְנֵי עַמּוּד אֶחָד שֶׁל הָעוֹלָם, בְּנוֹ שֶׁל רַבִּי יְהוּדָה שֶׁגִּדַּלְתָּ. וְאָחֲזוּ בוֹ לְדִין, וְקוֹלוֹ הִתְעוֹרֵר מִבַּחוּץ בְּפָסוק זֶה, וְאָמַר, מַיִם שֶׁהֵם מִלְּמַטָּה, אֵיךְ יַעֲלוּ לְמַעְלָה מִמֶּנּוּ, לְמָקוֹם עֶלְיוֹן יוֹתֵר מִמֶּנּוּ בְּכַמָּה מַעֲלוֹת? וּמַה צָּרִיךְ לְאוֹתָם מַיִם לְמַעְלָה? וּמַה מָּקוֹם שֶׁכָּל (תפוחי) הַמַּבּוּעִים וְהַנְּחָלִים יוֹצְאִים מִמֶּנּוּ, וְאֵין הֶפְסֵק לַמַּבּוּעִים וְהַנְּחָלִים, הֻשְׁקָה מִמָּקוֹם יָבֵשׁ? מִי רָאָה חֲפִירַת הַבְּאֵר נוֹתֵן מַיִם לַמַּבּוּעַ שֶׁנּוֹבֵעַ? וְכִי יְרוּשָׁלַיִם תִּתֵּן מַיִם אֶל הַיָּם הַקַּדְמוֹנִי, מָקוֹם שֶׁכָּל מֵימֵי הָעוֹלָם יוֹצְאִים מִשָּׁם וְנוֹבְעִים מִשָּׁם? אִי חָסִיד קָדוֹשׁ, לְקוֹל זֶה שָׁכְכוּ וְשָׁמְעוּ כָּל קוֹלוֹת בְּנֵי הַיְשִׁיבָה שֶׁל שָׁם, וּמִשּׁוּם זֶה לֹא יָכְלוּ בַּעֲלֵי הַדִּין לִקְרַב אֵלָיו.</p>\n<p>בָּכָה רַבִּי שִׁמְעוֹן, אָמַר לוֹ, אַל תִּבְכֶּה מְנוֹרָה הַקְּדוֹשָׁה, אַשְׁרֵי חֶלְקְךְ שֶׁאֲפִלּוּ תִינוֹקוֹת מִמְּךְ אוֹמְרִים סוֹדוֹת נִסְתָּרִים שֶׁל הַתּוֹרָה. בֹּא וְאֹמַר לְךְ מַה שֶּׁעָשׂוּ בְּנֵי הַיְשִׁיבָה עַל קוֹל אוֹתוֹ תִּינוֹק. כְּשֶׁנִּכְנַס קוֹל אוֹתוֹ תִּינוֹק כְּחֵץ פְּנִימָה וְכֻלָּם הִקְשִׁיבוּ לוֹ, בְּאוֹתָהּ שָׁעָה הִזְדַּעֲזַע רֹאשׁ הַיְשִׁיבָה וְכָל אֵלּוּ שֶׁהָיוּ לְפָנָיו, וְאָמַר, מִי אֵלּוּ שֶׁלֹּא הִשְׁאִירוּ אֶת אוֹתוֹ בֶּן אֱלֹהִים חַיִּים לְהִכָּנֵס? קָמוּ וְאָחֲזוּ בוֹ שְׁלֹשָׁה עַמּוּדִים שֶׁעוֹמְדִים לִפְנֵי רֹאשׁ הַיְשִׁיבָה, וְנִכְנַס, וְכָל בְּנֵי הַיְשִׁיבָה נִכְנְסוּ אֵלָיו. אָמַר רֹאשׁ הַיְשִׁיבָה, פְּסֹק פְּסוּקְךְ בֵּן קָדוֹשׁ!</p>\n<p>אָמַר, עַד כָּעֵת פָּחַדְתִּי, שֶׁהֲרֵינִי מִישִׁיבָה אַחֶרֶת, וְכָךְ אָמְרוּ לִי כְּשֶׁבַּעֲלֵי הַדִּין אָחֲזוּ בוֹ. אָמַר לוֹ, אַל תִּפְחַד בֵּן קָדוֹשׁ, כָּאן תִּהְיֶה בֵּינֵינוּ שִׁבְעָה יָמִים, וְתִתְרַחֵץ בְּכָל יוֹם מִטַּל הַקָּדוֹשׁ, וְאַחַר כָּךְ יַעֲלוּ אוֹתְךְ לְתוֹךְ אוֹתָהּ יְשִׁיבָה כִּשְׁאָר הַתִּינוֹקוֹת מִכָּאן.</p>\n<p>פָּתַח אוֹתוֹ תִּינוֹק וְאָמַר, וְהָיָה בַּיּוֹם הַהוּא, הַהוּא - לֹא יָדוּעַ מִיהוּ. אֶלָּא בְּכָל מָקוֹם בַּיּוֹם הַהוּא, יוֹם אַחֲרוֹן הוּא. לָמָּה נִקְרָא יוֹם הַהוּא? אֶלָּא זֶהוּ יוֹם שֶׁאוֹחֵז סוֹף בָּרֹאשׁ. רֵאשִׁית נִקְרָא הוּא, כְּמוֹ שֶׁנֶּאֱמַר (במדבר יח) וְעָבַד הַלֵּוִי הוּא. עֲבוֹדַת הַלֵּוִי לְדַרְגָּה שֶׁנִּקְרֵאת הוּא, טָמִיר וְגָנוּז. וְנִקְרָא הַהוּא (ה' הוא), לְהַרְאוֹת סוֹף כָּל הַמַּעֲלוֹת, שֶׁהִיא רֵאשִׁית, וְהַכֹּל אֶחָד. וּמִשּׁוּם שֶׁהוּא סוֹף, הִתּוֹסֵף בּוֹ ה'. (הלוי הוא טמיר וגנוז. ונקרא יום ההוא, להראות סוף של כל הדרגות, שאחוז תחלה, והכל אחד).</p>\n<p>עָתִידָה יְרוּשָׁלַיִם לְהוֹצִיא מַיִם וְלִנְבֹּעַ מַבּוּעַ. כָּאן יֵשׁ לוֹמַר, סוֹף לְכָל הַדְּרָגוֹת אֵינָהּ יְרוּשָׁלַיִם, אֶלָּא וַדַּאי יְרוּשָׁלַיִם וְיוֹם הַהוּא, הַכֹּל אֶחָד. מַה בֵּין זֶה לָזֶה? אֶלָּא יְרוּשָׁלַיִם, כָּל הַדְּרָגוֹת הַקְּדוֹשׁוֹת שֶׁלָּהּ, כְּשֶׁסּוֹבְבִים נִקְרָאִים יְרוּשָׁלַיִם, וְכָךְ נִרְאִים. וְיֵשׁ דְּרָגוֹת שֶׁסּוֹבְבוֹת, וְנִקְרָאוֹת עֲזָרוֹת. אֵלֶּה פְּנִימִיּוֹת וְאֵלֶּה בַּחוּץ. וְיֵשׁ דְּרָגוֹת שֶׁנִּקְרָאוֹת כְּשֶׁסּוֹבְבוֹת לְשָׁכוֹת. (כשמסתובבות אלו הפנימיות ואלו לבחוץ, נקראו ירושלים. ויש דרגות שסובבות, ונקראות עזרות. ויש דרגות שנקראות לשכות) וְיֵשׁ דְּרָגוֹת שֶׁנִּקְרָאוֹת כְּשֶׁסּוֹבְבוֹת הֵיכָל וּדְבִיר. לִפְנִים מִכָּל אֵלּוּ הַדְּרָגוֹת יֵשׁ נְקֻדָּה אַחַת, (תהלים מה) כְּבוּדָּה בַת מֶלֶךְ פְּנִימָה. נְקֻדָּה זוֹ נִקְרֵאת יוֹם הַהוּא, וְסִימָנְךְ - (דברים ג) הַהוּא יִקָּרֵא אֶרֶץ.</p>\n<p>וּכְשֶׁיַּעָמֹד יוֹם זֶה מִתּוֹךְ שִׂבְכֵי הָעֲזָרָה, תָּקוּם נְבִיעַת מַיִם, וְאוֹתָהּ נְבִיעָה תִּהְיֶה מֵהַיָּם הַקַּדְמוֹנִי, כְּמוֹ אִמָּא שֶׁבְּנָהּ בֵּין זְרוֹעוֹתֶיהָ, וּמֵרֹב חָלָב שֶׁיּוֹנֵק, מִתְמַלֵּא פִיו וְנִתְגַּדֵּל בּוֹ, מֵרִיק חָלָב לְפִי אִמּוֹ. כָּךְ חֶצְיָם אֶל הַיָּם הַקַּדְמוֹנִי.</p>\n<p>לְקָחוֹ רֹאשׁ הַיְשִׁיבָה וּנְשָׁקוֹ. אָמַר, חַיֶּיךְ (חיי עולם שדבר זה כך), כָּךְ פֵּרְשׁוּהוּ בִּישִׁיבַת הָרָקִיעַ, וְכָךְ זֶה וַדַּאי. יָם הָאַחֲרוֹן - מַעֲלוֹת אַחֲרוֹנוֹת שֶׁלָּהּ. אִי חָסִיד קָדוֹשׁ, כַּמָּה חֶדְוָה עַל חֶדְוָה נִתּוֹסְפָה בְּאוֹתוֹ תִּינוֹק תּוֹךְ בְּנֵי הַיְשִׁיבָה. עֶשְׂרִים וְשֶׁבַע טַעֲמֵי הַתּוֹרָה, אָמַר אוֹתוֹ תִּינוֹק. וְשִׁבְעִים כְּתָרִים עִטְּרוּ לְאָבִיו בְּאוֹתוֹ יוֹם. אַשְׁרֵי חֶלְקוֹ מִי שֶׁזּוֹכֶה לְלַמֵּד אֶת בְּנוֹ. אָמַר רַבִּי שִׁמְעוֹן, לֹא זָכָה אָבִיו לְלַמֵּד. אָמַר, אָבִיו הִשְׁאִיר.</p>\n<p>וְסוֹד נִסְתָּר הָיָה בְּתִינוֹק זֶה עַל מַה שֶּׁהִסְתַּלֵּק מֵהָעוֹלָם וְעַל שֶׁרָצוּ לָדוּן דִּינוֹ (בגלוי) וְנִצַּל מִמֶּנּוּ. זֶה הָיָה בְגִלּוּי, שֶׁהָיָה מְבַיֵּשׁ לְרַבּוֹ לִפְנֵי הַכֹּל בִּשְׁאֵלוֹת וְקֻשְׁיוֹת שֶׁלּוֹ, וְלֹא חָשַׁשׁ לָלֶכֶת לְאַחֵר לְהַתְקִין תַּלְמוּדוֹ, וְהֶחֱלִישׁ דַּעַת רַבּוֹ, וְלָכֵן רָצוּ לָדוּן אוֹתוֹ בְּדִין קָשֶׁה. וּמִשּׁוּם כָּךְ, אַף עַל גַּב שֶׁנִּצַּל מִבַּעֲלֵי הַדִּין, לֹא נִצַּל כָּאן. שִׁבְעָה יָמִים הָיוּ שֶׁלֹּא הִשְׁתַּלֵּם דְּיוֹקְנוֹ (דינו). וּכְשֶׁהָיָה מִתְרַחֵץ, בִּכְאֵב יָתֵר לִפְנֵי הַכֹּל כָּל אוֹתָם שִׁבְעָה יָמִים עַד שֶׁהִשְׁתַּלֵּם דְּיוֹקְנוֹ. וְעַל שֶׁהִסְתַּלֵּק מֵהָעוֹלָם לֹא תִרְצֶה לָדַעַת. אִי רַבִּי, אִי רַבִּי, אַשְׁרֵי חֶלְקְךְ!</p>\n<p>בֹּא וּרְאֵה, תַּחַת הָעִגּוּל שֶׁל אוֹתָם שְׂבָכִים שֶׁשָּׁם, בְּאוֹתָם מַיִם שֶׁל אוֹתוֹ מַבּוּעַ הַמַּעְיָן, נִרְשָׁם מַבּוּעַ אֶחָד, וּמִתְפַּשֵּׁט וְיוֹצֵא הַחוּצָה, וְנִכְנָס לְתוֹךְ הַיָּם הַגָּדוֹל, (ששם) וְרוֹשֵׁם בּוֹ דֶּרֶךְ בְּלֵב הַיָּם, וּמִמֶּנּוּ שׁוֹתֶה לִוְיָתָן וְרָוֶה וְשָׂמֵחַ, וּמִתְרַבֶּה בְרִבּוּי. וּכְשֶׁיּוֹצֵא מַבּוּעַ אַחֵר, אוֹתוֹ מַבּוּעַ מִתְפַּשֵּׁט וְהוֹלֵךְ בַּסֵּתֶר תַּחַת הַתְּהוֹם לְתוֹךְ הַיָּם הָאַחֲרוֹן. וְכָל אוֹתָם מַיִם זֵידוֹנִים וּמַיִם תַּקִּיפִים מַנְמִיךְ אוֹתָם וּמְכוֹפֵף אוֹתָם שֶׁלֹּא יֵצְאוּ לְחַבֵּל בִּבְנֵי הָעוֹלָם. וְסִימָן - (ישעיה מג) הַנּוֹתֵן בַּיָּם דָּרֶךְ וּבְמַיִם עַזִּים נְתִיבָה.</p>\n<p>וּבְאֶמְצַע אוֹתָהּ עֲזָרָה יֵשׁ שְׁנֵי כְרוּבִים, מַעֲשֵׂה אָמָּנוּת שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ, וְלֹא יְכוֹלִים לַעֲמֹד בָּהֶם עֶלְיוֹנִים וְתַחְתּוֹנִים. וְתַחְתֵּיהֶם עֲתִידִים כָּל יִשְׂרָאֵל לַעֲמֹד, שֶׁלֹּא יֵצְאוּ מִתַּחַת כַּנְפֵיהֶם הַחוּצָה, זַכָּאִים יִהְיוּ כָּל הַנִּכְנָס תַּחַת כַּנְפֵיהֶם. שְׁלֹשָׁה עָשָׂר אֶלֶף מִגְדָּלִים שֶׁל שֶׁמֶשׁ שֶׁמֵּאִיר מִנִּיצוֹץ שֶׁל מַרְגָּלִית בְּצַעֲצוּעַ (בניצוץ) כָּרָאוּי. רֹאשׁ הַיְשִׁיבָה בִּגְלַל זֶה זָכָה לְאוֹתוֹ כָּבוֹד.</p>"],[9522012359,"<p>מִי יָכוֹל לוֹמַר מֵאוֹתָם דְּבָרִים שֶׁמִּתְחַדְּשִׁים בְּכָל יוֹם מִלִּפְנֵי רֹאשׁ הַיְשִׁיבָה. אִי רַבִּי, בְּכָל זְמַן שֶׁרוּחוֹת זְכָרִים עוֹלוֹת לְמַעְלָה, נָשִׁים בְּאוֹתוֹ זְמַן יוֹצְאוֹת כֻּלָּן, וּמִתְכַּנְּסוֹת לְתוֹךְ הַהֵיכָל שֶׁשָּׁם בַּתְיָה, וּשְׂמֵחוֹת שָׁם בְּכַמָּה דְבָרִים עַתִּיקִים. וּמִשָּׁם יוֹצְאוֹת, וְנִכְנָסוֹת כֻּלָּן, וְהִיא עִמָּהֶן, לְתוֹךְ הֵיכַל סֶרַח, וּשְׂמֵחוֹת בְּכַמָּה דְבָרִים חֲדָשִׁים וְעַתִּיקִים, וּמִשָּׁם יוֹצְאוֹת וְהִיא עִמָּהֶן, וְנִכְנָסוֹת לְתוֹךְ הֵיכַל יוֹכֵבֶד. וְכֵן בְּכָל אוֹתָם הֵיכָלוֹת.</p>\n<p>כָּעֵֹת, רַבִּי, אֹמַר לְךְ סוֹד אֶחָד. בֹּא וּרְאֵה, בְּכָל שְׁמִטָּה וּשְׁמִטָּה הַכָּרוֹז יוֹצֵא: הִתְכַּנְּסוּ גְבָרִים וְנָשִׁים וְכָל אוֹתָם בְּנֵי הָאֱמוּנָה וַעֲלוּ. אָז כֻּלָּם מִתְפַּשְּׁטִים, זְכָרִים וְנָשִׁים, וְעוֹלִים. וְכָל אוֹתָם תִּינוֹקוֹת מֵחָלָב נִכְנָסִים לְתוֹךְ יְשִׁיבַת (התכנסו בני האמונה גברים ונשים, וכל אותם יונקי חלב, ועלו. אז כלם מתפשטים, גברים ונשים, ועולים. וכלם נכנסים לתוך ישיבת) הָרָקִיעַ, וּשְׂמֵחִים בְּחֶדְוָה וְעִלּוּי שֶׁלָּהֶם, וְשָׁם שִׂמְחָה עַל שִׂמְחָה. וְאוֹתוֹ נַעַר שֶׁמַּפְתְּחוֹת רִבּוֹנוֹ בְיָדוֹ עוֹמֵד, וְאוֹמֵר לָהֶם כַּמָּה דְבָרִים חֲדָשִׁים וְעַתִּיקִים, וְכֻלָּם רוֹאִים שִׂמְחָה שֶׁאֵין שִׂמְחָה כְּאוֹתָהּ שִׂמְחָה.</p>\n<p>אַחַר כָּךְ נִכְנָסִים כֻּלָּם לְתוֹךְ כַּמָּה פָרוֹכוֹת, וְכַמָּה הֵיכָלוֹת גְּנוּזִים שָׁם, שֶׁהֵם מְאִירִים בְּנֹעַם ה' בְּתוֹךְ הֵיכַל אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְזֶהוּ שֶׁכָּתוּב (תהלים כז) לַחֲזוֹת בְּנֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ. אַחַר כָּךְ פּוֹרְחִים הַתִּינוֹקוֹת לְמַעְלָה, וְהֵם פּוֹרְחִים לְמַטָּה, וְחוֹזְרִים לִמְקוֹמוֹתֵיהֶם וּמִתְלַבְּשִׁים כְּבַתְּחִלָּה. אַשְׁרֵי הָעָם שֶׁלְּכָל טוּב אוֹתוֹ עוֹלָם מְצַפִּים.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כַּמָּה מְתוּקִים הַדְּבָרִים שֶׁשָּׁמַעְנוּ. אַשְׁרֵי חֶלְקִי שֶׁזָּכִיתִי לְכָל לִשְׁמֹעַ אֶת כָּל זֶה. אַשְׁרֵי הַיּוֹם שֶׁיָּצָאתִי לְכָאן. אָמְרוּ לוֹ, רַבִּי, שְׁלֹשָׁה יָמִים יֵשׁ לָנוּ רְשׁוּת לָבא אֵלֶיךְ, וְאַחַר כָּךְ יוֹם אֶחָד (נלך, ואין לנו רשות לבא. באותו יום נוספת) שִׂמְחָה שֶׁלְּךְ.</p>"],[9522012360,"<p>הוּא מוֹשֵׁךְ מְשִׁיכוּת מִצִּדּוֹ, וְנִסְתָּר וּמִתְכַּסֶּה תַחַת מָקוֹם שֶׁנִּקְרָא תָּא הָרָצִים עַד חֲצוֹת הַלַּיְלָה. מֵאַחַר חֲצוֹת הַלַּיְלָה יוֹצֵאת שַׁלְהֶבֶת עַמּוּד יִצְחָק, וּמַכָּה בַּתַּרְנְגוֹל הַזֶּה שֶׁנִּקְרָא גֶבֶר, כְּמוֹ גֶבֶר אַחֵר עֶלְיוֹן מִמֶּנּוּ. כֵּיוָן שֶׁמַּכֶּה בּוֹ גֶּבֶר זֶה, קוֹרֵא וְנוֹתֵן שִׁשָּׁה קוֹלוֹת, וְכֻלָּם בְּהַשְׂכֵּל.</p>\n<p>בְּשָׁעָה שֶׁהוּא קוֹרֵא, כָּל תַּרְנְגוֹלֵי הָעוֹלָם הַזֶּה קוֹרְאִים, וְיוֹצֵאת מִמֶּנּוּ שַׁלְהֶבֶת אַחֶרֶת וּמַגִּיעָה תַחַת כַּנְפֵיהֶם, וְקוֹרְאִים. מַה הוּא קוֹרֵא? בְּשָׁעָה רִאשׁוֹנָה קוֹרֵא וְאוֹמֵר: (תהלים כט) קוֹל ה' בַּכֹּחַ קוֹל ה' בֶּהָדָר. וּבְשָׁעָה שְׁנִיָּה קוֹרֵא וְאוֹמֵר: (מיכהו) קוֹל ה' לָעִיר יִקְרָא, (תהלים כט) קוֹל ה' שֹׁבֵר אֲרָזִים. בְּשָׁעָה שְׁלִישִׁית קוֹרֵא וְאוֹמֵר: קוֹל ה' חֹצֵב לַהֲבוֹת אֵשׁ. בְּשָׁעָה רְבִיעִית קוֹרֵא וְאוֹמֵר: קוֹל ה' יָחִיל מִדְבָּר וְגוֹ'. בְּשָׁעָה חֲמִישִׁית קוֹרֵא וְאוֹמֵר: קוֹל ה' עַל הַמָּיִם וְגוֹ'. בְּשָׁעָה שִׁשִּׁית קוֹרֵא וְאוֹמֵר: קוֹל ה' יְחוֹלֵל אַיָּלוֹת וְגוֹ'. וְאַחַר כָּךְ קוֹרֵא וְאוֹמֵר: (ישעיה מ) קוֹל אֹמֵר קְרָא וְאָמַר מָה אֶקְרָא וְגוֹ'. וְזֶהוּ הַתַּרְנְגוֹל שֶׁקּוֹרֵא וְלֹא שׁוֹכֵךְ, וְאַחַר כָּךְ קוֹרֵא כְּמוֹ מִקֹּדֶם.</p>\n<p>וּמַה קּוֹרֵא? כָּל מַעֲשֵׂי בְּנֵי הָעוֹלָם, מִשּׁוּם שֶׁהוּא בַּעַל הַתִּיק (שלהחכמה) וְקֶסֶת הַסּוֹפֵר בְּמָתְנָיו, וְכָל מַעֲשֵׂי בְּנֵי הָעוֹלָם כּוֹתֵב בְּכָל יוֹם. וּבַלַּיְלָה לְאַחַר שֶׁקּוֹרֵא כָּל הַקְּרִיאוֹת הַלָּלוּ, קוֹרֵא כָּל מַה שֶּׁכָּתַב בַּיּוֹם.</p>\n<p>וְאִלְמָלֵא רַגְלָיו אֶצְבָּעוֹת שֶׁלּוֹ, שֶׁהֵם שְׁתֵּי דְרָגוֹת - אֶחָד אוֹתוֹ שֶׁעוֹמֵד בָּאֶמְצַע שֶׁהוּא גָּדוֹל, וְאוֹתוֹ שֶׁעוֹמֵד מֵאָחוֹר שֶׁהוּא קָטָן, שֶׁמְּעַכְּבִים אוֹתוֹ - יִשְׂרֹף הָעוֹלָם בְּשַׁלְהֲבוֹתָיו. וּמָה עוֹשִׂים? כֵּיוָן שֶׁעוֹלֶה הַבֹּקֶר וְחוּט אוֹר יוֹצֵא מִצַּד דָּרוֹם, אָז מִתְחַבְּרִים כֻּלָּם וְנַעֲשִׂים שְׁתֵּי רַגְלַיִם שְׁנֵי טַלְפֵי עֵגֶל, לְקַיֵּם הַכָּתוּב (יחזקאל א) וְכַף רַגְלֵיהֶם כְּכַף רֶגֶל עֵגֶל. וַהֲרֵי יָדַעְתָּ סוֹד זֶה. שְׁאֵלַת עֲנַף הַגֹּרֶן. לְתוֹךָ עֲזָרָה זוֹ יֵשׁ שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה הֵיכָלוֹת, כְּחֶשְׁבּוֹן יְמוֹת הַשָּׁנָה. וּבְכָל פֶּתַח וּפֶתַח כָּתוּב: יְהִי שָׁלוֹם בְּחֵילֵךְ שַׁלְוָה בְּאַרְמְנוֹתָיִךְ (תהלים קכב). לֹא יָדוּעַ מַהוּ בַּהֵיכָלוֹת הָאֵלֶּה, אֶלָּא כֻּלָּם נִרְאִים מַעֲשֵׂה צִיּוּר. שִׁבְעָה סִדְרֵי מַרְגָּלִיּוֹת נִרְאִים אֵלּוּ בְאֵלּוּ בְּכָל אֶחָד וְאֶחָד.</p>"],[9522012361,"<p>אִי חָסִיד קָדוֹשׁ, כַּמָּה מְשַׁבֵּחַ רֹאשׁ הַיְשִׁיבָה הֵיכָל אֶחָד שֶׁהוּא בְּרֹאשׁ צַד מִזְרַח הָעֲזָרָה הַזּוֹ, מִשּׁוּם שֶׁאַרְבָּעָה הֵם בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם. אֲבָל הֵיכָל שֶׁל צַד מִזְרָח מַרְבֶּה אוֹרוֹתָיו יוֹתֵר מִכֻּלָּם.</p>\n<p>יוֹם אֶחָד בַּיָּם הַגָּדוֹל יָצָא לִוְיָתָן, וְכָל הַיָּם הִזְדַּעֲזַע, וְכָל הַדָּגִים הָלְכוּ לְכָאן וּלְכָאן. כְּשֶׁהִגִּיעַ הַלִּוְיָתָן לְפֶתַח פֶּתַח הַתְּהוֹם, מַתְחִיל לִשְׂמֹחַ, וְשָׁכַךְ שָׁם הַתְּהוֹם, אֶלָּא אוֹתוֹ כְּמַרְאֵה הַמַּעְיָן, וּמִתְכַּסִּים הָאוֹרוֹת, וְלֹא נִרְאוּ כָּל אוֹתָם אוֹרוֹת, פְּרָט לְאוֹר הַהֵיכָל שֶׁבְּצַד הַמִּזְרָח הַזֶּה.</p>\n<p>אוֹתָהּ מַרְגָּלִית שֶׁמּוֹצִיא הַלִּוְיָתָן מִתּוֹךְ אוֹתוֹ תְהוֹם שֶׁנִּקְרָא סַגְדּוֹ\"ן, מִמַּה נֶּעֶשְׂתָה? אֶלָּא יוֹם זֶה שֶׁמּוֹצִיא הַלִּוְיָתָן שֶׁהִזְדַּעֲזַע הַיָּם, יוֹם שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, הוּא ט' בְּאָב. וְאוֹתָהּ מַרְגָּלִית, שֶׁכְּשֶׁזּוֹכֵר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת בָּנָיו וְזוֹרֵק שְׁתֵּי דְמָעוֹת לְתוֹךְ הַיָּם הַגָּדוֹל, אַחַת נוֹפֶלֶת לְתוֹךְ תְּהוֹם זֶה שֶׁנִּקְרָא סַגְדּוֹ\"ן, וְאַחַת נוֹפֶלֶת לְתוֹךְ תְּהוֹם אַחֵר שֶׁנִּקְרָא גִּילְבָ\"א.</p>\n<p>מִשּׁוּם שֶׁחֲמִשָּׁה תְהוֹמוֹת אֲחֵרִים הֵם בַּיָּם הַגָּדוֹל, אֲבָל לֹא חֲשׁוּבִים כְּאֵלּוּ הָאֲחֵרִים. וְכֵיוָן שֶׁנּוֹפְלוֹת אֵלּוּ הַדְּמָעוֹת, צָפוֹת תּוֹךְ תְּהוֹם אֶחָד. וְאֶחָד נִטְבָּע תּוֹךְ תְּהוֹם שֶׁנִּקְרָא גִּילְבָ\"א.</p>"],[9522012362,"<p>שֶׁלְּמַטָה תּוֹךְ שִׁמְרֵי הַיַּיִן, שְׁמָרִים רָעִים, יוֹצֵא עִרְעוּר אֶחָד מְקַטְרֵג, מַזִּיק קַדְמוֹן, וְהוּא בְּרוּחַ דְּמוּת אָדָם כְּשֶׁמִּתְקָרֵב לַקֹּדֶשׁ. כֵּיוָן שֶׁנֶּעֱבָר מִשָּׁם וְרוֹצֶה לָרֶדֶת לְמַטָּה לְהִתְלַבֵּשׁ בִּלְבוּשׁ לְהַזִּיק אֶת הָעוֹלָם, יוֹרֵד הוּא וּמַרְכְּבוֹתָיו, וּלְבוּשׁ קַדְמוֹן שֶׁלּוֹבֵשׁ תַּבְנִית שׁוֹר, דְּמוּת שׁוֹר. וְרִאשׁוֹן לַנְּזִיקִין מֵאוֹתָם אַרְבָּעָה הוּא שׁוֹר, וְאוֹתָם אַרְבָּעָה אָבוֹת לְהַזִּיק הָעוֹלָם. וְכֻלָּם שְׁלֹשָׁה אֲבוֹת נְזִיקִין פְּרָט לַשּׁוֹר כֻּלָּם שֶׁלּוֹ.</p>\n<p>וְעַל זֶה כָּתוּב, (תהלים קו) וַיָּמִירוּ אֶת כְּבוֹדָם בְּתַבְנִית שׁוֹר אֹכֵל עֵשֶׂב. מַהוּ אֹכֵל עֵשֶׂב? הֲרֵי דָּרַשְׁנוּ בוֹ, אֲבָל עִקַּר הַדָּבָר מִתַּמְצִית הַלֶּחֶם, וְלֹא מִשִּׁבְעַת מִינֵי דָגָן, אֵין לוֹ בָּהֶם חֵלֶק, וְלֹא רָאוּי לוֹ לִהְיוֹת שָׁם.</p>\n<p>מִמְּקוֹמוֹתֵיהֶם, וְאֵלֶּה יוֹשְׁבִים בִּמְקוֹמוֹתֵיהֶם. עַד שֶׁלֹּא יוֹצְאִים אֵלּוּ, מְזֻמָּנִים אֵלּוּ. אוֹר וְהִתְנוֹצְצוּת שֶׁלָּהֶם אֵין הָעֵינַיִם יְכוֹלוֹת לִסְבֹּל. הוֹלְכִים מִסָּבִיב, אֵין הֵם שׁוֹכְכִים לְעוֹלָמִים.</p>\n<p>כְּשֶׁמִּסְתַּכֵּל בֶּן אָדָם בְּהֵיכָל זֶה, מִיָּד בְּהִסְתַּכְּלוּת רִאשׁוֹנָה נִרְאֶה קָטָן וְלֹא קָטָן, מִסְתַּכֵּל יוֹתֵר - נִרְאֶה גָדוֹל. עוֹד מִסְתַּכֵּל - נִרְאֶה יוֹתֵר גָּדוֹל. כָּל מַה שֶּׁמִּסְתַּכֵּל, כָּךְ נִרְאֶה בְּהִתְפַּשְּׁטוּת גָּדוֹל וְעֶלְיוֹן, עַד שֶׁנִּדְמֶה בַהִסְתַּכְּלוּת כִּמְלֹא נִימָה שֶׁאֵין לָהּ שִׁעוּר.</p>\n<p>מַעָשִׂים גְּדוֹלִים לִפְנִים שֶׁלֹּא יְדוּעָה אֻמָּנוּתָם, מִשָּׁם מְאִירָה עֲזָרָה וְכָל מַה שֶּׁיֵּשׁ בָּהּ, פְּרָט לַכְּרוּבִים שֶׁאוֹרָם עוֹלֶה עַד רוּם הָרָקִיעַ בִּגְוָנִים רַבִּים, וְאוֹרוֹת נוֹצְצִים. אֶלֶף וַחֲמֵשׁ מֵאוֹת וַחֲמִשָּׁה וְשִׁבְעִים גְּפָנִים עוֹשִׂים פֵּרוֹת בַּעֲזָרָה זוֹ.</p>"],[9522012363,"<p>יוֹתֵר - (קהלת ד) חֹבֵק אֶת יָדָיו, בִּמְרִירוּת וַאֲנִינוּת שֶׁלּוֹ, וְאַחַר כָּךְ - אֹכֵל אֶת בְּשָׂרוֹ, בְּעַל כָּרְחוֹ, שֶׁאֵין לוֹ רְשׁוּת לִשְׁלֹט עַל דָּבָר אַחֵר. מָה עוֹזֵר לוֹ בְּכָל מַה שֶּׁמַּסְטֶה וְעוֹשֶׂה וְעָמֵל שֶׁלְּאַחַר כָּךְ אֵין לוֹ רְשׁוּת אֶלָּא עַל שֶׁלּוֹ, אַחַר כָּךְ מַרְקִיד וְשָׂמֵחַ כִּכְסִיל בְּלִי דַעַת כְּלָל, וְהוֹלֵךְ לְלֹא תוֹעֶלֶת וְאוֹכֵל הַבָּשָׂר. וּבַשְּׁאָר אֵין לוֹ רְשׁוּת. מְרִירוּת שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה, כְּשֶׁיִּשְׂרָאֵל בְּצָרָה וְאוֹכְלִים אוֹתָם שׂוֹנְאֵיהֶם, וְלֹא נוֹתְנִים כֹּחַ בְּמַעֲשֵׂיהֶם הַטּוֹבִים לְהוֹצִיא מִמֶּנּוּ.</p>\n<p>וַאֲפִלּוּ מִבְּשָׂרוֹ שֶׁהוּא מִצַּד זֶה, מֵרֵעַ לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, שֶׁהוּא רַחוּם וְחַנּוּן. אֲבָל עַל שֶׁלּוֹ, רוּחַ הַקֹּדֶשׁ וּנְשָׁמָה קְדוֹשָׁה, אֵין עֶלְיוֹנִים וְתַחְתּוֹנִים יְכוֹלִים לִשְׁלֹט עָלָיו כְּלָל. וְעַל כָּךְ כָּל הָעֲלִילוֹת וְכָל מַה שֶּׁמַּסְטֶה אוֹתוֹ רָע, שֶׁחוֹשֵׁב לִשְׁלֹט עַל רוּחַ הַקֹּדֶשׁ וְאַחַר כָּךְ לֹא יָכוֹל, וְיָשׁוּב וְאוֹכֵל אֶת בְּשָׂרוֹ, מַה תּוֹעֶלֶת הָיָה לוֹ? וְעוֹד, שֶׁהֵם מְכַסִּים כֻּלָּם כְּמוֹ מְעֻרְפָּל חָזָק, וְאֵין שׁוֹכְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>בֹּא וְאֹמַר לְךְ דָּבָר. אִם תֹּאמַר שֶׁשִּׂמְחָה הִיא לְמַלְאַךְ הַמָּוֶת כְּשֶׁהוֹרֵג בְּנֵי אָדָם - לֹא. אֲבָל מִשּׁוּם שֶׁרוֹאֶה שֶׁרְצוֹן רִבּוֹנוֹ בְּכָךְ, מַרְאֶה עַצְמוֹ בְשִׂמְחָה לַעֲשׂוֹת רְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (תהלים קמח) רוּחַ סְעָרָה עֹשָׂה דְבָרוֹ. אָמַר לוֹ רַבִּי שִׁמְעוֹן, וַהֲרֵי הוּא מְרַקֵּד וְהוֹלֵךְ בְּחֶדְוָה לִפְנֵי נָשִׁים. אָמַר לוֹ, אִי חָסִיד קָדוֹשׁ, וַדַּאי כָּךְ זֶה, לְהֵרָאוֹת לִפְנֵי הַמֶּלֶךְ שֶׁנּוֹחַ לוֹ בִּרְצוֹן הַמֶּלֶךְ. אֲבָל הַנַּחַת שֶׁלּוֹ בְּהֶסְפֵּד הַנָּשִׁים. הוּא רוֹקֵד, וְאָזְנָיו לַהֶסְפֵּד.</p>\n<p>אָמַר לוֹ, אִם כָּךְ, מַדּוּעַ הוֹלֵךְ וּמַסְטֶה עַל הָאָדָם לְמַעְלָה וּמַזְכִּיר חֲטָאָיו? אָמַר לוֹ, מִשּׁוּם שֶׁהוּא (קהלת ד) זָקֵן וּכְסִיל, וְחוֹשֵׁב לִשְׁלֹט עַל הָרוּחַ, וְכָל תַּאֲוָתוֹ הִיא בִּגְלַל זֶה. בַּסּוֹף לֹא שׁוֹלֵט אֶלָּא עַל שֶׁלּוֹ, בְּשָׂרוֹ, וְעַל זֶה כָּתוּב (תהלים ז) יָשׁוּב עֲמָלוֹ בְרֹאשׁוֹ.</p>"],[9522012364,"<p>הוֹלֵךָ וְרוֹצֶה לְרַגֵּשׁ אֶת הָעוֹלָם, וּמַיִם עוֹלִים מִתּוֹךְ שְׁאָר תְּהוֹמוֹת וְרוֹצִים לְכַסּוֹת הָעוֹלָם. אוֹתָן דְּמָעוֹת רוֹתְחוֹת יוֹתֵר מִכָּל אֵשׁ שֶׁבָּעוֹלָם. וּמִתּוֹךְ תֹּקֶף הָרְתִיחָה שֶׁלָּהֶן, קוֹפְאִים הַמַּיִם תּוֹךְ הַיָּם הַקָּפוּא, וְאִלְמָלֵא שֶׁרָמַז הַקָּדוֹשׁ בָּרוּךְ הוּא נְשִׁיבָה אַחַת מִצַּד אַבְרָהָם מֵעַמּוּד שֶׁלּוֹ וְנִרְאֶה כָּל הָעוֹלָם, לֹא יָכוֹל לַעֲמֹד אֲפִלּוּ רֶגַע אֶחָד.</p>\n<p>אוֹתָן דְּמָעוֹת כְּשֶׁנּוֹפְלוֹת לְתוֹךְ הַיָּם, נִשְׁמָע קוֹל בֵּין הַיָּם עַד מְעָרַת הַמַּכְפֵּלָה. מִקּוֹל נַהֲמָתָם שֶׁנִּשְׁמָע שָׁם כְּשֶׁנִּכְנָסִים לְתוֹךְ הַיָּם, מִתְעוֹרְרִים אָבוֹת הָרִאשׁוֹנִים, וְקָמוּ, וְחָשְׁבוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לַהֲפֹךְ אֶת הָעוֹלָם, עַד שֶׁקּוֹל יוֹצֵא וְאוֹמֵר לָהֶם: אַל תְּפַחֲדוּ אֲהוּבִים קְדוֹשִׁים, בִּגְלַלְכֶם זוֹכֵר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת בְּנֵיכֶם, וְהוּא רוֹצֶה לִגְאֹל אוֹתָם, וְאַתֶּם תִּרְאוּ.</p>"],[9522012365,"<p>כָּל הָאַלְפָא בֵּיתוֹת מְשֻׁלָּבוֹת וּמִצְטָרְפוֹת אֵלֶּה בְאֵלֶּה, וּמִתְחַבְּרוֹת בְּצֵרוּף הַשֵּׁם הַקָּדוֹשׁ. כֵּיוָן שֶׁנִּרְאוּ הָאוֹתִיּוֹת בְּצֵרוּף זֶה, אֵלֶּה נִגְנָזִים, וְיוֹצְאִים אֲחֵרִים, וְכֵן כֻּלָּם. אֵלֶּה נִגְנָזִים, וְאֵלֶּה יוֹצְאִים, כֻּלָּם לִפְנִים בַּחֲלַל אוֹתָם כַּפְתּוֹרִים.</p>\n<p>שׁוּב פּוֹרְחִים שָׁלֹשׁ פְּעָמִים בַּיּוֹם בָּאֲוִיר וְיוֹצְאִים הַחוּצָה, וְעוֹמֵד הַשֵּׁם בְּאַרְבַּע אוֹתִיּוֹת, תְּלוּיִים בָּאֲוִיר שָׁעָה וָחֵצִי. לְאַחַר שֶׁנִּגְנַז זֶה מִיָּד יוֹצֵא מִתּוֹךְ חֲלַל הָאֲוִיר שֵׁם שֶׁל שְׁתֵּים עֶשְׂרֵה אוֹתִיּוֹת, פּוֹרֵחַ וְתָלוּי בָּאֲוִיר שָׁעָה אַחַת, וְלֹא יוֹתֵר. אַחַר כָּךְ זֶה נִגְנָז, וְיוֹצֵא מִיָּד צֵרוּף אוֹתִיּוֹת אֲחֵרוֹת, שֵׁם שֶׁל כ' (של כ\"ב) אותיות, ותלוי באויר שעה אחרת ונגנז. ומיד יוצאות אותיות מחלל אחר, שם של עשרים ושמונה אותיות, מתעטרים כלם בכתריהם, ועומדים שעה וחצי, ונגנז זה. ומיד יוצאים תלויים באויר שם של עשרים וחמש אותיות בצרופיהן, ועומד שעה ושלשה רגעים. יוצאות אותיות של ארבעים ושתים אותיות, ועומדות לעולם.</p>\n<p>הַשֵּׁמוֹת, אֶלָּא כֻּלָּם אוֹתִיּוֹת, לֹא שׁוֹכְכִים לְעוֹלָמִים, בּוֹלְטִים וְנוֹצְצִים הַחוּצָה, וְעוֹלִים וְיוֹרְדִים. אֵין מִי שֶׁיָּכוֹל לַעֲמֹד בָּהֶם, פְּרָט לַמָּשִׁיחַ בְּטֹרַח גָּדוֹל. זֶה גָנוּז, לְאַחַר שֶׁעוֹמֵד שְׁעָתַיִם וְעֶשְׂרִים וּשְׁנַיִם רְגָעִים, וְהַשֵּׁם הֶחָקוּק שֶׁל ע\"ב אוֹתִיּוֹת יוֹצֵא וְעוֹמֵד וְתָלוּי בָּאֲוִיר שָׁעָה וָחֵצִי. כָּל הַשֵּׁמוֹת הָאֵלֶּה לֹא יוֹצְאִים וְלֹא נִרְאִים, אֶלָּא פַּעַם אַחַת בַּיּוֹם, אֲבָל אוֹתָן א\"ב נִרְאוֹת פּוֹרְחוֹת בָּאֲוִיר, וּמְצָרְפוֹת אֵלֶּה בְאֵלֶּה שָׁלֹשׁ פְּעָמִים בְּיוֹם.</p>\n<p>כְּשֶׁפּוֹרְחוֹת אוֹתִיּוֹת הָאָלֶף בֵּית, אֵלֶּה פּוֹרְחוֹת מִכָּאן וְאֵלֶּה מִכָּאן, וּמִצְטָרְפוֹת כֻּלָּן. כְּשֶׁיּוֹרֵד שָׁם רֹאשׁ הַיְשִׁיבָה, מַתְחִיל, מָשִׁיחַ רוֹאֶה בְצֵרוּף א\"ב אוֹתִיּוֹת כְּמוֹ שֶׁרָאָה דָנִיֵּאל, שֶׁהֵם: ממתוס ננקפי אאלרן (מנא מנא תקל ופרסין (דניאל ה, כה)).</p>"],[9522012366,"<p>כָּל עֶרֶב שַׁבָּת, כְּשֶׁמְּקַדְּשִׁים יִשְׂרָאֵל אֶת הַיּוֹם לְמַטָּה, כָּרוֹז מַכְרִיז לְאַרְבָּעָה צִדְדֵי הָעוֹלָם: הִתְכַּנְּסוּ מֶרְכָּבוֹת קְדוֹשׁוֹת! הַתְקִינוּ כִסְאוֹת (קדושים) מִי רָאָה חֶדְוָה בִּשְׁלֹשׁ מֵאוֹת וְתִשְׁעִים רְקִיעִים? כַּמָּה מְמֻנִּים, כַּמָּה שַׁלִּיטִים מִתְכַּנְּסִים לִמְקוֹמוֹתֵיהֶם. כֵּיוָן שֶׁיִּשְׂרָאֵל לְמַטָּה מְקַדְּשִׁים (להקדוש ברוך הוא), אָז מִתְעוֹרֵר עֵץ הַחַיִּים, וּמַקִּישׁ בְּאוֹתָם הֶעָלִים שֶׁלּוֹ רוּחַ נְשִׁיבוּת אַחַת מִתּוֹךְ עוֹלָם הַבָּא, וְאוֹתָם עַנְפֵי הָאִילָן מִתְנַעְנְעִים, וְעוֹלִים רֵיחוֹת שֶׁל הָעוֹלָם הַבָּא.</p>\n<p>אוֹתוֹ עֵץ הַחַיִּים מִתְעוֹרֵר, וּמוֹצִיא נְשָׁמוֹת קְדוֹשׁוֹת, וּפוֹרֵשׂ עַל הָעוֹלָם. וְעִם כָּל זֶה נְשָׁמוֹת יוֹצְאוֹת וּנְשָׁמוֹת נִכְנָסוֹת. אֵלֶּה מְעוֹרְרִים אֵלֶּה, אֵלֶּה יוֹצְאִים וְאֵלֶּה נִכְנָסִים, וְעֵץ הַחַיִּים בְּחֶדְוָה.</p>\n<p>וְאָז יִשְׂרָאֵל כֻּלָּם מִתְעַטְּרִים בָּעֲטָרוֹת שֶׁל אוֹתָן נְשָׁמוֹת קְדוֹשׁוֹת, כֻּלָּם בְּחֶדְוָה בִּמְנוּחָה. וְכָל הַשַּׁבָּת יֵשׁ לָהֶם אוֹתָהּ חֶדְוָה וְאוֹתָהּ מְנוּחָה, וְכָל הַצַּדִּיקִים שֶׁבַּגָּן, כֻּלָּם עוֹלִים וּמִתְעַנְּגִים בְּעֹנֶג עֶלְיוֹן שֶׁל הָעוֹלָם הַבָּא. כֵּיוָן שֶׁיּוֹצֵאת הַשַּׁבָּת, כָּל הַנְּשָׁמוֹת פּוֹרְחוֹת וְעוֹלוֹת.</p>\n<p>בֹּא וּרְאֵה, כְּשֶׁנִּכְנֶסֶת שַׁבָּת, נְשָׁמוֹת יוֹרְדוֹת לִשְׁרוֹת עַל הָעָם הַקָּדוֹשׁ, וְנִשְׁמוֹת הַצַּדִּיקִים עוֹלוֹת לְמַעְלָה. כְּשֶׁיּוֹצֵאת הַשַּׁבָּת, הַנְּשָׁמוֹת עוֹלוֹת, אוֹתָן שֶׁשָּׁרוּ עַל יִשְׂרָאֵל. וּנְשָׁמוֹת יוֹרְדוֹת, אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים.</p>\n<p>כֵּיוָן שֶׁעוֹלוֹת כָּל הַנְּשָׁמוֹת שֶׁשָּׁרוּ עַל יִשְׂרָאֵל, עוֹלוֹת וְעוֹמְדוֹת בִּדְמוּת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹאֵל אֶת כֻּלָּם: אֵיזֶה חִדּוּשׁ הָיָה לָכֶם בְּאוֹתוֹ עוֹלָם בַּתּוֹרָה? אַשְׁרֵי מִי שֶׁאוֹמֵר לְפָנָיו חִדּוּשׁ עַל הַתּוֹרָה. כַּמָּה חֶדְוָה עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא. מְכַנֵּס פָּמַלְיָה שֶׁלּוֹ וְאוֹמֵר: שִׁמְעוּ חִדּוּשׁ תּוֹרָה שֶׁאוֹמֶרֶת נִשְׁמַת פְּלוֹנִי זֶה. וְכֻלָּם מַעֲמִידִים אוֹתוֹ דָבָר בִּשְׁתֵּי יְשִׁיבוֹת. הֵם לְמַטָּה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה חוֹתֵם לְאוֹתוֹ דָבָר.</p>\n<p>בֹּא וּרְאֵה, כְּשֶׁדָּבָר מִתְחַדֵּשׁ בַּתּוֹרָה וּנְשָׁמָה שֶׁיּוֹרֶדֶת בְּשַׁבָּת הִתְעַסְּקָה בְּאוֹתָם דְּבָרִים חֲדָשִׁים וְעוֹלָה לְמַעְלָה, כָּל הַפָּמַלְיָה שֶׁל מַעְלָה מַקְשִׁיבָה לְאוֹתוֹ דָבָר, וְחַיּוֹת הַקֹּדֶשׁ מִתְרַבִּים בִּכְנָפַיִם וּמִתְלַבְּשִׁים בִּכְנָפַיִם. וּכְשֶׁשּׁוֹאֵל אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא מְשִׁיבִין, וְשׁוֹתְקִין, אָז חַיּוֹת הַקֹּדֶשׁ מַה כָּתוּב? (יחזקאל א) בְּעָמְדָם תְּרַפֶּינָה כַנְפֵיהֶן, כְּמוֹ שֶׁנֶּאֱמַר (איוב לב) כִּי עָמְדוּ לֹא עָנוּ עוֹד. (נחמיה ח) וּכְפִתְחוֹ עָמְדוּ כָּל הָעָם.</p>\n<p>וְאִם תֹּאמַר, לָמָּה לַשְּׁתִיקָה קָרְאוּ עֲמִידָה? אֶלָּא בַּדִּבּוּר יֵשׁ שִׁבְעָה אֵיבָרִים שֶׁמִּתְנַעְנְעִים יַחַד אִתּוֹ: לֵב, רֵאָה, קָנֶה, לָשׁוֹן, שִׁנַּיִם, שְׂפָתַיִם, בָּשָׂר. וּבַשְּׁתִיקָה עוֹמְדִים בְּעָמְדָם לְלֹא נִעְנוּעַ, וְעַל זֶה קוֹרְאִים לַשְּׁתִיקָה עֲמִידָה.</p>\n<p>שֶׁהֲרֵי רַב הַמְנוּנָא סָבָא אָמַר, (תהלים כ) יִשְׁלַח עֶזְרְךְ מִקֹּדֶשׁ וְגוֹ'. מִקֹּדֶשׁ - זֶה קִדּוּשׁ יָדַיִם. וּמִצִּיּוֹן יִסְעָדֶךָּ - זֶה הַמּוֹצִיא, שֶׁהוּא סוֹעֵד לֵב הָאָדָם. יִזְכֹּר כָּל מִנְחֹתֶיךְ, כָּל - לְרַבּוֹת דָּבָר אַחֵר, זוֹ נְטִילַת יָדַיִם אַחֲרוֹנָה. וְעוֹלָתְךְ יְדַשְּׁנֶה סֶלָה - זוֹ בִּרְכַּת הַמָּזוֹן בְּזִמּוּן. אִם אַתָּה עוֹשֶׂה כֵן, יִתֶּן לְךְ כִלְבָבֶךְ וְכָל עֲצָתְךְ יְמַלֵּא. וּבְשַׁבָּת מְקַדֵּשׁ, זֶה קִדּוּשׁ הַגָּדוֹל. וְעַל דָּבָר זֶה הִתְעַטְּרוּ הַצַּדִּיקִים בְּגַן עֵדֶן מִשַּׁבָּת לְשַׁבָּת אַחֶרֶת.</p>"],[9522012367,"<p>עוֹד פָּתַח וְאָמַר, (ישעיה מ) עַל הַר גָּבֹהַּ עֲלִי לָךְ מְבַשֶּׂרֶת צִיּוֹן וְגוֹ'. עַל הַר גָּבהַּ - זֶה וַדַּאי הַר הָעֲבָרִים, מָקוֹם שֶׁמֹּשֶׁה נִקְבַּר בּוֹ. וַהֲרֵי פֵּרְשׁוּהָ, שֶׁשְּׁכִינָה תַעֲלֶה לְשָׁם וּתְבַשֵּׂר לָעוֹלָם. אֲבָל הַכֹּל הוּא מְבַשֶּׂרֶת צִיּוֹן, זוֹהִי חֶפְצִי בָהּ, אֵשֶׁת נָתָן בֶּן דָּוִד, אֵם הַמָּשִׁיחַ, מְנַחֵם בַּ\"ר עַמִּיאֵ\"ל, וְהִיא תֵצֵא וּתְבַשֵּׂר, וְהִיא בִּכְלַל מְבַשֶּׂרֶת צִיּוֹן.</p>\n<p>קוֹל יִשָּׁמַע בָּעוֹלָם, וּשְׁנֵי מְלָכִים יִתְעוֹרְרוּ בָעוֹלָם לַעֲרֹךְ קְרָב, וְיֵצֵא שֵׁם הַקָּדוֹשׁ עַל הָעוֹלָם. מַה תְּבַשֵּׂר וְתֹאמַר? (שם) הִנֵּה ה' אֱלֹהִים בְּחָזָק יָבֹא וּזְרֹעוֹ מֹשְׁלָה לוֹ הִנֵּה שְׂכָרוֹ אִתּוֹ וּפְעֻלָּתוֹ לְפָנָיו. הִנֵּה שְׂכָרוֹ אִתּוֹ - שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַכְרִיז בְּכָל פָּמַלְיָה שֶׁל מַעְלָה וְיֹאמַר לָהֶם: הִתְכַּנְּסוּ וְדוּנוּ דִין, מִי שֶׁמָּסַר נִשְׁמָתוֹ עַל קְדֻשַּׁת שְׁמִי מַהוּ שְּׂכָרוֹ? וְאֵלּוּ יֹאמְרוּ כָּךְ וְכָךְ. מִי שֶׁסָּבַל כַּמָּה חֵרוּפִים וְגִדּוּפִים בְּכָל יוֹם עָלַי מַה שְּׂכָרוֹ? הֵם יֹאמְרוּ כָּךְ. מִי שֶׁנֶּעֱנָשׁ בְּכָל יוֹם יוֹם עָלַי מַה שְּׂכָרוֹ? הֵם יֹאמְרוּ כָּךְ. זֶהוּ שֶׁכָּתוּב הִנֵּה שְׂכָרוֹ אִתּוֹ וּפְעֻלָּתוֹ לְפָנָיו.</p>\n<p>מַהוּ וּפְעֻלָּתוֹ? אֶלָּא כְּמוֹ שֶׁכָּתוּב, (תהלים לא) מָה רַב טוּבְךְ וְגוֹ', פָּעַלְתָּ לַחוֹסִים בָּךְ. זֶהוּ פְּעֻלָּתוֹ. נֶגֶד בְּנֵי אָדָם מַה זֶּה? אֶלָּא נֶגֶד עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ, מַה זֶּה אֲשֶׁר צָפַנְתָּ? וְכִי מִי יִגְזֹל וְיִטֹּל מִיָּדוֹ מַה שֶּׁהוּא רוֹצֶה לָתֵת, שֶׁכָּתוּב צָפַנְתָּ?</p>\n<p>אֶלָּא צֵא וּרְאֵה מַעֲשֵׂי הָרַחֲמָנוּת שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא. בְּמַה שֶּׁהוּא מַכֶּה - בּוֹ נוֹתֵן רְפוּאָה. בַּמֶּה מַכֶּה? בִּשְׂמֹאל. בְּיָמִין מְקָרֵב וּבִשְׂמֹאל מַכֶּה. בְּמַה שֶּׁמַּכֶּה - בּוֹ נוֹתֵן רְפוּאָה לָעוֹלָם. כָּתוּב (ירמיה א) מִצָּפוֹן תִּפָּתַח הָרָעָה, וּבְצָפוֹן מַכֶּה, שֶׁמִּשָּׁם יוֹצְאִים כָּל הַדִּינִים וְכָל הַגְּזֵרוֹת הַקָּשׁוֹת - וּבוֹ שׁוֹרֶה כָּל שָׂכָר טוֹב וְכָל טוֹב שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לָתֵת לְיִשְׂרָאֵל. לֶעָתִיד לָבֹא קוֹרֵא הַקָּדוֹשׁ בָּרוּךְ הוּא לַצָּפוֹן וְיֹאמַר לוֹ: בְּךְ נָתַתִּי כָּל טוֹב וְכָל שָׂכָר טוֹב לְבָנַי שֶׁסָּבְלוּ כַּמָּה רָעוֹת בָּעוֹלָם הַזֶּה עַל קְדֻשַּׁת שְׁמִי, תֵּן שְׂכָרִים טוֹבִים שֶׁנָּתַתִּי בְךְ.</p>\n<p>זֶהוּ שֶׁכָּתוּב, (ישעיה מג) אֹמַר לַצָּפוֹן תֵּנִי וּלְתֵימָן אַל תִּכְלָאִי וְגוֹ'. וְכִי דֶרֶךְ הַדָּרוֹם כָּךְ הוּא, לִמְנֹעַ בְּרָכוֹת? וַהֲרֵי כָּל הַבְּרָכוֹת מִצַּד דָּרוֹם, וְכָל טוֹבוֹת הָעוֹלָם מִדָּרוֹם יוֹצְאוֹת, וְהוּא אוֹמֵר לְתֵימָן אַל תִּכְלָאִי?!</p>\n<p>אֶלָּא בְּאוֹתָהּ שָׁעָה יְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אַבְרָהָם וְיֹאמַר לוֹ: קוּם, שֶׁהֲרֵי הִגִּיעַ זְמַן שֶׁאֲנִי גּוֹאֵל אֶת בָּנֶיךְ לָתֵת לָהֶם שָׂכָר טוֹב עַל כָּל מַה שֶּׁסָּבְלוּ בַגָּלוּת. וּמִתּוֹךְ שֶׁאַבְרָהָם הָיָה בִמְכִירָתָם, שֶׁכָּתוּב (דברים לב) אִם לֹא כִּי צוּרָם מְכָרָם - זֶה אַבְרָהָם, הָיָה לוֹ כְּמִי שֶׁלֹּא טוֹב בְּעֵינָיו, וּמַרְאֶה עַצְמוֹ כְּמִי שֶׁרוֹצֶה שֶׁיִּלְקוּ עַל חֲטָאֵיהֶם יוֹתֵר וְיֹאמַר: גְּבוּ מֵעֲונוֹתֵיהֶם! גְּבוּ מֵחֲטָאֵיהֶם! אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם: יָדַעְתִּי כָּל מַה שֶּׁאָמַרְתָּ לְפָנִים. אֲנִי גַּם כֵּן לְפָנִים. אַל תִּכְלָאִי. אֲנִי רוֹצֶה לְפַיֶּסְךְ עַל בָּנֶיךְ, אַל תִּמְנַע מֵהֶם טוֹבוֹת, אַל תִּמְנַע מֵהֶם שָׂכָר טוֹב, כַּמָּה וְכַמָּה סָבְלוּ עַל חֲטָאֵיהֶם. וּמִשּׁוּם כָּךְ - אֹמַר לַצָּפוֹן תֵּנִי. וְהַיְנוּ אֲשֶׁר צָפַנְתָּ, וְזֶהוּ הַדָּבָר (שתהא) שֶׁל אוֹתָהּ מְבַשֶּׂרֶת.</p>\n<p>וְעוֹד תְּבַשֵּׂר פַּעַם שְׁנִיָּה, בְּשָׁעָה שֶׁהַשְּׁכִינָה תַעֲלֶה עַל אוֹתוֹ הַר עֶלְיוֹן, וְתֵלֵךְ וּתְבַשֵּׂר לָאָבוֹת. מִיָּד תֵּלֵךְ לִירוּשָׁלַיִם וְתִרְאֶה אוֹתָהּ בְּחֻרְבָּנָהּ. תִּכָּנֵס לְצִיּוֹן, וְשָׁם תְּקַרְקֵר קִיר כְּמִקֹּדֶם עַל מְקוֹם בֵּית מוֹשָׁבָהּ וְעַל כְּבוֹדָהּ בְּאוֹתוֹ מָקוֹם. וְשָׁם נִשְׁבַּעְתָּ שֶׁלֹּא תִקַּח מִשָּׁם וְלֹא תֵצֵא עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִגְאַל אֶת בָּנֶיהָ, וְחֶפְצִי בָהּ זוֹ תְּבַשֵּׂר כְּמִקֹּדֶם וְאוֹמֶרֶת: (ישעיה יב) צַהֲלִי וָרֹנִּי יוֹשֶׁבֶת צִיּוֹן כִּי גָדוֹל בְּקִרְבֵּךְ וְגוֹ'. מַה זֶּה גָּדוֹל בְּקִרְבֵּךְ? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁבָּא אֵלֶיהָ לַהֲקִימָהּ מִן הֶעָפָר, וְיֹאמַר לָהּ: (שם נב) הִתְנַעֲרִי מֵעָפָר קוּמִי שְׁבִי יְרוּשָׁלם. יְרוּשָׁלַיִם הִיא, וִירוּשָׁלַיִם שְׁמָהּ בְּוַדַּאי.</p>\n<p>וּבָזְהִ גַּם כָּךְ כַּמָּה שִׂמְחָה עַל שִׂמְחָה תִּהְיֶה לַצַּדִּיקִים בְּגַן עֵדֶן. וּמִשּׁוּם זֶה אַשְׁרָיו מִי שֶׁנִּשְׁמָתוֹ בְּשַׁבָּת מְעִידָה לִפְנֵי הַמֶּלֶךְ עַל חִדּוּשׁ הַתּוֹרָה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא וְכָל פָּמַלְיָתוֹ וְכָל אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים שֶׁהָיוּ בְּגַן עֵדֶן, כֻּלָּם מִתְעַטְּרִים בְּאוֹתוֹ דָבָר.</p>\n<p>עוֹד שָׁמַעְתִּי מְנוֹרָה הַקְּדוֹשָׁה, שֶׁכַּמָּה כָבוֹד עַל כָּבוֹד וַעֲטָרָה עַל עֲטָרָה מְעַטְּרִים לַאֲבִי אוֹתוֹ אָדָם שָׁם בְּשָׁעָה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: הִתְכַּנְּסוּ לִשְׁמֹעַ חִדּוּשׁ וּדְבָרִים חֲדָשִׁים בַּתּוֹרָה מִשֵּׁם פְּלוֹנִי בֶּן פְּלוֹנִי. כַּמָּה הֵם שֶׁמְּנַשְּׁקִים אֶת רֹאשׁוֹ. כַּמָּה צַדִּיקִים מְעַטְּרִים אוֹתוֹ כְּשֶׁיּוֹרְדִים. אַשְׁרֵי חֶלְקָם שֶׁל כָּל אֵלּוּ שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה בְּיוֹם הַשַּׁבָּת מִשְּׁאָר יָמִים. (עד כאן)</p>"],[9522012368,"<p>רֵאשִׁית עֲרִסֹתֵכֶם חַלָּה תָּרִימוּ וְגוֹ'. מִצְוָה לוֹ לְהַפְרִישׁ חַלָּה לַכֹּהֵן. חַלָּ\"ה כָּךְ חֶשְׁבּוֹנָהּ: מ\"ג בֵּיצִים וְחֹמֶשׁ בֵּיצָה, אֶחָד מֵחָמֵשׁ. וְיֵשׁ חֹמֶשׁ אֶחָד מֵחֲמִשִּׁים, שֶׁהוּא ן'. וְזֶה סִימַן מָגֵ\"ן, שֶׁהוּא מִיכָאֵ\"ל גַּבְרִיאֵ\"ל נוּרִיאֵ\"ל. חַלָּה - שְׁכִינָה. שֶׁבְּמָקוֹם שֶׁמַּלְאָכִים אֵלֶּה שָׁם - הָאָבוֹת שָׁם. וּבְמָקוֹם שֶׁהָאָבוֹת שָׁם - שְׁכִינָה שָׁם. וּבָהּ וַיְחַל, בָּהּ אָנוּ מִתְפַּלְלִים. זֶהוּ שֶׁכָּתוּב (שמות לב) וַיְחַל מֹשֶׁה אֶת פְּנֵי ה' אֱלֹהָיו. (דברים ג) אֲדנָי אֱלֹהִים אַתָּה הַחִלּוֹתָ לְהַרְאוֹת אֶת עַבְדְּךְ. וּבָה חָלָה זְכוּת אָבוֹת, וּבָהּ תַּמָּה זְכוּת אָבוֹת לָרְשָׁעִים, שֶׁהָיוּ מְקַבְּלִים שְׂכָרָם בָּעוֹלָם הַזֶּה.</p>\n<p>שֶׁמִּצַד יָמִין שֶׁשָּׁם י', שֶׁהִיא חָכְמָה, רֵאשִׁית שֵׁם ה', שֶׁהִיא מַרְאָה זְכוּת עַל בָּנֶיהָ מִיָּמִין, שֶׁשָּׁם רמ\"ח מִצְווֹת עֲשֵׂה מִצַּד אוֹת ה' אַחֲרוֹנָה, שֶׁהִיא שְׂמֹאל שֶׁל גְּבוּרָה, שֶׁשָּׁם לֹא תַעֲשֶׂה, שֶׁהֵם שס\"ה, שֶׁשָּׁם נִדּוֹנִים רְשָׁעִים גְּמוּרִים, תַּמָּה לָהֶם זְכוּת אָבוֹת, וּמִתְהַפֵּךְ לָהֶם שֵׁם יְהֹוָ\"ה - הוה\"י. וְלָמַדְנוּ מֵהָמָן הָרָשָׁע, (אסתר ה) וְכָל זֶה אֵינֶנּוּ שּוֶה לִי.</p>"],[9522012369,"<p>וַיֹּאמֶר ה' אֶל מֹשֶׁה לֵּאמֹר. דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְגוֹ' וְעָשׂוּ לָהֶם צִיצִת עַל כַּנְפֵי בִגְדֵיהֶם לְדֹרֹתָם וְגוֹ'. רַבִּי חִזְקִיָּה פָּתַח, (זכריה ג) וַיַּרְאֵנִי אֶת יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל וְגוֹ'. כַּמָּה צַדִּיקִים הֵם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִכְבוֹדָם עַל כָּל בְּנֵי הָעוֹלָם, וְנָתַן לָהֶם תּוֹרָה קְדוֹשָׁה, וְנָתַן לָהֶם נְבִיאֵי אֱמֶת שֶׁמַּנְהִיגִים אוֹתָם בַּתּוֹרָה בְּדֶרֶךְ אֱמֶת.</p>\n<p>בֹּא וּרְאֵה, כָּל נְבִיאִים וּנְבִיאִים שֶׁהֶעֱמִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל, עַל כֻּלָּם הִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּדְרָגוֹת עֶלְיוֹנוֹת קְדוֹשׁוֹת, וְרָאוּ זִיו כָּבוֹד קָדוֹשׁ שֶׁל הַמֶּלֶךְ מִמָּקוֹם עֶלְיוֹן, אֲבָל לֹא קָרוֹב כְּמֹשֶׁה, שֶׁהָיָה קָרוֹב לַמֶּלֶךְ יוֹתֵר מֵהַכֹּל, שֶׁהֲרֵי אַשְׁרֵי חֶלְקוֹ יוֹתֵר מִכָּל בְּנֵי הָעוֹלָם, שֶׁעָלָיו כָּתוּב (במדבר יב) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ וּמַרְאֶה וְלֹא בְחִידת. וּשְׁאָר נְבִיאִים הָיוּ רוֹאִים מִמָּקוֹם רָחוֹק, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה לא) מֵרָחוֹק ה' נִרְאָה לִי.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, כָּךְ לָמַדְנוּ, כָּתוּב (שמות ב) וַיֵּלֶךְ אִישׁ מִבֵּית לֵוִי וַיִּקַּח אֶת בַּת לֵוִי. וַיֵּלֶךְ אִישׁ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (שמות טו) ה' אִישׁ מִלְחָמָה. מִבֵּית לֵוִי - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, מָקוֹם שֶׁחָכְמָה עֶלְיוֹנָה וְאוֹתוֹ זֹּהַר (נהר) מִתְחַבְּרִים כְּאֶחָד, שֶׁלֹּא נִפְרָדִים לְעוֹלָמִים. מִבֵּית לֵוִי - שֶׁהִשְׁרָה לִוְיָתָן (כל שמחה) בִּלְבַדּוֹ בָּעוֹלָם, זֶהוּ שֶׁכָּתוּב (תהלים קד) לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ. וַיִּקַּח אֶת בַּת לֵוִי - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, מָקוֹם שֶׁאוֹר הַלְּבָנָה מֵאִיר.</p>\n<p>וַתַּהַר הָאִשָּׁה וַתֵּלֶד בֵּן. הָאִשָּׁה וַדַּאי, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ב) לְזֹּאת יִקָּרֵא אִשָּׁה. בַּהַתְחָלָה בַּת לֵוִי, כָּךְ הוּא בְּוַדַּאי. וְכִי בַּת לֵוִי בַּהַתְחָלָה וְכָעֵת אִשָּׁה? אֶלָּא כָּךְ לָמַדְנוּ, אִשָּׁה עַד שֶׁלֹּא מִזְדַּוֶּגֶת נִקְרֵאת בַּת פְּלוֹנִי. אַחַר שֶׁהִזְדַּוְּגָה נִקְרֵאת אִשָּׁה. וְכָאן בַּת וְאִשָּׁה, הַכֹּל בְּדַרְגָּה אַחַת הִיא.</p>\n<p>וַתִּצְפְּנֵהוּ שְׁלֹשָׁה יְרָחִים - אֵלּוּ שְׁלֹשֶׁת הֶחֳדָשִׁים שֶׁהַדִּין הַקָּשֶׁה שָׁרוּי בָּעוֹלָם. וּמָהֵם? תַּמּוּ\"ז וְאָ\"ב וְטֵבֵ\"ת. מַה בָּא לְהַשְׁמִיעֵנוּ? שֶׁעַד שֶׁלֹּא יָרַד מֹשֶׁה לָעוֹלָם, מָצוּי הָיָה לְמַעְלָה, וְעַל זֶה הִזְדַּוְּגָה בּוֹ שְׁכִינָה מִיּוֹם שֶׁנּוֹלַד. מִכָּאן אָמַר רַבִּי שִׁמְעוֹן, רוּחוֹת הַצַּדִּיקִים מְצוּיוֹת הֵן לְמַעְלָה עַד שֶׁלֹּא יָרְדוּ לָעוֹלָם.</p>\n<p>וְלֹא יָכְלָה עוֹד הַצְּפִינוֹ וַתִּקַּח לוֹ וְגוֹ'. מַה זֶּה וַתִּקַּח לוֹ תֵּבַת גֹּמֶא? שֶׁכִּסְּתָה אוֹתוֹ בְּסִימָנֶיהָ לִהְיוֹת שָׁמוּר מֵאוֹתָם דְּגֵי הַיָּם שֶׁשָּׁטִים בַּיָּם הַגָּדוֹל, כְּמוֹ שֶׁכָּתוּב (תהלים קד) שָׁם רֶמֶשׂ וְאֵין מִסְפָּר. וְהִיא כִּסְּתָה אוֹתוֹ לִהְיוֹת שָׁמוּר מֵהֶם בְּכִסּוּי (של צד היובל המכבד) שֶׁבְּנֵי הַיָּם בְּלֹא כָבוֹד בִּשְׁנֵי צְבָעִים, לָבָן וְשָׁחֹר, וְהִנִּיחָה אֶת מֹשֶׁה לָשׁוּט בֵּינֵיהֶם, לִהְיוֹת נוֹדָע בֵּינֵיהֶם, מִשּׁוּם שֶׁעָתִיד הוּא לַעֲלוֹת בֵּינֵיהֶם בְּפַעַם אַחֶרֶת לְקַבֵּל תּוֹרָה.</p>\n<p>וַתֵּרֶד בַּת פַּרְעֹה - זוֹהִי שֶׁבָּאָה מִצַּד שְׂמֹאל שֶׁל דִּין הַקָּשֶׁה, כְּמוֹ שֶׁנֶּאֱמַר לִרְחֹץ עַל הַיְאֹר. עַל הַיְאוֹר דַּוְקָא, וְלֹא עַל הַיָּם. וְאִם תֹּאמַר, הֲרֵי כָּתוּב (שמות יז) וּמַטְּךְ אֲשֶׁר הִכִּיתָ בּוֹ אֶת הַיְאֹר, וּמֹשֶׁה לֹא הִכָּה אֶלָּא בַּיָּם, וּקְרָאוֹ הַכָּתוּב יְאוֹר! אֶלָּא יְאוֹר הָיָה שֶׁהִכָּה אַהֲרֹן עַל יְדֵי מֹשֶׁה, וְשָׂמוֹ הַכָּתוּב שֶׁהוּא עָשָׂה.</p>\n<p>כְּמוֹ זֶה, (שם ז) וַיִּמָּלֵא שִׁבְעַת יָמִים אַחֲרֵי הַכּוֹת ה' אֶת הַיְאֹר. וְאַהֲרֹן הִכָּה. אֶלָּא (שעל זה) עַד שֶׁבָּא מִצַּד הַקָּדוֹשׁ בָּרוּךְ הוּא קְרָאוֹ הַכָּתוּב הַכּוֹת ה'. אַחַר כָּךְ קְרָאוֹ בַשֵּׁם שֶׁל מֹשֶׁה. וְנַעֲרֹתֶיהָ הֹלְכֹת - אוֹתָן שְׁאָר מֶרְכָּבוֹת שֶׁבָּאוֹת מִצַּד זֶה.</p>\n<p>וַתִּפְתַּח וַתִּרְאֵהוּ אֶת הַיֶּלֶד. וַתִּרְאֵהוּ?! וַתֵּרֶא הָיָה צָרִיךְ לוֹ לִכְתֹּב! מַה זֶּה וַתִּרְאֵהוּ? וַהֲרֵי אָמַר רַבִּי שִׁמְעוֹן, אֵין לְךְ דָּבָר בַּתּוֹרָה אוֹ אוֹת אַחַת בַּתּוֹרָה שֶׁאֵין בָּהּ סוֹדוֹת נִכְבָּדִים וְעֶלְיוֹנִים. אֶלָּא כָּךְ לָמַדְנוּ, רֹשֶׁם הַמֶּלֶךְ וְהַמַּלְכָּה נִמְצָא בּוֹ, וְהֵם רֹשֶׁם שֶׁל וָא\"ו הֵ\"א. מִיָּד - וַתַּחְמֹל עָלָיו וְגוֹ'. עַד כָּאן לְמַעְלָה. מִכָּאן וָהָלְאָה לְמַטָּה, פְּרָט לְפָסוּק זֶה שֶׁכָּתוּב וַתֵּתַצַּב אֲחֹתוֹ מֵרָחֹק. אָחוֹת שֶׁל מִי? אָחוֹת שֶׁל אוֹתוֹ שֶׁקָּרָא לִכְנֶסֶת יִשְׂרָאֵל אֲחוֹתִי, כְּמוֹ שֶׁנֶּאֱמַר (שיר ה) פִּתְחִי לִי אֲחוֹתִי. מֵרָחֹק, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה לא) מֵרָחוֹק ה' נִרְאָה לִי.</p>\n<p>מַה מַּשְׁמָע? מַשְׁמָע שֶׁאוֹתָם צַדִּיקִים, עַד שֶׁלֹּא יָרְדוּ לָעוֹלָם, נוֹדָעִים הֵם לְמַעְלָה לְגַבֵּי הַכֹּל, וְכָל שֶׁכֵּן מֹשֶׁה. וּמַשְׁמָע שֶׁנִּשְׁמוֹת הַצַּדִּיקִים נִמְשָׁכוֹת מִמָּקוֹם עֶלְיוֹן, כְּמוֹ שֶׁבֵּאַרְנוּ. וְסוֹד הַדָּבָר לָמַדְנוּ, שֶׁמַּשְׁמָע שֶׁאָב וָאֵם יֵשׁ לַנְּשָׁמָה, כְּמוֹ שֶׁיֵּשׁ אָב וָאֵם לַגּוּף בָּאָרֶץ.</p>\n<p>וּמַשְׁמָע שֶׁבְּכָל הַצְּדָדִים, בֵּין לְמַעְלָה בֵּין לְמַטָּה, הַכֹּל בָּא וְנִמְצָא מִזָּכָר וּנְקֵבָה. וַהֲרֵי בֵּאֲרוּ הַסּוֹד, שֶׁכָּתוּב (בראשית א) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה. הָאָרֶץ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. נֶפֶשׁ חַיָּה - נֶפֶשׁ אָדָם הָרִאשׁוֹן הָעֶלְיוֹן, כְּמוֹ שֶׁנִּתְבָּאֵר. בָּא רַבִּי אַבָּא וּנְשָׁקוֹ. אָמַר, וַדַּאי נָאֶה אָמַרְתָּ, וְכָּאן הוּא הַכֹּל.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה נָבִיא הַנֶּאֱמָן עַל כָּל שְׁאָר נְבִיאֵי הָעוֹלָם. בִּגְלַל זֶה לֹא הִשְׁתַּדֵּל בּוֹ כְּשֶׁהִסְתַּלֵּק מֵהָעוֹלָם, רַק הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהֶעֱלָהוּ לְפַרְגּוֹדוֹ. וְעַל כָּךְ עָלָה מֹשֶׁה בִּנְבוּאָה עֶלְיוֹנָה וּבִדְרָגוֹת נִכְבָּדוֹת מִכָּל נְבִיאֵי הָעוֹלָם, וּשְׁאָר הַנְּבִיאִים רָאוּ אַחַר כְּתָלִים גְּדוֹלִים.</p>"],[9522012370,"<p>וַיַּרְאֵנִי אֶת יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל (זכריה ג). מָה רָאָה? שֶׁהָיָה עוֹמֵד לִפְנֵי מַלְאָךְ וּמִתְלַבֵּשׁ בִּלְבוּשִׁים מְלֻכְלָכִים, עַד שֶׁיָּצָא הַכָּרוֹז וְאָמַר: הָסִירוּ הַבְּגָדִים הַצֹּאִים מֵעָלָיו. אָמַר רַבִּי יִצְחָק, כָּתוּב כָּאן וְעֹמֵד לִפְנֵי הַמַּלְאָךְ. מַה זֶּה לִפְנֵי הַמַּלְאָךְ? שֶׁהָיָה דָּן דִּינוֹ, אוֹתוֹ שֶׁכָּתוּב בּוֹ (קהלת ה) וְאַל תֹּאמַר לִפְנֵי הַמַּלְאָךְ כִּי שְׁגָגָה הִיא. מַה בָּא לְהַשְׁמִיעֵנוּ? שֶׁכָּל בֶּן אָדָם שֶׁלֹּא זוֹכֶה בָּעוֹלָם הַזֶּה לְהִתְעַטֵּף בְּעִטּוּף מִצְוָה וּלְהִתְלַבֵּשׁ בִּלְבוּשׁ מִצְוָה, כְּשֶׁנִּכְנָס בָּעוֹלָם הַהוּא עוֹמֵד בִּלְבוּשׁ טִנֹּפֶת שֶׁלֹּא צָרִיךְ, וְעוֹמֵד בַּדִּין עָלָיו.</p>\n<p>בֹּא וּרְאֵה, כַּמָּה לְבוּשִׁים מִזְדַּמְּנִים בְּאוֹתוֹ עוֹלָם, וְאוֹתוֹ הָאִישׁ שֶׁלֹּא זוֹכֶה בָּעוֹלָם הַזֶּה בִּלְבוּשֵׁי מִצְוָה, כְּשֶׁנִּכְנָס לָעוֹלָם הַהוּא מַלְבִּישִׁים אוֹתוֹ בִּלְבוּשׁ נוֹדָע אֶחָד לִפְנֵי בַּעֲלֵי הַגֵּיהִנֹּם, וְאוֹתוֹ לְבוּשׁ אוֹי לְמִי שֶׁמִּתְלַבֵּשׁ בּוֹ. שֶׁהֲרֵי כַּמָּה שׁוֹמְרֵי הַחֻקִּים עֲתִידִים לֶאֱחֹז בּוֹ, וּמַכְנִיסִים אוֹתוֹ לַגֵּיהִנֹּם. וּשְׁלֹמֹה הַמֶּלֶךְ צוֹוֵחַ וְאוֹמֵר: (קהלת ט) בְּכָל עֵת יִהְיוּ בְגָדֶיךְ לְבָנִים.</p>\n<p>לָמַדְנוּ בְּסוֹד סִפְרָא דִצְנִיעוּתָא, אַרְבָּעָה מְלָכִים יוֹצְאִים לְמוּל אַרְבָּעָה. תְּלוּיִים בָּהֶם כַּעֲנָבִים בְּאֶשְׁכּוֹל, צְרוּרִים בָּהֶם שִׁבְעָה רָצִים, מְעִידִים עֵדוּת, וְלֹא עוֹמְדִים בִּמְקוֹמָם.</p>\n<p>צִיצִית, מִצְוָה זוֹ הִיא לְהַזְכִּיר כָּל מִצְווֹת הַתּוֹרָה בִּשְׁבִילָהּ, כְּמוֹ שֶׁנֶּאֱמַר וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם אֶת כָּל מִצְות ה' וַעֲשִׂיתֶם אֹתָם (במדבר טו). זֶהוּ סִימַן הַמֶּלֶךְ לְהַזְכִּיר וְלַעֲשׂוֹת.</p>\n<p>כָּתוּב (שמות כח) וְעָשִׂיתָ צִּיץ זָהָב, וַהֲרֵי בֵּאַרְנוּ - סוֹד הַצִּיץ לְהִתְעַטֵּר בּוֹ כֹּהֵן גָּדוֹל. וְזֶהוּ צִיץ לְהִסְתַּכֵּל בּוֹ בָּעֵינַיִם, שֶׁהוּא סִימָן שֶׁל עוֹלָם הָעֶלְיוֹן שֶׁהִתְעַטֵּר בּוֹ כֹּהֵן גָּדוֹל.</p>\n<p>וּמִשּׁוּם זֶה הִסְתַּכְּלוּתוֹ מְכַפֶּרֶת עַל עַזּוּת פָּנִים, שֶׁלֹּא עוֹמֶדֶת לְפָנָיו אֶלָּא פְּנֵי אֱמֶת, סוֹד שֶׁל כָּל אֵלּוּ הַפָּנִים הָעֶלְיוֹנִים, שֶׁהֵם פְּנֵי אֱמֶת, פָּנִים שֶׁל אֱמֶת, שֶׁכְּלוּלִים בָּאֱמֶת שֶׁל יַעֲקֹב.</p>\n<p>צִיצִית הִיא נְקֵבָה, סוֹד עוֹלַם הַתַּחְתּוֹן, הִסְתַּכְּלוּת לְהַזְכִּיר. צִיץ זָכָר. צִיצִית נְקֵבָה, וְזֶה לְכָל אָדָם. צִיץ לַכֹּהֵן.</p>\n<p>וְשָׁנִינוּ, אָסוּר לְהִסְתַּכֵּל בַּשְּׁכִינָה, בִּגְלַל זֶה יֵשׁ תְּכֵלֶת, מִשּׁוּם שֶׁתְּכֵלֶת הִיא כִּסֵּא לְבֵית דָּוִד וְתִקּוּנוֹ. וְזֶהוּ פַּחַד מִלִּפְנֵי ה' לִפְחֹד מֵאוֹתוֹ מָקוֹם. וְעַל זֶה וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם אֶת כָּל מִצְות ה'. וְזֶה הַכִּסֵּא שֶׁדָּנִים בּוֹ דִּינֵי נְפָשׁוֹת, כְּמוֹ שֶׁפֵּרְשׁוּהָ, וְכָל הַגְּוָנִים טוֹבִים לַחֲלוֹם, פְּרָט לִתְכֵלֶת, שֶׁהוּא כִּסֵּא שֶׁעוֹלֶה בְּדִין הַנְּפָשׁוֹת.</p>\n<p>כָּתוּב וְנָתְנוּ עַל צִיצִת הַכָּנָף פְּתִיל תְּכֵלֶת. וְנָתְנוּ עַל הַכָּנָף לֹא כָתוּב, אֶלָּא וְנָתְנוּ עַל צִיצִת. שֶׁזֶּהוּ שֶׁמְּכַסֶּה עַל שְׁאָר הַחוּטִים.</p>\n<p>וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם. וְכָתוּב (דברים כה) זָכוֹר אֵת אֲשֶׁר עָשָׂה לְךְ עֲמָלֵק. מָה הַטַּעַם זֶה? אֶלָּא מָשָׁל לְבֵן שֶׁפָּרַץ גָּדֵר וּנְשָׁכוֹ כֶלֶב - כָּל זְמַן שֶׁאָבִיו רוֹצֶה לְהוֹכִיחַ אֶת בְּנוֹ, הָיָה אוֹמֵר: זָכוֹר כְּשֶׁנָּשַׁךְ אוֹתְךְ הַכֶּלֶב! גַּם כָּאן - וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם, שֶׁזֶּהוּ מָקוֹם שֶׁעוֹלוֹת הַנְּשָׁמוֹת לְהִדּוֹן.</p>\n<p>כְּמוֹ זֶה - (במדבר כא) וְהָיָה כָּל הַנָּשׁוּךְ וְרָאָה אֹתוֹ וָחָי. לָמָּה? אֶלָּא כְּשֶׁמַּעֲלֶה אֶת עֵינָיו וְרוֹאֶה דְמוּת אוֹתוֹ שֶׁנְּשָׁכוֹ, הָיָה פּוֹחֵד וּמִתְפַּלֵּל לִפְנֵי ה', וְהָיָה יוֹדֵעַ שֶׁהוּא עֹנֶשׁ הָרְשָׁעִים. כָּל זְמַן שֶׁהַבֵּן רוֹאֶה רְצוּעַת אָבִיו, פּוֹחֵד מֵאָבִיו. נִצּוֹל מֵהָרְצוּעָה - נִצּוֹל מֵהַכֹּל. מִי גָרַם לוֹ לְהִנָּצֵל? זֶה שֶׁרָאָה בְעֵינָיו אוֹתָהּ רְצוּעָה - אוֹתָהּ רְצוּעָה גָרְמָה לוֹ לְהִנָּצֵל. וְלָכֵן, וְרָאָה אֹתוֹ וָחָי. רָאָה רְצוּעָה שֶׁמַּלְקָה אוֹתוֹ, וְהִיא עָשְׂתָה לוֹ לְהִנָּצֵל. גַּם כָּךְ וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם - וַעֲשִׂיתֶם וַדַּאי. וְאִם לֹא - הֲרֵי הָרְצוּעָה, שֶׁזּוֹ תִגְרֹם לָכֶם לָשׁוּב לַעֲבוֹדָתִי תָמִיד, וְאָז וַעֲשִׂיתֶם.</p>\n<p>וְלֹא תָתוּרוּ אַחֲרֵי לְבַבְכֶם, יִמְנַע מִכֶּם דְּרָכִים רָעִים אֲחֵרִים, וַדַּאי לֹא תָתוּרוּ וְלֹא תַעֲשׂוּ רָעוֹת. וְעַל זֶה עוֹלֶה גָוֶן תְּכֵלֶת. זוֹ תְכֵלֶת דּוֹמָה לְכִסֵּא הַכָּבוֹד. מַה כִּסֵּא הַכָּבוֹד עוֹשֶׂה אֶת הָאָדָם לָלֶכֶת בְּדֶרֶךְ יָשָׁר לְזַכּוֹתוֹ, גַּם תְּכֵלֶת זוֹ עוֹשָׂה אֶת הָאָדָם לָלֶכֶת בְּדֶרֶךְ יָשָׁר. וַדַּאי שֶׁהַכֹּל יֵשׁ לִפְחֹד מִמָּקוֹם זֶה לָלֶכֶת יָשָׁר.</p>\n<p>כָּתוּב (ישעיה כד) מִכְּנַף הָאָרֶץ זְמִרֹת שָׁמַעְנוּ פְּרִי לַצַּדִּיק וָאֹמַר רָזִי לִי וְגוֹ'. מִכְּנַף הָאָרֶץ - זֶה כְּנַף הַצִּיצִית, שֶׁהוּא כְּנַף הָאָרֶץ. זְמִרֹת שָׁמַעְנוּ - אֵלּוּ שְׁאָר הַחוּטִים שֶׁיּוֹצְאִים וּתְלוּיִים מִמָּקוֹם עֶלְיוֹן תּוֹךְ אוֹתָם שְׁבִילִים עֶלְיוֹנִים שֶׁיּוֹצְאִים מֵחָכְמָה עֶלְיוֹנָה. צְבִי לַצַּדִּיק - זֶה צַדִּיק חַי הָעוֹלָמִים, שֶׁאוֹתָם חוּטִים אֵלּוּ יָפְיוֹ, שֶׁהֲרֵי מִמֶּנּוּ יוֹצְאִים, וְכָל חוּט כָּלוּל בִּשְׁנֵי צְדָדִים. וּכְשֶׁהִסְתַּכַּלְתִּי, אָמַרְתִּי: רָזִי לִי רָזִי לִי. שֶׁהֲרֵי מִתּוֹךְ סוֹד עֶלְיוֹן שֶׁל כָּל הָאֱמוּנָה יוֹצְאִים. וּכְשֶׁהִסְתַּכַּלְתִּי בַתְּכֵלֶת וְרָאִיתִי רְצוּעָה לְהַלְקוֹת, מָקוֹם יִרְאָה לִפְחֹד, אָמַרְתִּי: אוֹי לִי שֶׁבְּנֵי אָדָם לֹא יוֹדְעִים לְהַשְׁגִּיחַ וּלְהִסְתַּכֵּל עַל מַה נֶּעֱנָשִׁים לַשֶּׁקֶר. בָּזֶה בֹּגְדִים בָּגָדוּ, שֶׁהֲרֵי קוֹרְאִים קְרִיאַת שְׁמַע לְלֹא צִיצִית וּמְעִידִים עֵדוּת שֶׁקֶר, וְאֵלּוּ הֵם בּוֹגְדִים שֶׁבָּגָדוּ, מְשַׁקְּרִים בְּעַצְמָם.</p>\n<p>וּבֶגֶד בּוֹגְדִים בָּגָדוּ - לְבוּשָׁם בְּלִי צִיצִית, נִקְרָא בֶּגֶד בּוֹגְדִים. לְבוּשׁ שֶׁל אוֹתָם בּוֹגְדִים שֶׁבָּגָדוּ, שֶׁמְּשַׁקְּרִים וּמְעִידִים עֵדוּת שֶׁקֶר בְּכָל יוֹם. אוֹי לָהֶם! אוֹי לְנַפְשָׁם! שֶׁעוֹלִים בְּאוֹתוֹ כִּסֵּא תְכֵלֶת לְהִדּוֹן, וַעֲלֵיהֶם כָּתוּב (תהלים קא) דֹּבֵר שְׁקָרִים לֹא יִכּוֹן לְנֶגֶד עֵינָי. אוֹתוֹ בֶּגֶד שֶׁלָּהֶם נוֹדָע לְכָל בַּעֲלֵי הַדִּינִים. אוֹי לָהֶם! שֶׁאֵין לָהֶם חֵלֶק בָּעוֹלָם הַבָּא. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁלְּבוּשֵׁיהֶם וְתִקּוּנֵיהֶם נוֹדָעִים לְמַעְלָה לְהֵיטִיב לָהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>מִצְוָה זוֹ מִצְוַת צִיצִית, כּוֹלֶלֶת תְּכֵלֶת וְלָבָן, דִּין וְרַחֲמִים בְּאֵשׁ. אֵשׁ לְבָנָה לֹא אוֹכֶלֶת, תְּכֵלֶת אוֹכֶלֶת וּמַשְׁמִידָה. (דברי הימים ב ז) וַתֹּאכַל הָעֹלָה. לָבָן מִיָּמִין, תְּכֵלֶת מִשְּׂמֹאל. הָעַמּוּד הָאֶמְצָעִי מְיַחֵד בֵּין שְׁנֵיהֶם - יָרֹק. וּמִשּׁוּם זֶה פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, מֵאֵימָתַי קוֹרִין אֶת שְׁמַע בְּשַׁחֲרִית? מִשֶּׁיַּכִּיר בֵּין תְּכֵלֶת לְלָבָן. וּמִשּׁוּם זֶה הִתְקִינוּ לְקָרְאָהּ בְּיִחוּד.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כַּמָּה עֵדִים עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָעִיד בָּהֶם בְּנֵי אָדָם, וְכֻלָּם בְּעֵצָה וּבְעֵדוּת עוֹמְדִים מוּלוֹ. קָם בַּבּקֶר, מוֹשִׁיט רַגְלָיו לָלֶכֶת - עֵדִים עוֹמְדִים מוּלוֹ, מַכְרִיזִים וְאוֹמְרִים: (שמואל א ב) רַגְלֵי חֲסִידָיו יִשְׁמֹר וְגוֹ'. (קהלת ד) שְׁמֹר רַגְלְךְ כַּאֲשֶׁר תֵּלֵךְ. (משלי ד) פַּלֵּס מַעְגַּל רַגְלֶךְ. פּוֹתֵחַ עֵינָיו לְהִסְתַּכֵּל בָּעוֹלָם - הָעֵדִים אוֹמְרִים: (שם) עֵינֶיךְ לְנֹכַח יַבִּיטוּ. קָם לְדַבֵּר - הָעֵדִים אוֹמְרִים: (תהלים לד) נְצֹר לְשׁוֹנְךְ מֵרָע וְגוֹ'. מוֹשִׁיט יָדָיו בְּדִבְרֵי הָעוֹלָם - הָעֵדִים אוֹמְרִים: (שם) סוּר מֵרָע וַעֲשֵׂה טוֹב.</p>\n<p>אִם מְצַיֵּת לָהֶם - יָפֶה, וְאִם לֹא - כָּתוּב (זכריה ג) וְהַשָּׂטָן עֹמֵד עַל יְמִינוֹ לְשִׂטְנוֹ. כֻּלָּם מְעִידִים עָלָיו בַּחֲטָאָיו לְמַעְלָה. אִם רוֹצֶה הָאִישׁ לְהִשְׁתַּדֵּל בַּעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא - כֻּלָּם מְעִידִים סָנֵגוֹרְיָא לְפָנָיו, וְעוֹמְדִים לְהָעִיד עָלָיו טוֹבוֹת בְּשָׁעָה שֶׁצָּרִיךְ לוֹ.</p>\n<p>קָם בַּבּקֶר, מְבָרֵךְ כַּמָּה בְרָכוֹת. מֵנִיחַ תְּפִלִּין בְּרֹאשׁוֹ בֵּין עֵינָיו - רוֹצֶה לְהָרִים רֹאשׁוֹ, רוֹאֶה שֵׁם הַקָּדוֹשׁ הָעֶלְיוֹן אָחוּז וְרָשׁוּם עַל רֹאשׁוֹ. וּרְצוּעוֹת תְּלוּיוֹת לוֹ מִצַּד זֶה וּמִצַּד זֶה עַל לִבּוֹ. הֲרֵי מִסְתַּכֵּל בִּכְבוֹד רִבּוֹנוֹ. מוֹשִׁיט יָדָיו, רוֹאֶה יָד אַחֶרֶת מִתְקַשֶּׁרֶת בְּקֶשֶׁר הַשֵּׁם הַקָּדוֹשׁ, מַחֲזִיר יָדוֹ וּמִסְתַּכֵּל בִּכְבוֹד רִבּוֹנוֹ. מִתְעַטֵּף בְּעִטּוּף שֶׁל מִצְוָה בְּאַרְבַּע זָוִיּוֹת כְּסוּתוֹ, אַרְבָּעָה מְלָכִים יוֹצְאִים לִכְנֶגֶד אַרְבָּעָה. אַרְבָּעָה עֵדֵי אֱמֶת שֶׁל הַמֶּלֶךְ, תְּלוּיִים מֵאַרְבַּע זָוִיּוֹת, וּתְלוּיִים בָּהֶם כַּעֲנָבִים בָּאֶשְׁכּוֹל.</p>\n<p>מָה אֶשְׁכּוֹל שֶׁהוּא אֶחָד וּתְלוּיִים בּוֹ כַּמָּה עֲנָבִים, מִצַּד זֶה וּמִצַּד זֶה, כָּךְ זֶה מִצְוָה אַחַת, וּתְלוּיִים בָּהּ כַּמָּה עֲנָבִים זַגִּים וּזְמוֹרוֹת צְרוּרִים בָּהֶם. שִׁבְעָה רָצִים אֵלּוּ הֵם שִׁבְעָה צְרוֹרוֹת שֶׁל תְּכֵלֶת שֶׁצָּרִיךְ לִכְרֹךְ בָּהּ בְּכָל אֶחָד וְאֶחָד, אוֹ לְהַגְדִּיל עַד שְׁלֹשָׁה עָשָׂר. מִי שֶׁיּוֹסִיף, לֹא יוֹסִיף עַל שְׁלֹשָׁה עָשָׂר. מִי שֶׁיְּמַעֵט, לֹא יְמַעֵט מִשִּׁבְעָה.</p>\n<p>וְלָמַדְנוּ, תְּכֵלֶת זוֹ הִיא סוֹד דָּוִד הַמֶּלֶךְ, וְזֶה חוּט אַבְרָהָם שֶׁזָּכָה בּוֹ לְבָנָיו אַחֲרָיו. מַה זֶּה תְּכֵלֶת? תַּכְלִית הַכֹּל. (ודאי) רַבִּי יְהוּדָה אוֹמֵר, כִּסֵּא הַכָּבוֹד נִקְרָא.</p>\n<p>רַבִּי יִצְחָק אָמַר, שֶׁבַע כְּרִיכוֹת שֶׁהִיא שְׁכִינָה שְׁבִיעִית הַכֹּל בְּוַדַּאי. שֶׁהֲרֵי הִיא מִתְבָּרֶכֶת מִשִּׁשָּׁה אֲחֵרִים עַל יְדֵי הַצַּדִּיק. וְאִם שְׁלֹשָׁה עָשָׂר, שְׁלֹשָׁה עָשָׂר הֵם, כְּמוֹ שֶׁבֵּאֲרוּהָ בִּשְׁלֹשׁ עֶשְׂרֵה מִדּוֹת, וְזֶהוּ פֶּתַח הַכֹּל.</p>\n<p>וְהִיא חוּט אֶחָד, וּרְשׁוּמָה בִגְוָנֶיהָ, וְצִבְעָהּ יוֹצֵא מִדָּג אֶחָד שֶׁהוֹלֵךְ בְּיָם כִּנֶּרֶת. וְכִנֶּרֶת נִקְרֵאת עַל שְׁמָהּ. וְעַל זֶה כִּנּוֹר הָיָה תָלוּי מֵעַל מִטַּת דָּוִד, שֶׁהֲרֵי (של דוד) וַדַּאי הוּא כִּנּוֹר דָּוִד מְנַגֵּן מֵאֵלָיו לַמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן, וְלָכֵן גְּוָנָיו עוֹלִים עַד הָרָקִיעַ, וּמֵהָרָקִיעַ עַד הַכִּסֵּא.</p>\n<p>וְכָאן כָּתוּב מִצְוָה, כְּמוֹ שֶׁנֶּאֱמַר (מלכים ביח) מִצְוַת הַמֶּלֶךְ הִיא. (אסתר ג) מַדּוּעַ אַתָּה עוֹבֵר אֵת מִצְוַת הַמֶּלֶךְ. כִּי מִצְוַת הַמֶּלֶךְ. וְלָמַדְנוּ, יְסוֹד וְשֹׁרֶשׁ בַּמֶּלֶךְ מִתְעַטְּרִים כְּאֶחָד, וְזוֹהִי זִכָּרוֹן וּפֶתַח לְכָל שְׁאָר הַכְּתָרִים, שֶׁכָּתוּב (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק. וְכָתוּב זֶה הַשַּׁעַר לַה'. וְעַל זֶה כָּתוּב וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם אֶת מִצְות ה', לְהַכְלִיל בָּזֶה כָּל שְׁאָר הַכְּתָרִים. וְלָכֵן הֵם מְעִידִים עֵדוּת וְלֹא עוֹמְדִים בִּמְקוֹמָם, מִשּׁוּם שֶׁהִיא מִצְוַת.</p>\n<p>וְשָׁנִינוּ, תַּשְׁמִישֵׁי מִצְוָה נִזְרָקִין. וְאִם תֹּאמַר, הֲרֵי לוּלָב וַעֲרָבָה תַּשְׁמִישֵׁי קְדֻשָּׁה הֵם, לָמָּה נִזְרָקִים? אֶלָּא תַּשְׁמִישֵׁי קְדֻשָּׁה, מִשּׁוּם שֶׁרְשׁוּמִים בִּכְתִיבַת הַשֵּׁם הַקָּדוֹשׁ.</p>\n<p>אָמַר רַבִּי יִצְחָק, אוֹתָם חוּטִים, לְהַרְאוֹת אֵיךְ תְּלוּיִים מִכָּאן וּמִכָּאן לְאַרְבָּעָה צִדְדֵי הָעוֹלָם מִמָּקוֹם זֶה, וְהִיא שׁוֹלֶטֶת עַל הַכֹּל בְּסוֹד הַלֵּב, שֶׁהִיא לֵב כָּל הָעוֹלָם הַזֶּה וְלֵב הָעֶלְיוֹנִים, וּתְלוּיָה בַּלֵּב הָעֶלְיוֹן, וְהַכֹּל הוּא בַּלֵּב שֶׁיּוֹצֵא מֵחָכְמָה עֶלְיוֹנָה. אָמַר רַבִּי יִצְחָק, שִׁעוּר שֶׁל זֶה (וארך) שֶׁל זֶה נִתְבָּאֵר בְּאוֹתִיּוֹת חֲקוּקוֹת שֶׁל רַבִּי אֶלְעָזָר.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: מִי שֶׁרוֹצֶה לָלֶכֶת אַחַר יִרְאָתִי, יֵלֵךְ אַחַר הַלֵּב הַזֶּה וְאַחֲרֵי הָעֵינַיִם שֶׁעוֹמְדִים עָלֶיהָ. מִי הֵם עֵינַיִם אֵלֶּה? כְּמוֹ שֶׁנֶּאֱמַר (תהלים לד) עֵינֵי ה' אֶל צַדִּיקִים. אֲבָל אַתֶּם, לֹא תָתוּרוּ אַחֲרֵי לְבַבְכֶם וְאַחֲרֵי עֵינֵיכֶם. מָה הַטַּעַם? מִשּׁוּם שֶׁאַתֶּם זֹּנִים אַחֲרֵיהֶם.</p>\n<p>אָמַר רַבִּי חִיָּיא, מָה הַטַּעַם כָּאן יְצִיאַת מִצְרַיִם, שֶׁכָּתוּב אֲשֶׁר הוֹצֵאתִי אֶתְכֶם מֵאֶרֶץ מִצְרַיִם? אֶלָּא מִשּׁוּם שֶׁכְּשֶׁיָּצְאוּ מִמִּצְרַיִם, נִכְנְסוּ בְּחֵלֶק זֶה, וּבָזֶה הָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא הֶרֶג בְּמִצְרַיִם. וְלָכֵן בִּמְקוֹמוֹ נִזְכַּר, וּבִמְקוֹמוֹ הִזְהִירָם בָּזֶה. מַה זֶּה בִּמְקוֹמוֹ? מִשּׁוּם שֶׁמִּצְוָה זוֹ הִיא מְקוֹמָהּ.</p>\n<p>שָׁנָה רַבִּי יֵיסָא, כָּתוּב (מיכה ז) כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת. כִּימֵי?! כַּיּוֹם הָיָה צָרִיךְ לוֹ לִכְתֹּב, שֶׁהֲרֵי בִּזְמַן אֶחָד יָצְאוּ, וְלֹא הִתְעַכְּבוּ! אֶלָּא כְּמוֹ אוֹתָם יָמִים עֶלְיוֹנִים שֶׁהִתְבָּרְכָה בָהֶם כְּנֶסֶת יִשְׂרָאֵל, כָּךְ עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹצִיא אֶת יִשְׂרָאֵל מֵהַגָּלוּת, וְאָז כָּתוּב (ישעיה יב) וַאֲמַרְתֶּם בַּיּוֹם הַהוּא הוֹדוּ לַה' קִרְאוּ וְגוֹ', זַמְּרוּ ה' כִּי גֵאוּת עָשָׂה מוּדַעַת זֹּאת בְּכָל הָאָרֶץ. מַה זֶּה מוּדַעַת זֹּאת? מִשּׁוּם שֶׁעַכְשָׁו נוֹדְעָה זֹּאת בְּעִטּוּף מִצְוָה. בְּאוֹתוֹ זְמַן תִּוָּדַע זֹּאת בְּכַמָּה מִנְהָגִים שֶׁלָּהּ שֶׁיַּעֲשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹת וְנִסִּים בָּעוֹלָם, אָז כָּתוּב (זכריה יד) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלֹךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522012371,"<p>וַיִּקַּח קֹרַח בֶּן יִצְהָר בֶּן קְהָת בֶּן לֵוִי וְגוֹ'. רַבִּי אַבָּא פָּתַח, (תהלים יט) הַנֶּחֱמָדִים מִזָּהָב וּמִפָּז רַב וּמְתוּקִים מִדְּבַשׁ וְנֹפֶת צוּפִים. כַּמָּה עֶלְיוֹנִים הֵם דִּבְרֵי הַתּוֹרָה, כַּמָּה מְכֻבָּדִים הֵם, אֲהוּבִים הֵם לְמַעְלָה, אֲהוּבִים הֵם לְכֻלָּם, בִּגְלַל שֶׁהֵם שֵׁם קָדוֹשׁ. וְכָל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, מִשְׁתַּדֵּל בַּשֵּׁם הַקָּדוֹשׁ וְנִצָּל מֵהַכֹּל. נִצָּל בָּעוֹלָם הַזֶּה, וְנִצָּל בָּעוֹלָם הַבָּא. בֹּא וּרְאֵה, כָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, אָחוּז בְּעֵץ הַחַיִּים. כֵּיוָן שֶׁאָחוּז בּוֹ - בַּכֹּל אָחוּז, שֶׁכָּתוּב (משלי ג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ וְגוֹ'.</p>\n<p>רַבִּי יִצְחָק אָמַר, כָּל מִי שֶׁיִּשְׁתַּדֵּל בַּתּוֹרָה, יֵשׁ לוֹ חֵרוּת מֵהַכֹּל, חֵרוּת מִמִּיתָה כְּמוֹ שֶׁאָמַרְנוּ, מִשּׁוּם שֶׁחֵרוּת שׁוֹרָה עָלָיו וַאֲחוּזָה בוֹ. אִלּוּ יִשְׂרָאֵל מִתְעַטְּרִים בַּתּוֹרָה, יִנָּצְלוּ מֵהַכֹּל, וְלֹא יִמָּצְאוּ בַגָּלוּת. וְזֶהוּ שֶׁכָּתוּב (אלו ישראל משמרים את התורה, ינצלו מהכל, ולא ימצאו בגלות. כתוב) (שמות לב) חָרוּת עַל הַלֻּחֹת, אַל תִּקְרֵי חָרוּת אֶלָּא חֵרוּת. וְחֵרוּת זוֹ (בארוה) נִמְצֵאת בַּתּוֹרָה. הַתּוֹרָה הִיא כֹּחַ הַיָּמִין, כְּמוֹ שֶׁנֶּאֱמַר (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ. וְהַשְּׂמֹאל נִכְלָל בַּיָּמִין. מִי שֶׁעוֹשֶׂה יָמִין שְׂמֹאל וּשְׂמֹאל יָמִין, הֲרֵי הוּא כְּאִלּוּ מַחֲרִיב עוֹלָם.</p>\n<p>בֹּא וּרְאֵה, אַהֲרֹן יָמִין, לְוִיִּם שְׂמֹאל. קֹרַח רָצָה לַעֲשׂוֹת חִלּוּף הַיָּמִין לַשְּׂמֹאל, וּמִשּׁוּם זֶה נֶעֱנַשׁ. וְלֹא עוֹד, אֶלָּא שֶׁנִּמְצָא בּוֹ לָשׁוֹן הָרָע, וְנֶעֱנַשׁ בַּכֹּל. רַבִּי יְהוּדָה אָמַר, הַשְּׂמֹאל נִכְלל תָּמִיד בַּיָּמִין. קֹרַח רָצָה לְהַחֲלִיף תִּקּוּן שֶׁלְּמַעְלָה וּלְמַטָּה, בִּגְלַל זֶה נֶאֱבַד מִלְמַעְלָה וּלְמַטָּה.</p>\n<p>וַיִּקַּח קֹרַח. מַה זֶּה וַיִּקַּח? לָקַח עֵצָה רָעָה לְעַצְמוֹ. כָּל מִי שֶׁרוֹדֵף אַחַר מַה שֶּׁאֵינוֹ שֶׁלּוֹ - זֶה בּוֹרֵחַ מִמֶּנּוּ, וְלֹא עוֹד, אֶלָּא מַה שֶּׁיֵּשׁ לוֹ - נֶאֱבָד מִמֶּנּוּ. קֹרַח רָדַף אַחַר מַה שֶּׁאֵינוֹ שֶׁלּוֹ - אֶת שֶׁלּוֹ אִבֵּד, וְאַחֵר לֹא הִרְוִיחַ.</p>\n<p>קֹרַח הָלַךְ בְּמַחֲלֹקֶת. מַה זֶּה מַחֲלֹקֶת? פְּלוּגְתָּא. מַחֲלֹקֶת שֶׁלְּמַעְלָה וּלְמַטָּה. וּמִי שֶׁרוֹצֶה לְחַלֵּק תִּקּוּן הָעוֹלָם, נֶאֱבָד מִכָּל הָעוֹלָמוֹת. מַחֲלֹקֶת הִיא מַחֲלֹקֶת שֶׁל הַשָּׁלוֹם, וּמִי שֶׁחוֹלֵק עַל הַשָּׁלוֹם חוֹלֵק עַל הַשֵּׁם הַקָּדוֹשׁ, מִשּׁוּם שֶׁשֵּׁם הַקָּדוֹשׁ נִקְרָא שָׁלוֹם.</p>\n<p>בֹּא וּרְאֵה, אֵין הָעוֹלָם עוֹמֵד אֶלָּא עַל שָׁלוֹם. כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, לֹא יָכֹל לְהִתְקַיֵּם וְלַעֲמֹד, עַד שֶׁבָּא וְהִשְׁרָה עָלָיו שָׁלוֹם, וּמַהוּ? שַׁבָּת, שֶׁהִיא שְׁלוֹם הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים, וְאָז עָמַד וְהִתְקַיֵּם הָעוֹלָם. וּמִי שֶׁחוֹלֵק עָלָיו, יֹאבַד מֵהָעוֹלָם.</p>\n<p>צְלָפְחָד חָלַק עַל שַׁבָּת, שֶׁהָיָה (במדבר טו) מְקוֹשֵׁשׁ עֵצִים. מִי אוֹתָם עֵצִים? אוֹתָם עֵצִים אֲחֵרִים, כְּמוֹ שֶׁאָמַרְנוּ. וְאֵלּוּ דִּבְרֵי (אילנות) חֹל, וְחֹל בַּקֹּדֶשׁ לֹא שׁוֹרֶה, (מכאן והלאה דברי חל בשבת אסור ודאי) שֶׁחָלַק עַל שָׁלוֹם שֶׁלְּמַעְלָה.</p>\n<p>רַבִּי יוֹסֵי אָמַר, כָּתוּב (תהלים קיט) שָׁלוֹם רָב לְאֹהֲבֵי תוֹרָתֶךְ וְגוֹ'. הַתּוֹרָה הִיא שָׁלוֹם, שֶׁכָּתוּב (משלי ג) וכל נתיבתיה שלום. וקרח בא לפגם שלום שלמעלה ומטה, ומשום זה נענש מלמעלה ומטה.</p>"],[9522012372,"<p>וַיָּקֻמוּ לִפְנֵי מֹשֶׁה וְגוֹ'. פָּסוּק זֶה פֵּרְשׁוּהוּ הַחֲבֵרִים. רַבִּי שִׁמְעוֹן אָמַר, קְרִאֵי מוֹעֵד, קְרִאֵי כָּתוּב, חָסֵר יוֹ\"ד. לָמָּה קְרִאֵי? אֶלָּא כָּךְ הוּא - מַלְכוּת הָאָרֶץ כְּעֵין מַלְכוּת הָרָקִיעַ. וְסוֹד זֶה - כָּל אוֹתָם כְּתָרִים עֶלְיוֹנִים שֶׁהַשֵּׁם הַקָּדוֹשׁ נֶאֱחָז בָּהֶם, כֻּלָּם מְזֻמָּנִים מִמָּקוֹם שֶׁנִּקְרָא קֹדֶשׁ, זֶהוּ שֶׁכָּתוּב (ויקרא כג) מִקְרָאֵי קֹדֶשׁ. וְאֵימָתַי? בְּשָׁעָה שֶׁמּוֹעֵד זָמִין בָּעוֹלָם. כְּמוֹ שֶׁאוֹתָם כְּתָרִים עֶלְיוֹנִים שֶׁמְּזֻמָּנִים מִקֹּדֶשׁ הָעֶלְיוֹן, כָּךְ גַּם קֹדֶשׁ תַּחְתּוֹן זָמִין לְחֵילָיו לְעַטְּרָם וּלְהַעֲלוֹתָם.</p>\n<p>קֹדֶשׁ עֶלְיוֹן יָדוּעַ, קֹדֶשׁ תַּחְתּוֹן חָכְמַת שְׁלֹמֹה, כָּךְ גַּם הִיא מְזֻמֶּנֶת לְכָל חֵילֶיהָ, וְאוֹתָם חֲיָלוֹת כֻּלָּם עֲתִידִים לְהִתְעַטֵּר בְּקֹדֶשׁ תַּחְתּוֹן זֶה בִּזְמַן שֶׁמּוֹעֵד שָׁרוּי בָּעוֹלָם. וּכְמוֹ שֶׁחֵילֶיהָ עוֹמְדִים לְמַעְלָה, כָּךְ גַּם עוֹמְדִים מְמֻנֵּי הָעַמִּים כְּדֻגְמָתָהּ לְמַטָּה, וְעַל זֶה נִקְרְאוּ קְרִאֵי מוֹעֵד. וּמִשּׁוּם שֶׁהֵם לְמַטָּה, קְרִאֵי מוֹעֵד חָסֵר, (כמושלמעלה) אֲבָל הֵם בִּשְׁלֵמוּת יְתֵרָה.</p>\n<p>אַנְשֵׁי שֵׁם וַדַּאי, וְלֹא אַנְשֵׁי ה'. וְזֶהוּ סוֹד (ויקרא כד) בְּנָקְבוֹ שֵׁם יוּמָת, וּבֵאַרְנוּ, וְעַל זֶה נִקְרָא כָּאן אַנְשֵׁי שֵׁם וַדַּאי. כֵּיוָן שֶׁמִּצַּד הַגְּבוּרָה בָּאִים, אַנְשֵׁי שֵׁם הֵם, הֲרֵי שִׁבְחָם יָתֵר, אֲבָל הֵם לָקְחוּ לְעַצְמָם וְנֶאֶחְזוּ בְמַחֲלֹקֶת.</p>"],[9522012373,"<p>בֹּקֶר וְיֹדַע ה' אֶת אֲשֶׁר לוֹ. לָמָּה בֹּקֶר? וְלָמָּה קָדוֹשׁ וְלֹא טָהוֹר? אֶלָּא הֵם בָּאוּ מִצַּד שֶׁל טָהוֹר, וְקָדוֹשׁ הַכֹּהֵן. אָמַר מֹשֶׁה, בֹּקֶר, כְּשֶׁכֶּתֶר הַכֹּהֵן מִתְעוֹרֵר בָּעוֹלָם - אִם אַתֶּם כֹּהֲנִים, הֲרֵי בֹּקֶר, עִבְדוּ עֲבוֹדַת הַבֹּקֶר, וְאָז וְיֹדַע ה' אֶת אֲשֶׁר לוֹ וְאֶת הַקָּדוֹשׁ. אֶת אֲשֶׁר לוֹ - סְתָם, זֶה הַלְוִיִּם. וְאֶת הַקָּדוֹשׁ - זֶה הַכֹּהֵן. אָז וְהִקְרִיב אֵלָיו. וְאֵין מִי שֶׁיַּבְחִין בַּדָּבָר אֶלָּא בֹּקֶר. אִם תִּהְיוּ רְאוּיִים לְהִשָּׁאֵר בְּצַד הַדִּין, בּקֶר לֹא יִסְבֹּל אֶתְכֶם, שֶׁהֲרֵי לֹא זְמַנּוֹ הוּא. וְאִם תִּתְרָאוּ לְהִשָּׁאֵר בְּחֶסֶד, הֲרֵי זְמַנּוֹ הוּא, וְתִשָּׁאֲרוּ אֶצְלוֹ וִיקַבֵּל אֶתְכֶם.</p>\n<p>בַּמֶּה? בַּקְּטֹרֶת. שֶׁהֲרֵי קְטֹרֶת צְרִיכָה שׁוֹשְׁבִין לְהִתְקַטֵּר עַל יָדוֹ בַּכֹּל וּלְהִתְקַשֵּׁר. מִי הַשּׁוֹשְׁבִין? זֶה הַכֹּהֵן. וּמִשּׁוּם כָּךְ, וְהָיָה הָאִישׁ אֲשֶׁר יִבְחַר ה' הוּא הַקָּדוֹשׁ, וְלֹא הַטָּהוֹר. שְׁתֵּי דְרָגוֹת הֵן: קָדוֹשׁ וְטָהוֹר. כֹּהֵן קָדוֹשׁ, לֵוִי טָהוֹר. וְעַל זֶה הַקָּדוֹשׁ כָּתוּב.</p>"],[9522012374,"<p>וַיִּפְּלוּ עַל פְּנֵיהֶם וַיֹּאמְרוּ אֵל אֱלֹהֵי הָרוּחֹת לְכָל בָּשָׂר. בֹּא וּרְאֵה, מֹשֶׁה וְאַהֲרֹן מָסְרוּ עַצְמָם לְמִיתָה, בַּמֶּה? מִשּׁוּם שֶׁכָּתוּב וַיִּפְּלוּ עַל פְּנֵיהֶם וַיֹּאמְרוּ אֵל אֱלֹהֵי הָרוּחֹת. רוּחֹת כָּתוּב חָסֵר וָא\"ו. וּמִשּׁוּם זֶה עֵץ הַמָּוֶת הוּא, וּבְכָל מָקוֹם נְפִילַת אַפַּיִם לְאוֹתוֹ מָקוֹם. וְעַל זֶה אֵל אֱלֹהֵי, אֵל - זֶהוּ שֶׁכָּתוּב (תהלים ז) וְאֵל זֹּעֵם בְּכָל יוֹם. אֱלֹהֵי הָרוּחֹת - שֶׁהוּא מְקוֹם צְרוֹר נִשְׁמוֹת הָעוֹלָם, וְכָל הַנְּשָׁמוֹת לְשָׁם עוֹלוֹת, וּמִשָּׁם בָּאוֹת. (שם נראות).</p>\n<p>רַבִּי יְהוּדָה פָּתַח, (איוב לד) שִׁמְעוּ חֲכָמִים מִלָּי וְיֹדְעִים הַאֲזִינוּ לִי. פָּסוּק זֶה אֱלִיהוּא אֲמָרוֹ. בֹּא וּרְאֵה מַה כָּתוּב, (שם לב) וּבִשְׁלֹשֶׁת רֵעָיו חָרָה אַפּוֹ עַל אֲשֶׁר לֹא מָצְאוּ מַעֲנֶה וְגוֹ'. שֶׁהֲרֵי הֵם הָיוּ אוֹמְרִים דְּבָרִים, וְאִיּוֹב לֹא הָיָה מִתְנַחֵם עֲלֵיהֶם. מִכָּאן לָמַדְנוּ, מִי שֶׁנִּכְנָס לְנַחֵם אֶת הָאָבֵל, צָרִיךְ לְיַסֵּד דְּבָרִים בַּתְּחִלָּה, שֶׁהֲרֵי חֲבֵרָיו שֶׁל אִיּוֹב הָיוּ אוֹמְרִים דִּבְרֵי אֱמֶת, אֲבָל לְנַחֲמוֹ לֹא, מִשּׁוּם שֶׁצָּרִיךְ דְבָרִים שֶׁהוּא יוֹדֶה עֲלֵיהֶם (בדרך אמת), וְאָז יְקַבֵּל עָלָיו אֶת הַדִּין וְיוֹדֶה לַמֶּלֶךְ הַקָּדוֹשׁ עָלָיו. מַה כָּתוּב? וֶאֱלִיהוּא חִכָּה אֶת אִיּוֹב בִּדְבָרִים וְגוֹ'. שֶׁהוֹדָה אַחַר כָּךְ לַקָּדוֹשׁ-בָּרוּךְ-הוּא וְקִבֵּל עָלָיו דִּין שָׁמַיִם.</p>\n<p>בֹּא וּרְאֵה, כָּתוּב (איובלד) לָכֵן אַנְשֵׁי לֵבָב שִׁמְעוּ לִי חָלִלָה לָאֵל מֵרֶשַׁע וְשַׁדַּי מֵעָוֶל. לָכֵן אַנְשֵׁי לֵבָב שִׁמְעוּ לִי, שְׁלֵמִים בַּכֹּל לְהַבְחִין דְּבָרִים. חָלִלָה לָאֵל מֵרֶשַׁע, זֶהוּ שֶׁכָּתוּב (תהלים ז) וְאֵל זֹּעֵם בְּכָל יוֹם. וְשַׁדַּי מֵעָוֶל, זֶה סָמוּךְ כְּנֶגֶד זֶה, (והרי פרשוה) אֵל שַׁדַּי. (שם) כִּי פֹעַל אָדָם יְשַׁלֶּם לוֹ, הֲרֵי אָדָם הוֹלֵךְ בָּעוֹלָם הַזֶּה וְעוֹשֶׂה מַעֲשָׂיו וְחוֹטֵא לִפְנֵי רִבּוֹנוֹ, אוֹתוֹ מַעֲשֶׂה תָלוּי עָלָיו לְשַׁלֵּם לוֹ דִּין. זֶהוּ שֶׁכָּתוּב כִּי פֹעַל אָדָם יְשַׁלֶּם לוֹ, אוֹתוֹ מַעֲשֶׂה יְשַׁלֶּם לוֹ.</p>\n<p>וְעִם כָּל זֶה - אִם יָשִׂים אֵלָיו לִבּוֹ. כֵּיוָן שֶׁהָאָדָם שָׂם לִבּוֹ וּרְצוֹנוֹ לָשׁוּב לִפְנֵי רִבּוֹנוֹ, אָז אֵל אֱלֹהֵי הָרוּחֹת רוּחוֹ וְנִשְׁמָתוֹ אֵלָיו יֶאֱסֹף לְהִצָּרֵר בִּצְרוֹר הַחַיִּים, וְלֹא מַשְׁאִיר נַפְשׁוֹ בַּחוּץ לְהִדּוֹן בְּדִין אַחֵר.</p>\n<p>רַבִּי יוֹסֵי אָמַר, דָּבָר זֶה סוֹד (אחר) הוּא בַּדִּינִים הַנִּסְתָּרִים שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. כִּי פֹעַל אָדָם יְשַׁלֶּם לוֹ, לְהִדּוֹן בְּדִינוֹ, וּבְאוֹתָם מַעֲשִׂים שֶׁאָדָם עוֹשֶׂה בָּעוֹלָם הַזֶּה וּמַעֲלֵהוּ לְהִדּוֹן כְּמַעֲשָׂיו, וְיֹאבַד מֵהָעוֹלָם. מַה כָּתוּב אַחֲרָיו? מִי פָקַד עָלָיו אָרְצָה וּמִי שָׂם תֵּבֵל כֻּלָּהּ. מִי פָקַד עָלָיו אָרְצָה - זֶהוּ אָחִיו שֶׁגּוֹאֵל אוֹתוֹ. וּמִי שָׂם תֵּבֵל כֻּלָּהּ - שֶׁבּוֹנֶה בַּיִת וּבוֹנֶה בִּנְיַן עוֹלָם וְתִקּוּן וְיִשּׁוּב. מַה כָּתוּב אַחֲרָיו? אִם יָשִׂים אֵלָיו לִבּוֹ. אָדָם זֶה שֶׁצִּוָּה עָלָיו לִבְנוֹת בִּנְיָן, צָרִיךְ לְכַוֵּן לֵב וְרָצוֹן אֶל אוֹתוֹ הַמֵּת. מִכָּאן, אָדָם שֶׁבָּא עַל אוֹתָהּ אִשָּׁה בִּשְׁבִיל יֹפִי וְתַאֲוָה שֶׁלּוֹ, הֲרֵי בִּנְיַן עוֹלָם לֹא נִבְנֶה, שֶׁהֲרֵי רָצוֹן וְלֵב לֹא הִתְכַּוֵּן אֶל הַמֵּת.</p>\n<p>וּמִשּׁוּם כָּךְ כָּתוּב אִם יָשִׂים אֵלָיו לִבּוֹ, בִּרְצוֹן הַלֵּב שֶׁיְּכַוֵּן אֵלָיו, אָז רוּחוֹ וְנִשְׁמָתוֹ אֵלָיו יֶאֱסֹף, וְנִמְשָׁךְ אֵלָיו לְהִבָּנוֹת בָּעוֹלָם הַזֶּה. מַה כָּתוּב אַחֲרָיו? יִגְוַע כָּל בָּשָׂר יָחַד וְאָדָם עַל עָפָר יָשׁוּב. יִגְוַע כָּל בָּשָׂר יָחַד - אוֹתוֹ גוּף יִבְלֶה בֶּעָפָר וְכָל אוֹתוֹ בָּשָׂר. וְעַכְשָׁו אָדָם עַל עָפָר יָשׁוּב. הֲרֵי הִתְחַדְּשׁוּת הַבִּנְיָן כְּמִקֹּדֶם, וְיָשׁוּב עַל עָפָר שֶׁל בִּנְיָן שֶׁל גּוּף אַחֵר כְּמוֹ שֶׁהָיָה בַּהַתְחָלָה. וְעַל זֶה רוּחַ וּנְשָׁמָה בִּידֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְחָס עַל בְּנֵי אָדָם שֶׁלֹּא יֹאבְדוּ מֵהָעוֹלָם הַזֶּה וּמֵעוֹלָם אַחֵר, בִּגְלַל זֶה אֵל אֱלֹהֵי הָרוּחֹת לְכָל בָּשָׂר.</p>"],[9522012375,"<p>וַיֹּאמֶר מֹשֶׁה אֶל אַהֲרֹן קַח אֶת הַמַּחְתָּה וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (משלי טז) חֲמַת מֶלֶךְ מַלְאֲכֵי מָוֶת וְאִישׁ חָכָם יְכַפְּרֶנָּה. כַּמָּה יֵשׁ לָהֶם לִבְנֵי אָדָם לְפַחֵד מֵחֲטָאֵיהֶם וְלִשְׁמֹר מַעֲשֵׂיהֶם, שֶׁהֲרֵי בְּכַמָּה זְמַנִּים הָעוֹלָם נִדּוֹן, וּבְכָל יוֹם וָיוֹם הַמַּעֲשִׂים עוֹלִים בְּמִשְׁקָל, וּמַשְׁגִּיחִים עֲלֵיהֶם לְמַעְלָה וְנִכְתָּבִים לְפָנָיו. וּכְשֶׁמַּעֲשֵׂי בְּנֵי אָדָם לֹא כְשֵׁרִים לִפְנֵי הַמֶּלֶךְ, עוֹלֶה הָרֹגֶז וּמִתְעוֹרֵר הַדִּין. זֶהוּ שֶׁכָּתוּב חֲמַת מֶלֶךְ מַלְאֲכֵי מָוֶת, וְעַל זֶה בְּכָל יוֹם וָיוֹם צָרִיךְ אָדָם לְהִזָּהֵר מֵחֲטָאָיו.</p>\n<p>וְאִישׁ חָכָם יְכַפְּרֶנָּה. בְּשָׁעָה שֶׁבַּעֲלֵי הַדִּינִים עוֹמְדִים עַל הָעוֹלָם וְהָרֹגֶז תָּלוּי - אִם יֵשׁ בַּדּוֹר צַדִּיק שֶׁרָשׁוּם לְמַעְלָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁגִּיחַ עָלָיו וְשׁוֹכֵךְ הָרֹגֶז. לְמֶלֶךְ שֶׁרָגַז עַל עֲבָדָיו, וְהָיָה תוֹבֵעַ אֶת הַשּׁוֹטֵר הַמּוֹצִיא לַפֹּעַל לַעֲשׂוֹת דִּין. בֵּין כָּךְ נִכְנַס אֲהוּב הַמֶּלֶךְ וְעָמַד לְפָנָיו. כֵּיוָן שֶׁרָאָה אוֹתוֹ הַמֶּלֶךְ, אוֹרוּ פָנָיו. נִשְׁאַר אוֹתוֹ אֲהוּב הַמֶּלֶךְ לְדַבֵּר אִתּוֹ, וְהַמֶּלֶךְ שָׂמַח. אַחַר כָּךְ כְּשֶׁהִגִּיעַ הַשּׁוֹטֵר וְרָאָה פָנָיו שֶׁל הַמֶּלֶךְ שְׂמֵחִים, הִסְתַּלֵּק וְהָלַךְ לוֹ וְלֹא עָשָׂה דִין. וְאָז אוֹתוֹ אֲהוּב הַמֶּלֶךְ בִּקֵּשׁ מֵהַמֶּלֶךְ עַל עֲבָדָיו, וּמְכַפֵּר לָהֶם. וּמִשּׁוּם זֶה, וְאִישׁ חָכָם יְכַפְּרֶנָּה.</p>\n<p>גַּם כָּאן, כְּשֶׁמֹּשֶׁה רָאָה רֹגֶז תָּלוּי, מִיָּד - וַיֹּאמֶר מֹשֶׁה אֶל אַהֲרֹן, מִשּׁוּם שֶׁהוּא שׁוֹשְׁבִין הַמַּלְכָּה, וּקְטֹרֶת עוֹלָה רַק בְּיָדוֹ, שֶׁהוּא מַרְבֶּה שָׁלוֹם בָּעוֹלָם וְקוֹשֵׁר קֶשֶׁר הָאֱמוּנָה. קְטֹרֶת, הֲרֵי פֵּרְשׁוּהָ, שִׂמְחָה שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה, קֶשֶׁר הָאֱמוּנָה, סִלּוּק הָרֹגֶז. זֶהוּ שֶׁכָּתוּב (משלי כז) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב. וְאָז - וְאִישׁ חָכָם יְכַפְּרֶנָּה, יְנַקֶּה וִיטַהֵר אוֹתוֹ רֹגֶז, וְרַחֲמִים מִתְעוֹרְרִים.</p>"],[9522012376,"<p>רַבִּי אֶלְעָזָר אָמַר, (במדבר ד) אַל תַּכְרִיתוּ אֶת שֵׁבֶט מִשְׁפְּחֹת הַקְּהָתִי מִתּוֹךְ הַלְוִיִּם, מִשּׁוּם שֶׁהֵם גֶּזַע וְשֹׁרֶשׁ הַלְוִיִּם. וְזֹּאת עֲשׂוּ לָהֶם וְחָיוּ וְלֹא יָמֻתוּ, שֶׁצָּרִיךְ הַכֹּהֵן לְתַקְּנָם. שֶׁאַף עַל גַּב שֶׁהֵם קְרוֹבִים לַקֹּדֶשׁ, לֹא יִכָּנְסוּ אֶלָּא רַק בְּתִקּוּן הַכֹּהֵן, שֶׁהוּא יוֹדֵע סִימָן שֶׁיַּגִּיעוּ אֵלָיו, וְלֹא יוֹתֵר. וּכְשֶׁמְּכַסִּים לִכְלֵי הַקֹּדֶשׁ, אָז שׁוֹרֶה כִסּוּי אַחֵר, וְאָסוּר לָהֶם לְהִתְקָרֵב וְלִרְאוֹת, שֶׁהֲרֵי דָּבָר בַּחֲשַׁאי אֵין לָהֶם, אֶלָּא לַכֹּהֵן, (ועל זה) שֶׁדִּבְרֵיהֶם וּמַעֲשֵׂיהֶם בְּסוֹד וּבַחֲשַׁאי, וְלַלְוִיִּם לְהָרִים קוֹל.</p>\n<p>בִּגְלַל זֶה כֹּהֲנִים בַּחֲשַׁאי וּבְסוֹד, וְעַל זֶה אָסוּר לָהֶם יַיִן, שֶׁיַּיִן לַהֲרָמַת קוֹל וּלְגִלּוּי סוֹד הוּא. בִּגְלַל זֶה לְוִיִּם נִמְסְרוּ לַהֲרָמַת קוֹל, שֶׁהֲרֵי בְּדִין נֶאֱחָזִים, דִּין בְּגָלוּי הוּא וּלְפַרְסֵם דָּבָר לִפְנֵי הַכֹּל. אֲבָל כֹּהֵן, כָּל דְּבָרָיו בְּסוֹד וַחֲשַׁאי, וְלֹא בְגָלוּי. (סימן הכל שמאל תהא דוחה, וימין מקרבת) מִשּׁוּם שֶׁהוּא יָמִין (מקרב), כְּשֶׁדִּינִים שְׁרוּיִים בָּעוֹלָם מִצַּד שְׂמֹאל, יָמִין תְּהֵא מְקָרֶבֶת, וּבַמֶּה? בִּקְטֹרֶת, שֶׁהִיא בַּחֲשַׁאי, בְּסוֹד דַּקִּיק וּפְנִימִי מֵהַכֹּל.</p>\n<p>בֹּא וּרְאֵה, כְּשֶׁמִּזְבֵּחַ אַחֵר מַתְחִיל לְעוֹרֵר הִתְעוֹרְרוּת, כְּשֶׁלֹּא נִמְצָאִים צַדִּיקִים, מִזְבֵּחַ פְּנִימִי מִתְעוֹרֵר אֵלָיו וְעוֹמֵד מוּלוֹ, וְהַדִּינִים שׁוֹכְכִים. וְעַל זֶה עוֹמֵד מוּל זֶה, וְאָז הַדִּין מִסְתַּלֵּק.</p>\n<p>רַבִּי אֶלְעָזָר אוֹמֵר, (במדבר ד) זֹּאת עֲבֹדַת בְּנֵי קְהָת בְּאֹהֶל מוֹעֵד קֹדֶשׁ הַקְּדָשִׁים. בְּשָׁעָה שֶׁבְּנֵי קְהָת לוֹקְחִים קֹדֶשׁ קָדָשִׁים, אָז בָּא כֹהֵן וְחוֹפֶה הַכֹּל, עַד שֶׁלֹּא יִקְרְבוּ לְלָקְחוֹ, וְלֹא רָאוּ מֵעוֹלָם מַה שֶּׁהֵם לוֹקְחִים, אֶלָּא הַכֹּל מְכֻסֶּה מֵהֶם, כְּמוֹ שֶׁכָּתוּב (שם) וּבָא אַהֲרֹן וּבָנָיו בִּנְסֹעַ הַמַּחֲנֶה וְהוֹרִדוּ אֵת פָּרֹכֶת הַמָּסָךְ. וְרֹב כִּסּוּיֵי כְּלֵי הַמִּקְדָּשׁ הֵם תְּכֵלֶת, מִשּׁוּם שֶׁתְּכֵלֶת הֲרֵי בֵּאֲרוּהָ וְנִתְבָּאֵר. אַחֲרֵי שֶׁהִתְכַּסָּה הַכֹּל, מִתְקָרְבִים בְּנֵי קְהָת שֶׁלּוֹקְחִים, וְלֹא מִתְקָרְבִים אֶלָּא בְּאוֹתָם בַּדִּים שֶׁיּוֹצְאִים הַחוּצָה. זֶהוּ שֶׁכָּתוּב (שם) וְכִלָּה אַהֲרֹן וּבָנָיו לְכַסֹּת אֶת הַקֹּדֶשׁ וְגוֹ', בִּנְסֹעַ הַמַּחֲנֶה וְאַחֲרֵי כֵן יָבֹאוּ בְנֵי קְהָת לָשֵׂאת וְגוֹ'.</p>\n<p>בִּגְלַל כָּךְ קְטֹרֶת, שֶׁהִיא פְּנִימִית, וְכָל מַה שֶּׁבְּסוֹד - לַכֹּהֵן נִמְסַר. וְעַל זֶה, וַיִּקַּח אַהֲרֹן כַּאֲשֶׁר דִּבֶּר מֹשֶׁה וַיָּרָץ אֶל תּוֹךְ הַקָּהָל (וגו') וַיִּתֵּן אֶת הַקְּטֹרֶת, שֶׁהִיא פְּנִימִית, סוֹד הַכֹּהֵן. אָז - וַיְכַפֵּר עַל הָעָם וַיַּעֲמֹד בֵּין הַמֵּתִים וּבֵין הַחַיִּים, בֵּין עֵץ הַחַיִּים וּבֵין עֵץ הַמָּוֶת. אָז הַיָּמִין מַקְרִיב זֶה לָזֶה, וַתֵּעָצַר הַמַּגֵּפָה. אַשְׁרֵי חֵלֶק הַכֹּהֵן, שֶׁלַּכֹּהֵן יֵשׁ כֹּחַ לְמַעְלָה וְיֵשׁ לוֹ כֹּחַ לְמַטָּה, וְהוּא גּוֹרֵם שָׁלוֹם לְמַעְלָה וּלְמַטָּה, וּבְכָל זְמַן הַשְּׂמֹאל עוֹבֵד לַיָּמִין. זֶהוּ שֶׁכָּתוּב (שם יח) וְיִלָּווּ עָלֶיךְ וִישָׁרֲתוּךְ, וְיָמִין בִּשְׂמֹאל נִמְצָאִים בַּמִּקְדָּשׁ.</p>"],[9522012377,"<p>רַבִּי אֶלְעָזָר הָיָה עוֹמֵד לִפְנֵי רַבִּי שִׁמְעוֹן אָבִיו. אָמַר לוֹ, כָּתוּב (קהלת ט) רְאֵה חַיִּים עִם אִשָּׁה אֲשֶׁר אָהַבְתָּ כָּל יְמֵי חַיֵּי הֶבְלֶךְ. אָמַר לוֹ, בֹּא וּרְאֵה, רְאֵה חַיִּים עִם אִשָּׁה אֲשֶׁר אָהַבְתָּ - (והיה אומר רבי שמעון, כתוב (קהלתט) ראה חיים עם אשה אשר אהבת) זֶהוּ סוֹד שֶׁצָּרִיךְ אָדָם לְהַכְלִיל חַיִּים בְּמָקוֹם זֶה. זֶה בְּלִי זֶה לֹא הוֹלֵךְ. וְצָרִיךְ אָדָם לְהַכְלִיל מִדַּת יוֹם בְּמִדַּת לַיְלָה, וּמִדַּת לַיְלָה בַּיּוֹם. וְזֶהוּ רְאֵה חַיִּים עִם אִשָּׁה אֲשֶׁר אָהַבְתָּ. מָה הַטַּעַם? כִּי הוּא חֶלְקְךְ בַּחַיִּים, שֶׁחַיִּים לֹא שׁוֹרִים אֶלָּא עַל זֶה. וּבַעֲמָלְךְ אֲשֶׁר אַתָּה עָמֵל תַּחַת הַשָּׁמֶשׁ, כְּמוֹ שֶׁאָמַר (משלי ג) בְּכָל דְּרָכֶיךְ דָעֵהוּ וְהוּא יְיַשֵּׁר אֹ רְחֹתֶיךְ.</p>\n<p>וּבֹא וּרְאֵה, כָּל דִּבְרֵי שְׁלֹמֹה הַמֶּלֶךְ, כֻּלָּם נִסְתָּרִים לְתוֹךְ הַחָכְמָה. וּפְסוּקִים אֵלּוּ נִרְאִים שֶׁהֻתְּרָה הָרְצוּעָה, כְּמוֹ שֶׁכָּתוּב (אמר לו רבי אלעזר, כתוב) אַחֲרָיו, (קהלת ט) כֹּל אֲשֶׁר תִּמְצָא יָדְךְ לַעֲשׂוֹת בְּכֹחֲךְ עֲשֵׂה כִּי אֵין מַעֲשֶׂה וְחֶשְׁבּוֹן וְגוֹ'. הַפָּסוּק הַזֶּה יֵשׁ לְהִתְבּוֹנֵן בּוֹ, כֹּל אֲשֶׁר תִּמְצָא יָדְךְ לַעֲשׂוֹת בְּכֹחֲךְ עֲשֵׂה, וְכִי שְׁלֹמֹה שֶׁחָכְמָה עֶלְיוֹנָה בוֹ יוֹתֵר עַל כָּל בְּנֵי הָעוֹלָם אָמַר כָּךְ?!</p>\n<p>אֶלָּא (אמר לו) כָּל דִּבְרֵי שְׁלֹמֹה הַמֶּלֶךְ עַל סוֹד חָכְמָה נֶאֶמְרוּ. בֹּא וּרְאֵה, כֹּל אֲשֶׁר תִּמְצָא יָדְךְ לַעֲשׂוֹת בְּכֹחֲךְ עֲשֵׂה, זֶהוּ שֶׁצָּרִיךְ אָדָם לְהַכְלִיל שְׂמֹאל בַּיָּמִין, וְכָל מַה שֶּׁהוּא עוֹשֶׂה צָרִיךְ לוֹ שֶׁלֹּא יִהְיוּ, אֶלָּא כְּלוּלִים בַּיָּמִין. כֹּל אֲשֶׁר תִּמְצָא יָדְךְ - זוֹ הַשְּׂמֹאל. לַעֲשׂוֹת בְּכֹחֲךְ - זֶהוּ הַיָּמִין, כְּמוֹ שֶׁנֶּאֱמַר (שמות טו) יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ. וְכֵיוָן שֶׁהָאָדָם יִזָּהֵר שֶׁכָּל מַעֲשָׂיו יִהְיוּ לְצַד יָמִין וְיַכְלִיל שְׂמֹאל בַּיָּמִין, אָז הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹרֶה בּוֹ בָּעוֹלָם הַזֶּה, וְיִכְנֹס אוֹתוֹ אֵלָיו לְאוֹתוֹ הָעוֹלָם הַבָּא.</p>\n<p>וְלֹא יֹאמַר אָדָם, בְּשָׁעָה שֶׁאָבֹא לְאוֹתוֹ עוֹלָם, אָז אֶתְבַּע מֵהַמֶּלֶךְ רַחֲמִים וְאָשׁוּב לְפָנָיו, אֶלָּא - כִּי אֵין מַעֲשֶׂה וְחֶשְׁבּוֹן וְדַעַת וְחָכְמָה, אַחַר שֶׁיִּסְתַּלֵּק אָדָם מֵהָעוֹלָם הַזֶּה. אֶלָּא אִם רוֹצֶה אָדָם שֶׁהַמֶּלֶךְ הַקָּדוֹשׁ יָאִיר לוֹ לְאוֹתוֹ עוֹלָם וְיִתֵּן לוֹ חֵלֶק בָּעוֹלָם הַבָּא, יִשְׁתַּדֵּל בָּעוֹלָם הַזֶּה לְהַכְלִיל מַעֲשָׂיו בַּיָּמִין, וְכָל מַעֲשָׂיו יִהְיוּ לְשֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁהֲרֵי לְאַחַר כְּשֶׁיִּתְכַּנֵּס מֵהָעוֹלָם הַזֶּה לְהִדּוֹן בְּדִין הַקָּשֶׁה בְּדִין הַגֵּיהִנֹּם, אֵין שָׁם עֵצָה וְחָכְמָה וְשֵׂכֶל לְהִנָּצֵל מִן הַדִּין.</p>\n<p>דָּבָר אַחֵר כִּי אֵין מַעֲשֶׂה וְחֶשְׁבּוֹן וְדַעַת וְחָכְמָה בִּשְׁאוֹל - בַּגֵּיהִנֹּם יֵשׁ בּוֹ מָדוֹרִים עַל מָדוֹרִים., מָדוֹר תַּחְתּוֹן שְׁאוֹל, מָדוֹר תַּחְתּוֹן מִמֶּנּוּ אֲבַדּוֹן, וְזֶה סָמוּךְ לָזֶה. מִי שֶׁיּוֹרֵד לַשְּׁאוֹל, יָדוּנוּ אוֹתוֹ, וּמִשָּׁם יְצַפְצֵף וְעוֹלֶה. זֶהוּ שֶׁכָּתוּב (שמואל אב) מוֹרִיד שְׁאוֹל וַיָּעַל. וּמִי שֶׁיּוֹרֵד לָאֲבַדּוֹן, שׁוּב לֹא עוֹלֶה לְעוֹלָמִים.</p>\n<p>מִי שֶׁיֵּשׁ בּוֹ מַעֲשֶׂה טוֹב אוֹ שֶׁהוּא (אם טוב הוא) בַּעַל חֶשְׁבּוֹן, הֲרֵי בֵּאֲרוּהָ, שֶׁבְּכָל לַיְלָה וְלַיְלָה טֶרֶם יִשְׁכַּב וְטֶרֶם יִישַׁן, צָרִיךְ אָדָם לַעֲשׂוֹת חֶשְׁבּוֹן מִמַּעֲשָׂיו שֶׁעָשָׂה כָּל אוֹתוֹ יוֹם, וְיָשׁוּב מֵהֶם וִיבַקֵּשׁ עֲלֵיהֶם רַחֲמִים. מָה הַטַּעַם בְּאוֹתָהּ הַשָּׁעָה? מִשּׁוּם שֶׁבְּאוֹתָהּ שָׁעָה עֵץ הַמָּוֶת שׁוֹרֶה בָעוֹלָם, וְכָל בְּנֵי הָעוֹלָם טוֹעֲמִים טַעַם הַמָּוֶת, וְצָרִיךְ בְּאוֹתָהּ שָׁעָה לַעֲשׂוֹת חֶשְׁבּוֹן מַעֲשָׂיו וְיוֹדֶה עֲלֵיהֶם, מִשּׁוּם שֶׁאוֹתָהּ שָׁעָה שֶׁל הַמָּוֶת, וְאֵלֶּה נִקְרָאִים בַּעֲלֵי חֶשְׁבּוֹן.</p>\n<p>וְכֵן מִי שֶׁמִּשְׁתַּדֵּל בְּדַעַת וּבְחָכְמָה לָדַעַת אֶת רִבּוֹנוֹ, כְּשֶׁיַּעֲבִירוּ אוֹתוֹ לַחֲזוֹת וּלְהִסְתַּכֵּל בְּאוֹתָם רְשָׁעִים שֶׁנִּטְרְדוּ בַגֵּיהִנֹּם וּבְדַרְגַּת הַשְּׁאוֹל, וְכֻלָּם צוֹוְחִים מֵאוֹתָן דְּרָגוֹת - הוּא לֹא יִשָּׁאֵר שָׁם וְלֹא יִמָּצֵא בֵינֵיהֶם, וְעַל זֶה אֵין מַעֲשֶׂה וְחֶשְׁבּוֹן וְדַעַת בִּשְׁאוֹל, וְלֹא יִמָּצֵא אֶלָּא לְמַעְלָה לְמַעְלָה, בְּמָקוֹם שֶׁכַּמָּה אוֹרוֹת וּמְנוֹרוֹת וְכַמָּה כִסּוּפִים שׁוֹרִים שָׁם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא בָּא (בו) (ומשתוקק לו) לְהִשְׁתַּעֲשֵׁעַ עִם שְׁאָר הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן. אַשְׁרֵי חֵלֶק הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, עֲלֵיהֶם כָּתוּב (תהלים קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ יֵשְׁבוּ רְשָׁעִים אֶת פָּנֶיךְ.</p>"],[9522012378,"<p>וְעָבַד הַלֵּוִי הוּא אֶת עֲבֹדַת אֹהֶל מוֹעֵד וְגוֹ'. רַבִּי אַבָּא פָּתַח, (ישעיה מ) הַיּוֹשֵׁב עַל חוּג הָאָרֶץ וְגוֹ'. בֹּא וּרְאֵה, כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא הָעוֹלָם, עָלָה בְרָצוֹן לְפָנָיו וּבָרָא אוֹתוֹ בַּתּוֹרָה, (כשעלה ברצון לפני הקדוש ברוך הוא לברא העולם, הסתכל בתורה וברא אותו) וּבָהּ נִתְקַן. זֶהוּ שֶׁכָּתוּב (משלי ח) בַּהֲכִינוֹ שָׁמַיִם שָׁם אָנִי. וְכָתוּב (שם) וָאֶהְיֶה אֶצְלוֹ אָמוֹן. וַהֲרֵי הֵקִימוּ, אַל תִּקְרֵי אָמוֹן אֶלָּא אֻמָּן.</p>\n<p>כְּשֶׁבָּא לִבְרֹא אָדָם, וַהֲרֵי נִתְבָּאֵר, אָמְרָה תוֹרָה: וְכִי לְחִנָּם נִקְרֵאתָ אֶרֶךְ אַפַּיִם וְרַב חֶסֶד? בְּאוֹתָהּ שָׁעָה שֶׁיָּצָא אָדָם לָעוֹלָם, הָיָה זִיו פַּרְצוּפוֹ מִלְמַעְלָה וּמִלְּמַטָּה, וְהָיוּ פוֹחֲדִים מִמֶּנּוּ כָּל הַבְּרִיּוֹת, וּפֵרְשׁוּהָ. בּא וּרְאֵה, לֹא הִתְקַיֵּם הָעוֹלָם וְלֹא הֻשְׁלַם עַד אוֹתָהּ שָׁעָה שֶׁיָּצָא אָדָם בִּשְׁלֵמוּת הַכֹּל, וְהִתְקַדֵּשׁ הַיּוֹם וְנִתְקַן כִּסֵּא קָדוֹשׁ לַמֶּלֶךְ, אָז הִשְׁתַּלְּמוּ עֶלְיוֹנִים וְתַחְתּוֹנִים, וְנִמְצְאוּ שְׂמָחוֹת בְּכָל הָעוֹלָמוֹת.</p>\n<p>בְּאוֹתָהּ שָׁעָה שֶׁרָצָה הַיּוֹם לְהִתְקַדֵּשׁ, הָיוּ יוֹצְאִים רוּחוֹת שֶׁל הַשֵּׁדִים לְהִבָּרְאוֹת גּוּף שֶׁלָּהֶם, וְהִתְקַדֵּשׁ הַיּוֹם וְלֹא נִבְרְאוּ, וְנִשְׁאַר הָעוֹלָם כְּמוֹ שֶׁנִּפְגָּם מִמְּלַאכְתּוֹ וּמִסְתּוֹבֵב (ונחסר). כֵּיוָן שֶׁהִתְקַדְּשׁוּ יִשְׂרָאֵל וְנִשְׁלְמוּ בְדַרְגוֹתֵיהֶם וְנִמְצְאוּ לְוִיִּם מִצַּד הַשְּׂמֹאל, כַּאֲשֶׁר (אז) נִשְׁלַם אוֹתוֹ פְגָם שֶׁל הָעוֹלָם שֶׁמִּצַּד שְׂמֹאל.</p>\n<p>וְעַל זֶה צְרִיכִים הַלְוִיִּם לְהִטַּהֵר, וְאָז הַכֹּל נִכְלָל בַּיָּמִין וְהָעוֹלָם לֹא נִפְגָּם, וּמִשּׁוּם כָּךְ כָּתוּב, וְעָבַד הַלֵּוִי הוּא. הוּא הִשְׁלִים לְצַד שְׂמֹאל, הוּא הִשְׁלִים לִפְגַם הָעוֹלָם. וַאֲפִלּוּ אוֹתוֹ צַד צָפוֹן שֶׁנִּשְׁאָר חָסֵר בָּעוֹלָם, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא הָעוֹלָם, הַלֵּוִי הִשְׁלִים בָּאָרוֹן לַכֹּל. מַה זֶּה בָּאָרוֹן? בְּאוֹתוֹ מַשָּׂא שֶׁהָיוּ נוֹשְׂאִים בַּמִּשְׁכָּן, נִשְׁלַם כָּל אוֹתוֹ פְגָם עַל יָדוֹ.</p>\n<p>הוּא - לְמַעְלָה לִשְׂמֹאל. הוּא - נִכְלָל בַּיָּמִין. עוֹד הוּא - זֶה הָעַתִּיק. אִלְמָלֵא הַדִּין לֹא נִמְצָא בָעוֹלָם, לֹא הָיוּ יוֹדְעִים אֲנָשִׁים אֱמוּנָה עֶלְיוֹנָה, וְלֹא יִשְׁתַּדְּלוּ בְנֵי אָדָם בַּתּוֹרָה, וְלֹא יִתְקַיְּמוּ מִצְווֹת התּוֹרָה. עֲבוֹדָה בִשְׁלֵמוּת שֶׁתִּמָּצֵא בָעוֹלָם אֶל הַמֶּלֶךְ הַקָּדוֹשׁ מִי יַעֲשֶׂה אוֹתָהּ? הֱוֵה אוֹמֵר זֶה הַלֵּוִי.</p>\n<p>וְעוֹד וְעָבַד הַלֵּוִי הוּא - כְּמוֹ שֶׁנֶּאֱמַר (דברים ד) כִּי ה' הוּא הָאֱלֹהִים. הוּא הִשְׁלִים שְׁלֵמוּת לִהְיוֹת הַכֹּל אֶחָד. הוּא - פָּשׁוּט לְקַבֵּל אֶת כְּנֶסֶת יִשְׂרָאֵל, כְּמוֹ שֶׁנֶּאֱמַר (שיר השירים ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי, בִּשְׁבִיל לְחַבֵּר זִוּוּג כְּאֶחָד. מִי עוֹרֵר אֶת הָאַהֲבָה? הֱוֵי אוֹמֵר הוּא. עוֹד הוּא - כְּמוֹ שֶׁנֶּאֱמַר (עוד הוא זה עתיק, כמו שנאמר כי ה' הוא האלהים) (תהלים ק) הוּא עָשָׂנוּ וְלֹא אֲנַחְנוּ עַמּוֹ. בִּגְלַל כָּךְ הוּא לְמַטָּה, הוּא לְמַעְלָה, הוּא נִגְלֶה, הוּא נִסְתָּר, הוּא אֱלֹהִים.</p>\n<p>רַבִּי יִצְחָק אָמַר, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָאִיר לַלְּבָנָה כְּאוֹר הַשֶּׁמֶשׁ, וְאוֹר הַשֶּׁמֶשׁ יִהְיֶה עַל אֶחָד שֶׁבַע פְּעָמִים. זֶהוּ שֶׁכָּתוּב (ישעיה ל) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְגוֹ'. וְכָתוּב (שם ס) לֹא יָבוֹא עוֹד שִׁמְשֵׁךְ וִירֵחֵךְ לֹא יֵאָסֵף. וְכָתוּב (שם) לֹא יִהְיֶה לָּךְ עוֹד הַשֶּׁמֶשׁ וְגוֹ'.</p>\n<p>כָּל פֶּטֶר רֶחֶם לְכָל בָּשָׂר וְגוֹ', וְאֵת בְּכוֹר הַבְּהֵמָה הַטְּמֵאָה תִּפְדֶּה. מִצְוָה זוֹ לִפְדּוֹת פֶּטֶר חֲמוֹר, לִפְדּוֹת לָעוֹלָם הַבָּא. וְאִם קֹדֶם שֶׁהָלַךְ לְאוֹתוֹ עוֹלָם לֹא יִפְדֶּה נַפְשׁוֹ וְרוּחוֹ וְנִשְׁמָתוֹ בַתּוֹרָה, עָתִיד לַחֲזֹר לָעוֹלָם הַזֶּה כְּבַתְּחִלָּה, (איובלג) יָשׁוּב לִימֵי עֲלוּמָיו, וּלְקַבֵּל נֶפֶשׁ וְרוּחַ וּנְשָׁמָה.</p>\n<p>כָּתוּב (שם) הֶן כָּל אֵלֶּה יִפְעַל אֵל פַּעֲמַיִם שָׁלוֹשׁ עִם גָּבֶר. וְיִשְׂרָאֵל, בִּגְלַל שֶׁפִּדְיוֹנָם הָיָה בְּלִי תוֹרָה, שֶׁהִיא כֶּסֶף, כִּסּוּף הָעוֹלָם הַבָּא, חָזְרוּ שָׁלֹשׁ פְּעָמִים אֲחֵרוֹת בַּגָּלוּת. וּבַגְּאֻלָּה הָאַחֲרוֹנָה, שֶׁגְּאֻלָּתָם תִּהְיֶה בַתּוֹרָה, לֹא יַחְזְרוּ לְעוֹלָם בַּגָּלוּת. בָּאוּ רַבּוֹתֵינוּ וּבֵרְכוּ אוֹתוֹ וְאָמְרוּ: רוֹעֶה הַנֶּאֱמָן, הַקָּדוֹשׁ בָּרוּךְ הוּא יִפְדֶּה אוֹתְךְ, וְכָל יִשְׂרָאֵל יִפָּדוּ עַל יָדְךְ, וְתִתְחַדֵּשׁ עִמָּהֶם, וְהֵם עִמְּךְ.</p>"],[9522012379,"<p>מִצְוָה אַחַר זוֹ - לָדוּן בְּעֶרְכֵי בַיִת. וּבְסוֹד הַחָכְמָה - בֵּית הָאִישׁ זוֹ אִשְׁתּוֹ. אִם הִיא אִשָּׁה שֶׁל טוֹב וָרָע וְרוֹצֶה לְהָמִיר רָעָה בְטוֹבָה, יִפְדֶּה אוֹתָהּ מֵאוֹתוֹ רָע וְיִתֵּן לוֹ עֵרֶךְ שֶׁלָּהּ. אֲבָל אִשָּׁה שֶׁל עֵץ הַחַיִּים, נֶאֱמַר בָּהּ (שם כח) לֹא יַעַרְכֶנָּה זָהָב וּזְכוּכִית וּתְמוּרָתָהּ כְּלִי פָז, וְאֵין לָהּ עֵרֶךְ, כְּמוֹ שֶׁנֶּאֱמַר (משלי יב) אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ, וְנֶאֱמַר (שם לא) אֵשֶׁת חַיִל מִי יִמְצָא וְגוֹ', וְזוֹ הַשְּׁכִינָה. מִי שֶׁגּוֹמֵל חֶסֶד עִמָּהּ, אֵין עֵרֶךְ לִשְׂכָרוֹ. וּמִי שֶׁמַּרְשִׁיעַ אֵלֶיהָ, אֵין עֵרֶךְ לְעָנְשׁוֹ.</p>\n<p>כַּמָּה שְׁפָחוֹת יֵשׁ לָהּ שֶׁמְּשַׁמְּשִׁים אוֹתָהּ, וּלְכָל אַחַת וְאַחַת מֵהֶן יֵשׁ לָהּ עֵרֶךְ, וְכָל אַחַת וְאַחַת צְרִיכָה פִדְיוֹן. אֲבָל מִי שֶׁיּוֹרֵשׁ נְשָׁמָה אוֹ רוּחַ אוֹ נֶפֶשׁ מֵהַשְּׁכִינָה, לֹא צָרִיךְ פִּדְיוֹן, שֶׁעַל הַשְּׁכִינָה נֶאֱמַר (ישעיה מב) אֲנִי ה' הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן. שֶׁהַפִּדְיוֹן שֶׁלָּהּ תָּלוּי בַּקָּדוֹשׁ-בָּרוּךְ-הוּא. שֶׁמּוֹשְׁכִים אוֹתָהּ (אל) יִשְׂרָאֵל בְּקֶשֶׁר תְּפִלִּין, בְּאוֹת שַׁבָּת, בְּאוֹת יָמִים טוֹבִים, בְּאוֹת הַבְּרִית וְתוֹרָה וּבְכַמָּה מִצְווֹת, שֶׁפִּדְיוֹנָהּ תָּלוּי בַּקָּדוֹשׁ-בָּרוּךְ-הוּא. זֶהוּ שֶׁכָּתוּב (יחזקאל כ) וָאַעַשׂ לְמַעַן שְׁמִי, וּבִגְלָלָהּ (ויקרא כו) וְאַף גַּם זֹּאת. כָּךְ כַּמָה מִצְווֹת הֵן שֶׁעוֹשִׂים בְּנֵי אָדָם עַל מְנָת לְקַבֵּל פְּרָס, וְכַמָּה עֲבֵרוֹת, וּלְכָל מִצְוָה יֵשׁ עֵרֶךְ בְּאוֹתוֹ עוֹלָם. (אבל ענש) וּלְכָל עֹנֶשׁ לְמִי שֶׁעוֹבֵר עֲלֵיהֶן, אֵין לוֹ עֵרֶךְ וְשִׁעוּר.</p>"],[9522012380,"<p>מִצְוָה אַחַר זוֹ - לָדוּן בַּמַּחֲרִים נְכָסָיו לַכֹּהֵן. זֶהוּ שֶׁכָּתוּב כָּל חֵרֶם בְּיִשְׂרָאֵל לְךְ יִהְיֶה. וְסוֹד זֶה (באדם ובבהמה) - כָּל פֶּטֶר רֶחֶם לְכָל בָּשָׂר אֲשֶׁר יַקְרִיבוּ לַה' בָּאָדָם וּבַבְּהֵמָה. רֶחֶם בְּהִפּוּךְ אוֹתִיּוֹת כְּחֶשְׁבּוֹן מָאתַיִם אַרְבָּעִים וּשְׁמוֹנָה אֵיבָרִים שֶׁבָּאָדָם, עֲלֵיהֶם נֶאֱמַר (חבקוק ג) בְּרֹגֶז רַחֵם תִּזְכּוֹר. אַחַר שֶׁכּוֹעֵס אָדָם וּמַחֲרִים אוֹתָהּ בְּהֵמָה אֵלָיו, הֲרֵי שׁוֹרֶה אֵל אַחֵר, נָחָשׁ, שֶׁנֶּאֱמַר בּוֹ (בראשית ג) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה, וְהוּא לִשְׂמֹאל הָאָדָם. בִּגְלַל זֶה פָּקַד הַקָּדוֹשׁ בָּרוּךְ הוּא לָתֵת לַכֹּהֵן, שֶׁהוּא רַחֲמִים, בְּרָכָה, לִכְפּוֹת רֹגֶז, שֶׁעוֹרֵר אוֹתוֹ הָאִישׁ מָרָה, חֶרֶב מַלְאַךְ הַמָּוֶת, וּמְעוֹרֵר הַיָּמִין אֵלָיו בְּרַחֲמִים וְנִכְפֶּה רֹגֶז הַשְּׂמֹאל, וְזֶהוּ בְּרֹגֶז רַחֵם תִּזְכּוֹר.</p>\n<p>מִי שֶׁכּוֹעֵס, שֶׁיֵּשׁ לוֹ בַּכַּעַס סַם הַמָּוֶת, שֶׁעָלָיו בֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, כָּל הַכּוֹעֵס כְּאִלּוּ עוֹבֵד עֲבוֹדָה זָרָה. מִשּׁוּם שֶׁצַּד הָאַחֵר בּוֹעֵר בָּאָדָם, וּבְאוֹתָהּ בְּהֵמָה שֶׁנּוֹתֵן לַכֹּהֵן, נִפְרָד מִמֶּנּוּ הַחֵרֶם, וְסָמָאֵ\"ל אֵל אַחֵר חֵרֶם, וּנְקֵבָתוֹ קְלָלָה, כְּלוּלָה מִכָּל קְלָלוֹת שֶׁבְּמִשְׁנֵה תוֹרָה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא בֵּרַךְ בְּכָל הַתּוֹרָה כֻּלָּהּ, וְכָל הַבְּרָכוֹת מִיָּמִין, שֶׁבָּהּ אָחוּז הַכֹּהֵן. וּמִשּׁוּם זֶה כָּל חֵרֶם צָרִיךְ לָתֵת לַכֹּהֵן, שֶׁהוא אוֹכֵל אוֹתָהּ בָּאֵשׁ וּמַשְׁמִיד אוֹתָהּ מֵהָעוֹלָם, וְשׁוֹכֶכֶת הָאֵשׁ מִשְּׂמֹאל בַּיָּמִין, שֶׁהוּא מַיִם, וּבוֹ (אסתר ג) וַחֲמַת הַמֶּלֶךְ שָׁכָכָה.</p>"],[9522012381,"<p>מִצְוָה אַחַר זוֹ - לְהַפְרִישׁ תְּרוּמָה גְדוֹלָה, וּפֵרְשׁוּהָ שְׁנַיִם מִמֵּאָה. מַה זֶּה תְּרוּמָה? חַכְמֵי הַיְשִׁיבָה, הַתְּרוּמָה הַזּוֹ שֶׁצְּרִיכִים לְהַפְרִישׁ שְׁנַיִם מִמֵּאָה, בְּסִתְרֵי תוֹרָה מִי הֵם? מִי שֶׁרוֹצֶה לִטְעֹם - אִם הוּא זָר, יוּמָת. וְהַיְנוּ אֵל זָר, סָמָאֵ\"ל. שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר (שמות שכה) וְיִקְחוּ לִי תְּרוּמָה, תְּרֵי (שנים) מִמֵּאָה, לְיַחֲדוֹ פַּעֲמַיִם בַּיּוֹם, שֶׁהַיְנוּ שְׁנַיִם מִמֵּאָה, בְּאַרְבָּעִים וָתֵשַׁע אוֹתִיּוֹת שֶׁל \"שְׁמַע\" וּ\"בָרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד\" שֶׁל עַרְבִית, וּבְאַרְבָּעִים וְתֵשַׁע אוֹתִיּוֹת שֶׁל שַׁחֲרִית. חֲסֵרִים שְׁנַיִם מִמֵּאָה, הֵם שְׁכִינָה עֶלְיוֹנָה וְתַחְתּוֹנָה, בִּשְׁנֵיהֶם צָרִיךְ לְיַחֵד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא אַמָּה שֶׁל שְׁנֵיהֶם, מִדָּה שֶׁל שְׁנֵיהֶם, מֵאָה בָּאַמָּה. אַמָּ\"ה בְּאוֹתִיּוֹת מֵאָ\"ה הוּא, וְהוּא בְּהִפּוּךְ אוֹתִיּוֹת הָאֵ\"ם.</p>\n<p>וְעוֹד, (במדבר טו) וְהָיָה בַּאֲכָלְכֶם מִלֶּחֶם הָאָרֶץ תָּרִימוּ תְרוּמָה לַה'. תָּרִימוּ, כְּמוֹ (חבקוק ג) רוֹם יָדֵיהוּ נָשָׂא. וְאוֹתָן עֶשֶׂר אֶצְבָּעוֹת שֶׁעֲלִיָּתָם לְעֶשֶׂר סְפִירוֹת, שֶׁהֵן יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, שֶׁעוֹלִים מ\"ה. וּבְאוֹתִיּוֹת אַלְפָא בֵּיתָא, מָה עוֹלֶה מֵאָ\"ה, י\"ם ה\"צ. וְזֶהוּ שֶׁפֵּרְשׁוּהָ רַבּוֹתֵינוּ בַּעֲלֵי הַמִּשְׁנָה, (דברים י) וְעַתָּה יִשְׂרָאֵל מָ\"ה ה' אֱלֹהֶיךְ שּאֵל מֵעִמָּךְ. וְאָמְרוּ, אַל תִּקְרֵי מָה אֶלָּא מֵאָה, כְּנֶגֶד מֵאָה בְרָכוֹת שֶׁמְּחֻיָּב אָדָם לְבָרֵךְ אֶת רִבּוֹנוֹ בְּכָל יוֹם, וְזֶהוּ שֶׁצָּרִיךְ אָדָם לְהַטְעִים בְּכָל יוֹם לְרִבּוֹנוֹ, וּמִשּׁוּם זֶה וְיִקְחוּ לִי תְּרוּמָה.</p>\n<p>וְכַמָּה תְרוּמוֹת הֵן? יֵשׁ תְּרוּמָה מֵהַתּוֹרָה, תּוֹרָה מ'. וְזוֹהִי תְרוּמָה, תּוֹרָה שֶׁנִּתְּנָה בְּאַרְבָּעִים יוֹם. וְאִם תֹּאמְרוּ שֶׁאָכַלְתִּי מִמֶּנָּה, הֲרֵי כָּתוּב (שמות כד) וַיְהִי מֹשֶׁה בָּהָר אַרְבָּעִים יוֹם וְאַרְבָּעִים לַיְלָה. (שמות לד) לֶחֶם לֹא אָכַל וּמַיִם לֹא שָׁתָה. שְׁמוּרָה הָיְתָה תְרוּמָה זוֹ עַד כָּעֵת לַקָּדוֹשׁ-בָּרוּךְ-הוּא. וְכֵיוָן שֶׁהַמֶּלֶךְ לֹא אָכַל, אֵיךְ אָכְלוּ הָעֲבָדִים? שֶׁהֲרֵי לְאַחַר שֶׁאָמַר (שיר השירים ה) אָרִיתִי מוֹרִי עִם בְּשָׂמִי, אַחַר כָּךְ - אִכְלוּ רֵעִים, יֹאכְלוּ עֲבָדָיו.</p>"],[9522012382,"<p>מִצְוָה אַחַר זוֹ - לְהַפְרִישׁ (לוי תרומת מעשר והיא) (תרומות) מַעֲשֵׂר לַלֵּוִי, וְהִיא שְׁכִינָה מִצַּד יָמִין, שֶׁהוּא חֶסֶד. תְּרוּמָה גְדוֹלָה לַכֹּהֵן, מִצַּד שְׂמֹאל, שֶׁהוּא גְבוּרָה. תְּרוּמַת מַעֲשֵׂר לַלֵּוִי, שֶׁהִיא שְׁכִינָה.</p>\n<p>יוֹ\"ד הֵ\"א וָא\"ו הֵ\"י. (במדבר כח) שְׁלֹשָׁה עֶשְׂרֹנִים לַפָּר, מִצַּד אוֹתוֹ שֶׁנֶּאֱמַר בּוֹ, (יחזקאל א) וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל, וְזוֹ גְבוּרָה. וְעִשָּׂרוֹן לַכֶּבֶשׂ, וְזֶהוּ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א (יו\"ד ה\"י וא\"ו ה\"י), שֶׁעוֹלֶה לְעֶשֶׂר סְפִירוֹת, עִשָּׂרוֹן זֶה. וְעֶשֶׂר לְמ\"ה, וּמ\"ה לְמֵאָה.</p>\n<p>אֲבָל שְׁלֹשָׁה עֶשְׂרֹנִים י' י' י', (זה יו\"ד ה\"י וא\"י ה\"י) וְעוֹלִים (ל'ל' ו' י') לִשְׁלֹשִׁים, וְעֶשֶׂר סְפִירוֹת בָּהֶם עוֹלִים אַרְבָּעִים וְשָׁלֹשׁ בֵּיצִים, וְהַכֹּל יוֹ\"ד, חֹמֶשׁ בֵּיצָה, וְתוֹסֶפֶת מִצַּד ה', וְכָךְ מַעֲשֵׂר, שֶׁהִיא מִצְוָה לְהַפְרִישׁ יִשְׂרָאֵל מַעֲשֵׂר מִצַּד הָאוֹת י', מַעֲשֵׂר מִן הַמַּעֲשֵׂר, אֶחָד מֵחָמֵשׁ מִצַּד אוֹת ה'. כָּל הָעִשּׂוּרִים שֶׁל אוֹת י', וְהִיא הַשְּׁכִינָה, אַחַת מֵעֶשֶׂר סְפִירוֹת. א' מֵחָמֵשׁ הוּא מִצַּד הַתִּפְאֶרֶת, שֶׁהוּא חָמֵשׁ מִכֶּתֶר. וּכְשֶׁתַּחְשֹׁב מִמַּלְכוּת עַד תִּפְאֶרֶת, תִּמְצָא תִּפְאֶרֶת חָמֵשׁ מִמַּטָּה לְמַעְלָה, וּשְׁכִינָה חֲמִישִׁית אֵלָיו.</p>\n<p>וּמִצַד אַחֵר הִיא שְׁנֵי עֶשְׂרֹנִים לָאַיִל, וְכוֹלֶלֶת י' י' הַכַּף בְּשֶׁקֶל הַקֹּדֶשׁ, עֲשָׂרָה עֲשָׂרָה י' ה\"ה. לָאַיִל - זֶה ו', שֶׁהוּא שֶׁקֶל הַקֹּדֶשׁ, וְזֶהוּ (במדבר ז) עֲשָׂרָה עֲשָׂרָה הַכַּף בְּשֶׁקֶל הַקֹּדֶשׁ. וְעוֹד שְׁנֵי עֶשְׂרֹנִים - י' י' מִן (בראשית ב) וַיִּיצֶר. לָאַיִל - ו' מִן וַיִּיצֶר. וְהַכֹּל א'. י' לְמַעְלָה, י' לְמַטָּה, ו' בָּאֶמְצַע. וְעוֹד שְׁלֹשָׁה עֶשְׂרֹנִים - הֵם י' י' י'.</p>"],[9522012383,"<p>מִצְוָה אַחַר זוֹ - לְהַפְרִישׁ תּוֹדָה. וְרַבּוֹתֵינוּ בַּעֲלֵי הַמִּשְׁנָה פֵּרְשׁוּהָ שֶׁתּוֹדָה עֶשְׂרִים עֶשְׂרוֹנִים, וּמִתְחַלְּקִים עֲשָׂרָה עֶשְׂרוֹנִים לְחָמֵץ, וַעֲשָׂרָה לְמַצָּה. וּמֵעֲשָׂרָה שֶׁל מַצָּה עוֹשִׂים שְׁלֹשִׁים מַצּוֹת. וּמֵעֲשָׂרָה שֶׁל חָמֵץ עוֹשִׂים עֶשֶׂר חַלּוֹת. וְזֶהוּ סֹלֶת, (ויקרא ז) חַלּוֹת מַצּוֹת בְּלוּלֹת בַּשָּׁמֶן. מֵעֲשָׂרָה עֶשְׂרוֹנִים, שֶׁהֵם יוֹ\"ד הֵ\"י וָא\"ו הֵ\"י, הָיוּ עוֹשִׂים שְׁלֹשִׁים מַצּוֹת, שֶׁהֵם י' י' י'. שֵׁם זֶה לִפְעָמִים הוּא לְיָמִין וְלִפְעָמִים הוּא לִשְׂמֹאל וְלִפְעָמִים בָּאֶמְצַע. רַחֲמִים מִכָּל צַד, לִימִינוֹ וְלִשְׂמֹאלוֹ.</p>\n<p>וְלִפְעָמִים עֲשָׂרָה לְיָמִין, וְאֵין פּוֹחֲתִין בּוֹ מֵעֶשֶׂר מַלְכֻיּוֹת. וְלִפְעָמִים יוֹ\"ד לִשְׂמֹאל, וְאֵין פּוֹחֲתִין בּוֹ מֵעֲשָׂרָה שׁוֹפָרוֹת. וְלִפְעָמִים יוֹ\"ד בָּאֶמְצַע, וְאֵין פּוֹחֲתִין בּוֹ מֵעֲשָׂרָה זִכְרוֹנוֹת.</p>"],[9522012384,"<p>עַל פִּי ה' יַחֲנוּ וְעַל פִּי ה' יִסָּעוּ אֶת מִשְׁמֶרֶת ה' שָׁמָרוּ (במדבר ט). שֶׁלְּכָל י' יֵשׁ אַרְבָּעָה פָנִים, שָׁלֹשׁ חַיּוֹת הֵן כְּנֶגֶד שָׁלֹשׁ יוֹדִין, וְאַרְבָּעָה פָנִים לְכָל חַיָּה כְּנֶגֶד אַרְבָּעָה פָנִים (אותיות) שֶׁל יְהֹוָ\"ה, עַל פִּי ה' יַחֲנוּ וְיִסָּעוּ.</p>\n<p>שָׁמָרוּ - זוֹ הַשְּׁכִינָה שֶׁשּׁוֹמֶרֶת לְאוֹתָם שֶׁשּׁוֹמְרִים שַׁבָּתוֹת וְיָמִים טוֹבִים, שֶׁבִּגְלַל זֶה לֹא זָזָה שְׁכִינָה מִיִּשְׂרָאֵל בְּכָל שַׁבָּתוֹת וְיָמִים טוֹבִים, וַאֲפִלּוּ בְּשַׁבְּתוֹת (בימי) הַחֹל, אֶלָּא שֶׁהִיא סוֹגֶרֶת וּמְסֻגֶּרֶת בָּהֶם.</p>\n<p>וּבְכָל תְּפִלָּה הִיא עוֹלָה לְשֵׁם יְהֹוָה, עַד שֶׁמַּגִּיעָה לַמֶּרְכָּבָה (של החיות) שֶׁל הָאָבוֹת הָעֶלְיוֹנִים, שֶׁהֵם: גְּדֻלָּה, גְּבוּרָה, תִּפְאֶרֶת. שֶׁיֵּשׁ לָהֶם שְׁנֵים עָשָׂר פָּנִים כְּנֶגֶד שְׁנֵים עָשָׂר שְׁבָטִים. וּכְפִי שֶׁהִיא מְלַמֶּדֶת זְכוּת עַל אֵלּוּ בַּעֲלֵי הַתְּפִלָּה וּבַעֲלֵי זְכֻיּוֹת בְּכָל מִצְוָה וּמִצְוָה מֵהַתּוֹרָה - כָּךְ יַחֲנוּ עַל זְכֻיּוֹת שֶׁלָּהֶם וְכֵן יִסָּעוּ לְגַבָּם, וְכָךְ יוֹרֶדֶת שְׁמִירָה אֲלֵיהֶם.</p>\n<p>אֵלּוּ שֶׁעוֹשִׂים זְכֻיּוֹת עַל מְנָת לְקַבֵּל פְּרָס, יוֹרֵד הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַרְכְּבוֹתָיו שֶׁעָשָׂה, וּבְאַרְבָּעָה שׁוֹמְרִים שֶׁלּוֹ, וּמִי שֶׁעוֹשֶׂה זְכֻיּוֹת שֶׁלֹּא עַל מְנָת לְקַבֵּל פְּרָס, יוֹרֵד עֲלֵיהֶם בְּמֶרְכַּבְתּוֹ, וְעַל הָרְשָׁעִים יוֹרֵד עֲלֵיהֶם בְּמַעֲשֵׂיהֶם בְּאוֹתָם שֵׁדִים וּמַזִּיקִים וּמַלְאֲכֵי חַבָּלָה בְּמֶרְכַּבְתָּם לְהִפָּרַע מֵהֶם. (זכיותשלא על מנת לקבל פרס, הקדוש ברוך הוא יורד עליהם במרכבתו ובארבע החיות שלו. ומי שעושה זכיות על מנת לקבל פרס, יורד עליהם במרכבה של העבד מטטרו\"ן ובארבעה השומרים שלו. ולרשעים יורד עליהם במעשיהם, באותם שדים ומזיקים ומלאכי חבלה עון ומשחית אף וחמה במרכבה שלהם להפרע מהם) פָּתְחוּ בַּעֲלֵי הַמִּשְׁנָה וְאָמְרוּ, וַדַּאי כָּךְ זֶה. אַשְׁרֵי חֶלְקְךְ רוֹעֶה הַנֶּאֱמָן. (עד כאן רעיא מהימנא). בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלֹךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522012385,"<p>וַיְדַבֵּר ה' אֶל מֹשֶׁה וְאֶל אַהֲרֹן לֵאמֹר זֹּאת חֻקַּת הַתּוֹרָה אֲשֶׁר צִוָּה ה' לֵאמֹר וְגוֹ'. רַבִּי יוֹסֵי פָּתַח, (דברים ד) וְזֹּאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה לִפְנֵי בְּנֵי יִשְׂרָאֵל. בֹּא וּרְאֵה, דִּבְרֵי הַתּוֹרָה הֵם קְדוֹשִׁים, הֵם עֶלְיוֹנִים, הֵם מְתוּקִים, כְּמוֹ שֶׁכָּתוּב (תהלים יט) הַנֶּחֱמָדִים מִזָּהָב וּמִפָּז רָב וּמְתוּקִים מִדְּבַשׁ וְגוֹ'. מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה כְּאִלּוּ עוֹמֵד כָּל יוֹם עַל הַר סִינַי וּמְקַבֵּל הַתּוֹרָה. זֶהוּ שֶׁכָּתוּב (דברים כז) הַיּוֹם הַזֶּה נִהְיֵיתָ לְעָם. וְכָךְ פֵּרְשׁוּהוּ הַחֲבֵרִים.</p>\n<p>כָּתוּב כָּאן זֹּאת חֻקַּת הַתּוֹרָה, וְכָתוּב וְזֹּאת הַתּוֹרָה. מַה בֵּין זֶה לָזֶה? אֶלָּא סוֹד עֶלְיוֹן הוּא, וְכָךְ לָמַדְנוּ: וְזֹּאת הַתּוֹרָה, לְהַרְאוֹת הַכֹּל בְּיִחוּד אֶחָד וּלְהַכְלִיל כְּנֶסֶת יִשְׂרָאֵל בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, לְהִמָּצֵא הַכֹּל אֶחָד. בִּגְלַל זֶה וְזֹּאת הַתּוֹרָה. לָמָּה תּוֹסֶפֶת וָא\"ו? אֶלָּא זֶה נֶאֱמַר לְהַרְאוֹת שֶׁהַכֹּל אֶחָד, לְלֹא פֵרוּד. וְזֹּאת - כְּלָל וּפְרָט כְּאֶחָד, זָכָר וּנְקֵבָה. וּמִשּׁוּם זֶה וְזֹּאת הַתּוֹרָה וַדַּאי. אֲבָל זֹּאת בְּלֹא תוֹסֶפֶת וָא\"ו, חֻקַּת הַתּוֹרָה וַדַּאי, וְלֹא הַתּוֹרָה, דִּין הַתּוֹרָה, גְּזֵרַת הַתּוֹרָה.</p>\n<p>בֹּא וּרְאֵה, (במדבר ח) זֹּאת אֲשֶׁר לַלְוִיִּם, וְלֹא וְזֹּאת. שֶׁהֲרֵי מִצַּד הַדִּין (הקשה) הֵם בָּאִים, וְלֹא מִצַּד הָרַחֲמִים. אָמַר רַבִּי יְהוּדָה, וַהֲרֵי כָּתוּב (במדבר ד) וְזֹּאת עֲשׂוּ לָהֶם וְחָיוּ. וְזֶה בַּלְוִיִּם נֶאֱמַר, וְאַתָּה אָמַרְתָּ זֹּאת, וְלֹא וְזֹּאת. אָמַר לוֹ, וַדַּאי כָּךְ זֶה, וְהַפָּסוּק מוֹכִיחַ. מִי שֶׁאוֹחֵז סַם הַמָּוֶת, אִם לֹא יְעָרֵב בּוֹ סַם הַחַיִּים, הֲרֵי וַדַּאי יָמוּת. וְעַל זֶה, וְזֹּאת עֲשׂוּ לָהֶם וְחָיוּ וְלֹא יָמֻתוּ, מִשּׁוּם שֶׁסַּם הַחַיִּים מְעֹרָב אִתּוֹ. וְזֹּאת עֲשׂוּ וְחָיוּ וְלֹא יָמֻתוּ, וַדַּאי וְזֹּאת צָרִיךְ לָהֶם, וְלֹא זֹּאת. מִשּׁוּם כָּךְ וְזֹּאת הַתּוֹרָה מַמָּשׁ, בְּיִחוּד אֶחָד, בְּיִחוּד שָׁלֵם, כְּלַל שֶׁל זָכָר וּנְקֵבָה. ו\"ה. זֹּאת - ה' בִּלְבַדָּהּ, וְעַל זֶה זֹּאת חֻקַּת הַתּוֹרָה.</p>"],[9522012386,"<p>רַבִּי שִׁמְעוֹן וְרַבִּי אַבָּא וְרַבִּי אֶלְעָזָר וְרַבִּי יִצְחָק הָיוּ מְצוּיִים בְּבֵית רַבִּי פִּנְחָס בֶּן יָאִיר. אָמַר רַבִּי פִּנְחָס לְרַבִּי שִׁמְעוֹן, בְּבַקָּשָׁה מִמְּךְ, אַתָּה שֶׁעוֹמְדִים עָלֶיךְ לְמַעְלָה וּדְבָרֶיךְ בְּגָלוּי, מַה שֶּׁלֹּא נִתְּנָה רְשׁוּת לְאָדָם אַחֵר, בְּפָרָשָׁה זוֹ אֱמֹר דָּבָר חָדָשׁ. אָמַר לוֹ, וּמַהוּ? אָמַר לוֹ, זֹּאת חֻקַּת הַתּוֹרָה. אָמַר לוֹ, הִנֵּה שְׁאָר הַחֲבֵרִים יֹאמְרוּ. אָמַר לְרַבִּי אֶלְעָזָר בְּנוֹ, אֶלְעָזָר עֲמֹד בְּעָמְדְּךְ, וֶאֱמֹר דָּבָר אֶחָד בְּפָרָשָׁה זוֹ, וְהַחֲבֵרִים יֹאמְרוּ אַחֲ רֶיךְ.</p>\n<p>קָם רַבִּי אֶלְעָזָר וְאָמַר, (רות ד) וְזֹּאת לְפָנִים בְּיִשְׂרָאֵל עַל הַגְּאוּלָּה וְעַל הַתְּמוּרָה לְקַיֵּם וְגוֹ'. בְּפָסוּק זֶה יֵשׁ לְהִסְתַּכֵּל, וְאִם רִאשׁוֹנִים אֵלּוּ עָשׂוּ הַסְכָּמָה זוֹ בְּדִין תּוֹרָה וּבָאוּ אַחֲרוֹנִים וּבִטְּלוּהָ, לָמָּה בִּטְּלוּהָ? וַהֲרֵי מִי שֶׁמְּבַטֵּל דְּבַר תּוֹרָה כְּאִלּוּ הֶחֱרִיב עוֹלָם שָׁלֵם? וְאִם זֶה אֵינוֹ בְּדִין תּוֹרָה, אֶלָּא הַסְכָּמָה בְּעָלְמָא, לָמָּה הַנַּעַל כָּאן?</p>\n<p>אֶלָּא וַדַּאי בְּדִין הַתּוֹרָה הָיָה, וּבְסוֹד עֶלְיוֹן נַעֲשָׂה הַדָּבָר. וּמִשּׁוּם שֶׁהָיוּ הָרִאשׁוֹנִים חֲסִידִים צַדִּיקִים, הַדָּבָר הַזֶּה הִתְגַּלָּה בֵינֵיהֶם, וּמִשֶּׁהִתְרַבּוּ רְשָׁעִים בָּעוֹלָם, נַעֲשָׂה (העבירו) דָבָר זֶה בְּצוּרָה אַחֶרֶת כְּדֵי לְכַסּוֹת דְּבָרִים שֶׁהֵם בְּסוֹד עֶלְיוֹן. (והרי פרשוה)</p>\n<p>בֹּא וּרְאֵה, (שמות ג) וַיֹּאמֶר אַל תִּקְרַב הֲלֹם שַׁל נְעָלֶיךְ מֵעַל רַגְלֶיךְ וְגוֹ'. וְכִי לָמָּה הַנַּעַל כָּאן? אֶלָּא נִתְבָּאֵר שֶׁצִּוָּה לוֹ עַל הָאִשָּׁה לְהִפָּרֵד מִמֶּנָּה, וּלְהִזְדַּוֵּג (במקום) בְּאִשָּׁה אַחֶרֶת שֶׁל אוֹר קָדוֹשׁ עֶלְיוֹן, וְהִיא הַשְּׁכִינָה.</p>\n<p>וְאוֹתָהּ נַעַל בֵּאֲרוּהָ בְּמָקוֹם אַחֵר, (והיאהשכינה) הֶעֱבִירוּהָ מֵעוֹלָם הַזֶּה, וּבֵאֲרוּהָ בְּעוֹלָם אַחֵר. וְעַל כָּךְ, כָּל מַה שֶּׁנּוֹתֵן הַמֵּת לָאָדָם בַּחֲלוֹם - זֶה טוֹב. לָקַח כֵּלָיו מֵהַבַּיִת - זֶה רָע, כְּמוֹ סַנְדָּלוֹ. מַדּוּעַ? כִּי הֶעֱבִיר רַגְלָיו, שֶׁהֵם עֲמִידַת הָאָדָם, מֵהָעוֹלָם הַזֶּה, וְכָנַס אוֹתָם לְעוֹלָם אַחֵר, מָקוֹם שֶׁהַמָּוֶת שׁוֹרֶה בּוֹ, שֶׁכָּתוּב (שיר ז) מַה יָּפוּ פְעָמַיִךְ בַּנְּעָלִים בַּת נָדִיב. (מהי בת נדיב, ' זו בת אברהם, שכתוב (תהלים מז) נדיבי עמים נאספו עם אלהי אברהם, ולא אלהי יצחק) וְסוֹד הַדָּבָר הוּא בֵּין הַחֲבֵרִים.</p>\n<p>וְזְהִ כְּשֶׁהַמֵּת לוֹקֵחַ אוֹתָם. אֲבָל בִּזְמַן שֶׁהַחַי שׁוֹלֵף נַעֲלוֹ וְנוֹתֵן לְאִישׁ אַחֵר כְּדֵי לְקַיֵּם בְּרִית, עוֹשֶׂה בִּגְזֵרָה עֶלְיוֹנָה. נַעַל שֶׁל חֲלִיצָה, כְּמוֹ שֶׁלְּמַעְלָה נַעַל אַחֶרֶת, וְהַכֹּל מָקוֹם אֶחָד (הכל מתיחד) (סוד אחד).</p>\n<p>בֹּא וּרְאֵה, אוֹתוֹ מֵת שֶׁהִסְתַּלֵּק מֵהָעוֹלָם בְּלֹא בָנִים, בַּת נָדִיב זוֹ לֹא כוֹנֶסֶת אוֹתוֹ אֵלֶיהָ, וְהוֹלֵךְ לִהְיוֹת מֻטְרָד בָּעוֹלָם, שֶׁלֹּא מוֹצֵא מָקוֹם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עָלָיו, וּמְצַוֶּה לְאָחִיו לִגְאֹל אוֹתוֹ, לָשׁוּב וְלִהְיוֹת מְתֻקָּן בְּעָפָר אַחֵר, כְּמוֹ שֶׁכָּתוּב (איובלד) וְאָדָם עַל עָפָר יָשׁוּב, וּפֵרְשׁוּהָ.</p>\n<p>וְאִם אוֹתוֹ גּוֹאֵל לֹא רוֹצֶה לְהַעֲמִיד אֶת אָחִיו בָּעוֹלָם הַזֶּה, צָרִיךְ לִקְשֹׁר נַעַל אַחַת בְּרַגְלוֹ, וְאוֹתָהּ אִשָּׁה שֶׁתִּשְׁרֶה אִתּוֹ, מְקַבֶּלֶת אֵלֶיהָ אוֹתָהּ נַעַל. וְלָמָּה נַעַל? אֶלָּא מִשּׁוּם שֶׁאוֹתָהּ נַעַל הִיא בִּגְלַל הַמֵּת (משום שאותה נעל היא קיום המת בעולם הזה), וְנִתְּנָה בְּרַגְלֵי אָחִיו הַחַי, וְהָאִשָּׁה מְקַבֶּלֶת אֵלֶיהָ אוֹתָהּ נַעַל, לְהַרְאוֹת שֶׁאוֹתוֹ מֵת חָזַר לְבֵין הַחַיִּים בַּמַּעֲשֶׂה הַזֶּה.</p>\n<p>וְהוּא בְּהֵפֶךְ מֵאוֹתָהּ נַעַל שֶׁלּוֹקֵחַ הַמֵּת מֵהַחַי, וְכָעֵת נַעַל זוֹ לוֹקֵחַ הַחַי מִן הַמֵּת, וּבְאוֹתָהּ נַעַל אוֹתוֹ הַמֵּת הוֹלֵךְ בֵּין הַחַיִּים, (וצריך נעל של המת הזה הולך בו בחייו) וְהָאִשָּׁה לוֹקַחַת אוֹתָהּ אֵלֶיהָ, לְהַרְאוֹת שֶׁאוֹתָהּ אִשָּׁה (משלי יב) עֲטֶרֶת בַּעְלָהּ, לָקְחָה אוֹתָהּ וּמְקַבֶּלֶת אוֹתָהּ אֵלֶיהָ.</p>\n<p>וְצָרִיךָ לְהַכּוֹת בְּאוֹתָהּ נַעַל בָּאָרֶץ, לְהַרְאוֹת שֶׁשָּׁכַךְ גּוּף אוֹתוֹ הַמֵּת. וְהַקָּדוֹשׁ בָּרוּךְ הוּא בִּזְמַן זֶה אוֹ לְאַחַר זְמַן יָחוּס עָלָיו וִיקַבֵּל אוֹתוֹ לְעוֹלָם אַחֵר. עוֹד הַכָּאָה שֶׁל אוֹתָהּ הַנַּעַל בַּיָּד (מהיד) שֶׁל הָאִשָּׁה לָאָרֶץ, לְהַרְאוֹת שֶׁיִּבָּנֶה אוֹתוֹ הַמֵּת בְּעָפָר אַחֵר בָּעוֹלָם הַזֶּה, וְכָעֵת יָשׁוּב לַעֲפָרוֹ שֶׁהָיָה מִשָּׁם בַּהַתְחָלָה, (ואז ישוב לעפרו) וְאָז אוֹתָהּ אִשָּׁה תֻּתַּר לַעֲשׂוֹת זֶרַע אַחֵר, וְכָךְ פֵּרְשׁוּהָ.</p>\n<p>בֹּא וּרְאֵה, עַל כָּךְ מִי שֶׁרוֹצֶה לְהַעֲמִיד בְּרִית, נוֹטֵל נַעֲלוֹ וְנוֹתֵן לַחֲבֵרוֹ לְהַעֲמִיד עָלָיו בְּרִית. (שבת נָדיב) זהו שכתוב וזאת לפנים בישראל על הגאולה. מה זה וְזֹּאת? בְּרִית שְׁלֵמָה בַּכֹּל. לְפָנִים בְּיִשְׂרָאֵל, כְּשֶׁהָיוּ צְנוּעִים קְדוֹשִׁים. לְקַיֵּם כָּל דָּבָר, כָּל דָּבָר מַמָּשׁ, שֶׁהֲרֵי זֶהוּ הַעֲמָדָה. וְאָז - וְזֹּאת הַתְּעוּדָה בְּיִשְׂרָאֵל, וַדַּאי. שֶׁלֹּא תֹאמַר שֶׁהַסְכָּמָה בְּעָלְמָא הִיא, וּמִדַּעְתָּם עָשׂוּ אוֹתָהּ, אֶלָּא הַעֲמָדָה עֶלְיוֹנָה הָיְתָה, לִהְיוֹת מַעֲשֵׂיהֶם בְּסוֹד שֶׁל מַעְלָה.</p>\n<p>כֵּיוָן שֶׁהִתְרַבּוּ רְשָׁעִים בָּעוֹלָם, כִּסּוּ הַדָּבָר בְּגָוֶן אַחֵר, בִּכְנַף הַמַּלְבּוּשׁ, וְהַמַּלְבּוּשׁ הַזֶּה הוּא תִּקּוּן עֶלְיוֹן. וְסוֹד הַדָּבָר - כָּתוּב (דברים כג) וְלֹא יְגַלֶּה כְּנַף אָבִיו.</p>"],[9522012387,"<p>זֹאת חֻקַּת הַתּוֹרָה. זֹּאת - זוֹ אוֹת הַבְּרִית, שֶׁלֹּא יִפָּרְדוּ זֶה מִזֶּה (וכאשר נפרע זה הכל) שֶׁנִּקְרָא זֶה, וּמֵהַנְּקֵבָה עוֹלָה לַזָּכָר. וְעַל זֶה שָׁמוֹ\"ר וְזָכוֹ\"ר מִתְחַבְּרִים כְּאֶחָד. חֻקַּת הַתּוֹרָה?! חֹק הַתּוֹרָה צָרִיךְ לִהְיוֹת! מַה זֶּה חֻקַּת?</p>\n<p>אֶלָּא חֻקַּת בְּוַדַּאי, וּבֵאַרְנוּ, ה' הָיְתָה ד' (חק), וַהֲרֵי נִתְבָּאֵר. אֲבָל ת' הוּא ד' וְנ' מְחֻבָּרִים כְּאֶחָד. וְנוּ\"ן הֲרֵי נִתְבָּאֵר, נוּ\"ן לָמָּה נִקְרֵאת כָּךְ בְּנוּ\"ן? אֶלָּא כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כה) וְלֹא תוֹנוּ אִישׁ אֶת עֲמִיתוֹ. שֶׁכָּעֵת הִיא בְּפָנִים מְאִירוֹת וְעוֹשָׂה אוֹנָאָה לִבְנֵי אָדָם, וְאַחַר כָּךְ מַכָּה כְּמוֹ נָחָשׁ, וּמַשְׁמִידָה וְהוֹרֶגֶת, (משליל) וְאָמְרָה לֹא פָעַלְתִּי אָוֶן. וְעַל זֶה כָּךְ נִקְרֵאת בְּנוּ\"ן שֶׁנֶּאֱמַר עָלֶיהָ. ת' הַכֹּל כְּאֶחָד - דָּלֶ\"ת נוּ\"ן. ד' נוּ\"ן דָּלֶ\"ת רֵי\"שׁ (ה\"א ה\"א) (נו\"ן רי\"ש), רֵי\"שׁ וְדָלֶ\"ת דָּבָר אֶחָד הוּא. וּבְאוֹתִיּוֹת חֲקוּקוֹת הֵם חֹק וְת', וְהַכֹּל דָּבָר אֶחָד.</p>"],[9522012388,"<p>דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְיִקְחוּ אֵלֶיךְ פָרָה. פָּרָה זוֹ בָּאָה לְטַהֵר. לְטַהֵר לַטְּמֵאִים. פָּרָה שֶׁמְּקַבֶּלֶת מֵהַשְּׂמֹאל. וּמִי הוּא לַשְּׂמֹאל? שׁוֹר, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל א) וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל. אֲדֻמָּה - סְמוּקָה כַּשּׁוֹשַׁנָּה, שֶׁכָּתוּב (שיר ב) כְּשׁוֹשַׁנָּה בֵּין הַחוֹחִים. אֲדֻמָּה - גְּזֵרַת הַדִּין.</p>\n<p>תְּמִימָה, מַה זֶּה תְּמִימָה? כְּמוֹ שֶׁשָּׁנִינוּ, שׁוֹר תָּם וְשׁוֹר מוּעָד. שׁוֹר תָּם דִּין רָפֶה. שׁוֹר מוּעָד דִּין קָשֶׁה. גַּם כָּךְ תְּמִימָה דִּין רָפֶה, גְּבוּרָה תַחְתּוֹנָה, זוֹהִי תְמִימָה. גְּבוּרָה עֶלְיוֹנָה, זֶהוּ דִּין קָשֶׁה, וְהִיא יָד הַחֲזָקָה תַּקִּיפָה.</p>\n<p>אֲשֶׁר אֵין בָּהּ מוּם, כְּמוֹ שֶׁנֶּאֱמַר (שיר השירים ד) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ. אֲשֶׁר לֹא עָלָה עָלֶיהָ עֹל, עַל כָּתוּב, כְּמוֹ שֶׁנֶּאֱמַר (שמואל ב כג) וּנְאֻם הַגֶּבֶר הוּקַם עָל. מָה הַטַּעַם? מִשּׁוּם שֶׁהִיא (שם כ) שְׁלֻמֵי אֱמוּנֵי יִשְׂרָאֵל, וְעָלֶיהָ לֹא הִיא, אֶלָּא עִמָּהּ. אֲשֶׁר לֹא עָלָה עָלֶיהָ עֹל, הַיְנוּ שֶׁכָּתוּב (עמוס ה) בְּתוּלַת יִשְׂרָאֵל, (בראשית כד) בְּתוּלָה וְאִישׁ לֹא יְדָעָהּ.</p>\n<p>וּנְתַתֶּם אֹתָהּ אֶל אֶלְעָזָר, מִצְוָתָהּ בַּסְּגָן, וּפֵרְשׁוּהָ. מָה הַטַּעַם לוֹ וְלֹא לְאַהֲרֹן? אֶלָּא אַהֲרֹן שׁוֹשְׁבִין הַמַּלְכָּה. וְעוֹד, שֶׁאַהֲרֹן לֹא בָא מִצַּד שֶׁל טָהוֹר, אֶלָּא מִצַּד שֶׁל קָדוֹשׁ, וּמִשּׁוּם שֶׁזֶּה בָּא לְטָהֳרָה, לֹא נִתַּן לוֹ.</p>\n<p>כָּל דָּבָר בְּפָרָה זוֹ הִיא בְּשֶׁבַע, שִׁבְעָה כִבּוּסִים וְכוּ', וַהֲרֵי נִתְבָּאֵר. מָה הַטַּעַם? מִשּׁוּם שֶׁהִיא שֶׁבַע שְׁנֵי שְׁמִטָּה, וּבַת שֶׁבַע נִקְרֵאת, וְעַל כָּךְ כָּל מַעֲשֶׂיהָ בְּשֶׁבַע. בֹּא וּרְאֵה, כָּל מַה שֶּׁנַּעֲשָׂה מִפָּרָה זוֹ - בִּשְׁבִיל לְטַהֵר, וְלֹא לְקַדֵּשׁ. וְאַף עַל גַּב שֶׁנִּתְּנָה לַסְּגָן, הוּא לֹא שׁוֹחֵט וְלֹא שׂוֹרֵף, בִּשְׁבִיל שֶׁלֹּא יִמָּצֵא דִין בְּצִדּוֹ, וְכָל שֶׁכֵּן אַהֲרֹן, שֶׁהוּא בְּדַרְגָּה יוֹתֵר מֻשְׁלֶמֶת, וְלֹא צָרִיךְ לְהִמָּצֵא שָׁם וּלְהִזְדַּמֵּן לְשָׁם.</p>\n<p>פָּרָה זוֹ, כֵּיוָן שֶׁנֶּעֶשְׂתָה אֵפֶר, צָרִיךְ לִזְרֹק בָּהּ עֵץ אֶרֶז וְאֵזוֹב וּשְׁנִי תוֹלַעַת, וַהֲרֵי אֵלֶּה נֶאֶמְרוּ. וְאָסַף אִישׁ טָהוֹר, וְלֹא קָדוֹשׁ. וְהִנִּיחַ מִחוּץ לַמַּחֲנֶה בְּמָקוֹם טָהוֹר, שֶׁהֲרֵי טָהוֹר לֹא נִקְרָא אֶלָּא מִצַּד שֶׁמְּטַמֵּא בַּהַתְחָלָה.</p>\n<p>סוֹד הַכֹּל, זֶה שֶׁכָּתוּב לְמֵי נִדָּה חַטָּאת הִיא. מִשּׁוּם שֶׁכָּל דִּינִים הַתַּחְתּוֹנִים וְכָל אֵלּוּ שֶׁבָּאִים מִצַּד הַטֻּמְאָה, כְּשֶׁיּוֹנְקִים מִצַּד אַחֵר וְיוֹשְׁבִים בְּדִין, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה לד) מָלְאָה דָם הֻדַּשְׁנָה מֵחֵלֶב, אָז כֻּלָּם מִתְעוֹרְרִים וּמִסְתַּלְּקִים וְשׁוֹרִים בָּעוֹלָם. כֵּיוָן שֶׁעוֹשִׂים מַעֲשֶׂה זֶה שֶׁלְּמַטָּה, וְכָל הַדִּין הַזֶּה בְּמָקוֹם זֶה שֶׁל פָּרָה זוֹ, וְזוֹרְקִים עָלֶיהָ עֵץ אֶרֶז וְגוֹ', אָז נֶחֱלָשׁ כֹּחָם, וּבְכָל מָקוֹם שֶׁשּׁוֹרִים נִשְׁבָּרִים וְנֶחֱלָשִׁים וּבוֹרְחִים מִשָּׁם, שֶׁהֲרֵי כֹּחָם נִרְאֶה כְּמוֹ זֶה לְגַבֵּיהֶם, וְאָז לֹא שׁוֹרִים בָּאָדָם, וְהוּא נִטְהָר.</p>\n<p>וְעַל זֶה נִקְרָאִים מֵי נִדָּה, מַיִם לְטַהֵר. כְּשֶׁהָעוֹלָם שָׁרוּי בְּדִין וְצַד הַטֻּמְאָה מִתְפַּשֵּׁט בָּעוֹלָם, כָּאן נִכְלָלִים כָּל מִינִים שֶׁל טֻמְאָה וְכָל מִינֵי טָהֳרָה, וּמִשּׁוּם זֶה טֻמְאָה וְטָהֳרָה כְּלָל עֶלְיוֹן בַּתּוֹרָה, וּבֵאֲרוּהָ הַחֲבֵרִים. אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר, עָשִׂיתָ שֶׁלֹּא יאמְרוּ הַחֲבֵרִים דָּבָר אַחֲרֶיךְ.</p>\n<p>פָרָה אֲדֻמָּה תְּמִימָה אֲשֶׁר אֵין בָּהּ מוּם וְגוֹ'. אָסוּר לַחֲרשׁ בְּשַׁבָּת חֲרִישָׁה שֶׁל שׁוֹר, שֶׁנֶּאֱמַר (תהלים קכט) עַל גַּבִּי חָרְשׁוּ חֹרְשִׁים. וּשְׁכִינָה תַחְתּוֹנָה הִיא פָּרָה אֲדֻמָּה - מִצַּד הַגְּבוּרָה. תְּמִימָה - מִצַּד הַחֶסֶד, שֶׁהוּא דַּרְגַּת אַבְרָהָם, שֶׁנֶּאֱמַר בּוֹ (בראשית יז) הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים. אֲשֶׁר אֵין בָּהּ מוּם - מִצַּד הָעַמּוּד הָאֶמְצָעִי. אֲשֶׁר לֹא עָלָה עָלֶיהָ עֹל - מִצַּד שְׁכִינָה עֶלְיוֹנָה שֶׁהִיא חֵרוּת. בְּמָקוֹם שֶׁהִיא שׁוֹלֶטֶת, וְהַזָּר הַקָּרֵב אֵין לוֹ רְשׁוּת לַצַּד הָאַחֵר לִשְׁלֹט, לֹא שָׂטָן וְלֹא מַשְׁחִית וְלֹא מַלְאַךְ הַמָּוֶת, שֶׁהֵם מִצַּד הַגֵּיהִנֹּם.</p>"],[9522012389,"<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים קד) הַמְשַׁלֵּחַ מַעְיָנִים בַּנְּחָלִים וְגוֹ'. יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי וְגוֹ'. פְּסוּקִים אֵלּוּ אֲמָרָם דָּוִד הַמֶּלֶךְ בְּרוּחַ הַקֹּדֶשׁ, וְיֵשׁ לְהִסְתַּכֵּל בָּהֶם. בֹּא וּרְאֵה, בְּשָׁעָה שֶׁחָכְמָה עֶלְיוֹנָה מַכָּה בַחֲקִיקוֹת, אַף עַל גַּב שֶׁהִיא נִסְתֶּרֶת בְּכָל הַצְּדָדִים, נִפְתָּח וְשׁוֹפֵעַ מִמֶּנָּה נָהָר אֶחָד מָלֵא (וממלא לשערים) בִשְׁעָרִים עֶלְיוֹנִים.</p>\n<p>כְּמַבּוּעַ וּמָקוֹר שֶׁל מַיִם שֶׁמְּמַלֵּא כְּלִי גָּדוֹל מִמֶּנּוּ, וּמִשָּׁם נִמְשָׁכִים מַבּוּעִים שֶׁל נְחָלִים וּנְהָרוֹת בְּכָל צַד - כָּךְ זֶה, בִּשְׁבִיל דַּקִּיק אֶחָד שֶׁלֹּא נוֹדָע, מוֹשֵׁךְ וְשׁוֹפֵעַ אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא וּמְמַלֵּא לְאוֹתוֹ נַחַל עָמֹק, וּמִשָּׁם נִמְשָׁכִים מַבּוּעִים וּנְחָלִים וּמִתְמַלְּאִים מִמֶּנּוּ. זֶהוּ שֶׁכָּתוּב הַמְשַׁלֵּחַ מַעְיָנִים בַּנְּחָלִים וְגוֹ'. אֵלֶּה נְהָרוֹת עֶלְיוֹנֵי קֹדֶשׁ שֶׁל אֲפַרְסְמוֹן זַךְ, וְכֻלָּם מֻשְׁקִים כְּאֶחָד מֵאוֹתָהּ נְבִיעַת הַנַּחַל הָעֶלְיוֹן הַקָּדוֹשׁ שֶׁיּוֹצֵא וְשׁוֹפֵעַ.</p>\n<p>אַחַר כָּךְ, יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי, הַיְנוּ שֶׁכָּתוּב (בראשיתב) וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים. אַרְבָּעָה רָאשִׁים אֵלֶּה הֵם חַיְתוֹ שָׂדָי, כְּלַל כָּל אוֹתָן מֶרְכָּבוֹת וְכָל אוֹתָם חֲיָלוֹת שֶׁשָּׂדַי אֲחוּזָה בָהֶם. אַל תִּקְרֵי שָׂדַי אֶלָּא שַׁדַּי, שֶׁהוּא נוֹטֵל וּמַשְׁלִים אֶת הַשֵּׁם מִיסוֹד הָעוֹלָם.</p>\n<p>יִשְׁבְּרוּ פְרָאִים צְמָאָם - אֵלֶּה אוֹתָם שֶׁכָּתוּב בָּהֶם (יחזקאל א) וְהָאוֹפַנִּים יִנָּשְׂאוּ לְעֻמָּתָם כִּי רוּחַ הַחַיָּה בָּאוֹפַנִּים. מִי הַחַיָּה? אֶלָּא אֵלּוּ חַיְתוֹ שָׂדָי, אַרְבַּע הֵן, וְכָל אַחַת וְאַחַת לְצַד אֶחָד שֶׁל הָעוֹלָם. וְאוֹתוֹ שֶׁנִּקְרָא חַיָּה, וְאוֹפַנִּים מוּל כָּל אֶחָד וְאֶחָד. וְלֹא הוֹלְכִים אֶלָּא מֵרוּחַ אוֹתָהּ חַיָּה שֶׁהוֹלֶכֶת עֲלֵיהֶם, וְכַאֲשֶׁר אֵלֶּה מֻשְׁקִים מֵאוֹתָהּ הַשְׁקָאָה עֶלְיוֹנָה, כָּל שְׁאָר הַחֲיָלוֹת הָאֲחֵרִים מֻשְׁקִים וּמֻרְוִים וּמִשְׁתָּרְשִׁים בְּשָׁרְשֵׁיהֶם, וְנֶאֱחָזִים אֵלֶּה בְאֵלֶּה בִּדְרָגוֹת יְדוּעוֹת. זֶהוּ שֶׁכָּתוּב עֲלֵיהֶם עוֹף הַשָּׁמַיִם יִשְׁכּוֹן וְגוֹ'. מַשְׁקֶה הָרִים מֵעֲלִיּוֹתָיו וְגוֹ' - אֵלּוּ שְׁאָר דְּרָגוֹת עֶלְיוֹנוֹת.</p>\n<p>אַחַר כָּל זֶה - מִפְּרִי מַעֲשֶׂיךְ תִּשְׂבַּע הָאָרֶץ, (למטה, וכל העולמות וכו') אֶרֶץ עֶלְיוֹנָה קְדוֹשָׁה. וּכְשֶׁהִיא מִתְבָּרֶכֶת, כָּל הָעוֹלָמוֹת בְּשִׂמְחָה, וּמִתְבָּרְכִים. וְזֶה בְּשָׁעָה שֶׁנִּמְצָאוֹת בְּרָכוֹת מֵהַשְׁקָאַת הַנַּחַל הֶעָמֹק שֶׁל הַכֹּל.</p>\n<p>וּבְשָׁעָה שֶׁהָעוֹלָם יוֹשֵׁב בְּדִין, שֶׁבְּרָכוֹת לֹא נִמְצָאוֹת לָרֶדֶת בָּעוֹלָם, אָז נִטְמָא הַמִּקְדָּשׁ. (ובשעה שאין נמצאות ברכות לרדת למטה, אז העולם יושב בדין. ומצד שמאל מתעוררת רוח ומתפשטת בעולם) וְכַמָּה חֲבִילוֹת שֶׁל מַזִּיקִים נִמְצָאִים בָּעוֹלָם וְשׁוֹרִים (בכמה מקומות) עַל בְּנֵי אָדָם, וּמְטַמֵּאת אוֹתָם אוֹתָהּ הָרוּחַ, כְּמוֹ בֶּן אָדָם שֶׁגָּוַע (כבר הרוח הזו) וְרוּחַ הַטֻּמְאָה שׁוֹרָה עָלָיו. כָּךְ גַּם שׁוֹרָה, לְמִי שֶׁיִּקְרַב אֵלָיו.</p>\n<p>זֶהוּ שֶׁכָּתוּב תַּסְתִּיר פָּנֶיךְ יִבָּהֵלוּן וְגוֹ'. פָּסוּק זֶה מַהוּ אוֹמֵר? אֶלָּא תַּסְתִּיר פָּנֶיךְ יִבָּהֵלוּן, שֶׁהֲרֵי לֹא הֻשְׁקוּ לְהִמָּצֵא בְרָכוֹת לָעוֹלָמוֹת. תּוֹסֵף רוּחָם יִגְוָעוּן, (לעורר) וּמִתְעוֹרֵר רוּחַ אַחֵר מִצַּד שְׂמֹאל, וְרוּחַ טֻמְאָה שׁוֹרָה עַל בְּנֵי אָדָם, עַל אוֹתָם שֶׁמֵּתוּ וּמִי שֶׁעוֹמֵד עֲלֵיהֶם וְעַל שְׁאָר בְּנֵי אָדָם, מָה רְפוּאָתָם? זֶה שֶׁכָּתוּב וְאֶל עֲפָרָם יְשׁוּבוּן. זֶה עֲפַר שְׂרֵפַת הַחַטָּאת (זהעפר המקדש שלמעלה) בִּשְׁבִיל לִטַּהֵר בּוֹ, וְהַיְנוּ סוֹד (קהלת ג) הַכֹּל הָיָה מִן הֶעָפָר, וַאֲפִלּוּ גַּלְגַּל חַמָּה.</p>\n<p>לְאַחַר שֶׁחוֹזְרִים לֶעָפָר זֶה בִּשְׁבִיל לִטַּהֵר בּוֹ, נֶעֱבֶרֶת רוּחַ הַטֻּמְאָה, וּמִתְעוֹרֶרֶת רוּחַ אַחֶרֶת קְדוֹשָׁה וְשׁוֹרָה בָעוֹלָם. זֶהוּ שֶׁכָּתוּב תְּשַׁלַּח רוּחֲךְ יִבָּרֵאוּן, יִבָּרֵאוּן וְיֵרָפְאוּ בִּרְפוּאָה עֶלְיוֹנָה שֶׁל רוּחַ אַחֶרֶת. וּתְחַדֵּשׁ פְּנֵי אֲדָמָה, שֶׁהֲרֵי נִטְהֲרָה (אשה לבעלה), וְחִדּוּשׁ הַלְּבָנָה נִמְצָא, וְכָל הָעוֹלָמוֹת מִתְבָּרְכִים. אַשְׁרֵי חֵלֶק יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם עֵצָה שֶׁכֻּלָּהּ רְפוּאָה כְּדֵי שֶׁיִּזְכּוּ לְחַיֵּי הָעוֹלָם הַבָּא, וְיִמָּצְאוּ טְהוֹרִים בָּעוֹלָם הַזֶּה, קְדוֹשִׁים לָעוֹלָם הַבָּא, עֲלֵיהֶם כָּתוּב (יחזקאל לו) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם.</p>"],[9522012390,"<p>וַיָּבֹאוּ בְנֵי יִשְׂרָאֵל כָּל הָעֵדָה מִדְבַּר צִין וְגוֹ'. רַבִּי יְהוּדָה אָמַר, לָמָּה פָּרָשַׁת פָּרָה סְמוּכָה לְמִיתַת מִרְיָם, הֲרֵי פֵּרְשׁוּהָ. אֶלָּא כֵּיוָן (כמו) שֶׁנַּעֲשָׂה הַדִּין בְּפָרָה זוֹ לְטַהֵר הַטְּמֵאִים, נַעֲשָׂה דִין בְּמִרְיָם לְטַהֵר הָעוֹלָם, וְהִסְתַּלְּקָה מֵהָעוֹלָם. כֵּיוָן שֶׁהִסְתַּלְּקָה מִרְיָם, הִסְתַּלְּקָה אוֹתָהּ בְּאֵר שֶׁהָיְתָה הוֹלֶכֶת עִם יִשְׂרָאֵל בַּמִּדְבָּר, וְהִסְתַּלְּקָה הַבְּאֵר בַּכֹּל.</p>\n<p>אָמַר רַבִּי אַבָּא, כָּתוּב וְאַתָּה בֶּן אָדָם שָׂא קִינָה עַל בְּתוּלַת יִשְׂרָאֵל. וְכִי עָלֶיהָ לְבַדָּהּ? לֹא. אֶלָּא מִשּׁוּם שֶׁהַכֹּל נִשְׁבַּר בִּגְלָלָהּ. בִּגְלָלָהּ נִשְׁבַּר הַיָּמִין אַחֲרֶיהָ, שֶׁהָיָה מְקָרְבָהּ לַגּוּף. וְהַגּוּף, שֶׁהוּא שֶׁמֶשׁ, נֶחְשַׁךְ בִּגְלָלָהּ, וְזֶהוּ שֶׁכָּתוּב (תהלים ס) הוֹשִׁיעָה יְמִינְךְ וַעֲנֵנִי. גּוּף, (בגללה, שכתוב (ישעיה יג) חשך השמשבצאתו, וכתוב) שֶׁכָּתוּב (ישעיה נ) אַלְבִּישׁ שָׁמַיִם קַדְרוּת, שֶׁהֲרֵי הַשֶּׁמֶשׁ נֶחְשַׁךְ בִּגְלָלָהּ. כְּמוֹ זֶה, וַתָּמָת שָׁם מִרְיָם וְגוֹ'.</p>\n<p>וְלֹא הָיָה מַיִם לָעֵדָה, שֶׁהֲרֵי הִסְתַּלְּקָה הַבְּאֵר שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה, אַחַר כָּךְ נִשְׁבַּר הַיָּמִין, שֶׁכָּתוּב יֵאָסֵף אַהֲרֹן אֶל עַמָּיו. וְאַחַר כָּךְ נֶחְשַׁךְ הַשֶּׁמֶשׁ, שֶׁכָּתוּב (דברים לב) וּמֻת בָּהָר וְגוֹ', וְהֵאָסֵף אֶל עַמֶּיךְ וְגוֹ'. הֲרֵי זְרוֹעַ יָמִין נִשְׁבְּרָה, וְהַגּוּף, שֶׁהוּא שֶׁמֶשׁ, נֶחְשַׁךְ.</p>\n<p>וּבֹא וּרְאֵה, לֹא נִמְצָא דוֹר בָּעוֹלָם כְּמוֹ הַדּוֹר שֶׁעָמַד מֹשֶׁה בָּעוֹלָם, וְאַהֲרֹן וּמִרְיָם. וְאִם תֹּאמַר בִּימֵי שְׁלֹמֹה גַּם כָּךְ - לֹא! שֶׁהֲרֵי בִּימֵי שְׁלֹמֹה שָׁלְטָה הַלְּבָנָה, וְהַשֶּׁמֶשׁ הִתְכַּנְּסָה. וּבִימֵי מֹשֶׁה הִתְכַּנְּסָה הַלְּבָנָה וְשָׁלַט הַשֶּׁמֶשׁ.</p>\n<p>שְׁלֹשָה אַחִים הָיוּ: מֹשֶׁה, אַהֲרֹן וּמִרְיָם, כְּמוֹ שֶׁנֶּאֱמַר (מיכה ו) וָאֶשְׁלַח לְפָנֶיךְ אֶת מֹשֶׁה אַהֲרֹן וּמִרְיָם. מִרְיָם - לְבָנָה. מֹשֶׁה - שֶׁמֶשׁ. אַהֲרֹן - זְרוֹעַ יָמִין. חוּר - זְרוֹעַ שְׂמֹאל. וְיֵשׁ אוֹמְרִים נַחְשׁוֹן בֶּן עַמִּינָדָב. בַּהַתְחָלָה מֵתָה מִרְיָם - הִסְתַּלְּקָה הַלְּבָנָה וְהִסְתַּלְּקָה הַבְּאֵר. אַחַר כָּךְ נִשְׁבְּרָה זְרוֹעַ יָמִין שֶׁמְּקָרֶבֶת תָּמִיד אֶת הַלְּבָנָה בְּאַחֲוָה וּבְשִׂמְחָה, וְעַל זֶה כָּתוּב (שמות טו) וַתִּקַּח מִרְיָם הַנְּבִיאָה אֲחוֹת אַהֲרֹן. אֲחוֹת אַהֲרֹן בְּוַדַּאי, שֶׁהִיא זְרוֹעַ שֶׁמְּקָרְבָהּ בְּאַחְדוּת וּבְאַחֲוָה עִם הַגּוּף.</p>\n<p>אַחַר כָּךְ הִתְכַּנֵּס הַשֶּׁמֶשׁ וְנֶחְשַׁךְ, כְּמוֹ שֶׁאָמַרְנוּ שֶׁכָּתוּב (במדבר כז) וְנֶאֱסַפְתָּ (והאסף) אֶל עַמֶּיךְ גַּם אָתָּה וְגוֹ'. אַשְׁרֵי חֶלְקָם שֶׁל מֹשֶׁה, אַהֲרֹן וּמִרְיָם שֶׁנִּמְצְאוּ בָעוֹלָם. בִּימֵי שְׁלֹמֹה שָׁלְטָה הַלְּבָנָה בְתִקּוּנֶיהָ וְנִרְאֲתָה בָעוֹלָם, וְהִתְקַיֵּם שְׁלֹמֹה בְּחָכְמַת הָאוֹר שֶׁלָּהּ וְשָׁלַט בָּעוֹלָם. כֵּיוָן שֶׁהַלְּבָנָה יָרְדָה בַּעֲונוֹתָיו, נִפְגַּם יוֹם אַחַר יוֹם, עַד שֶׁנִּמְצָא בְקֶרֶן מַעֲרָבִית וְלֹא יוֹתֵר, וְנִתַּן שֵׁבֶט אֶחָד לִבְנוֹ. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה נָבִיא הַנֶּאֱמָן.</p>\n<p>כָּתוּב (קהלת א) וְזָרַח הַשֶּׁמֶשׁ וּבָא הַשָּׁמֶשׁ וְגוֹ'. פָּסוּק זֶה בֵּאַרְנוּ. אֲבָל וְזָרַח הַשֶּׁמֶשׁ, כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, שֶׁהֵאִיר הַשֶּׁמֶשׁ וְלֹא הַלְּבָנָה. וְאֶל מְקוֹמוֹ שׁוֹאֵף וְגוֹ'. הֲרֵי כָּתוּב וּבָא הַשָּׁמֶשׁ, בַּמִּדְבָּר, עִם שְׁאָר מֵתֵי מִדְבָּר. כֵּיוָן שֶׁנִּכְנַס הַשֶּׁמֶשׁ, לְאֵיזֶה מָקוֹם הִתְכַּנֵּס? אֶל מְקוֹמוֹ, בִּשְׁבִיל לְהָאִיר לַלְּבָנָה. זֶהוּ שֶׁכָּתוּב שׁוֹאֵף זוֹרֵחַ הוּא שָׁם. שֶׁאַף עַל גַּב שֶׁהִתְכַּנֵּס, זוֹרֵחַ הוּא שָׁם וַדַּאי. שֶׁהֲרֵי לֹא מוּאֶרֶת הַלְּבָנָה אֶלָּא מֵאוֹר הַשֶּׁמֶשׁ. וְזֶהוּ סוֹד הַכָּתוּב (דברים לא) הִנְּךְ שֹׁכֵב עִם אֲבֹתֶיךְ וְקָם. אַף עַל גַּב שֶׁתִּתְכַּנֵּס, הִנְּךְ קַיָּם לְהָאִיר לַלְּבָנָה (ועליה זה הוא יהושע).</p>\n<p>כָּךָ הוּא מֹשֶׁה, וְעָלָיו כָּתוּב פָּסוּק זֶה, מַה יִּתְרוֹן לָאָדָם בְּכָל עֲמָלוֹ וְגוֹ'. מַה יִּתְרוֹן לָאָדָם בְּכָל עֲמָלוֹ - זֶה יְהוֹשֻׁעַ שֶׁהִשְׁתַּדֵּל לְהוֹרִישׁ אֶרֶץ יִשְׂרָאֵל, וְלֹא זָכָה לְהַשְׁלִים לַלְּבָנָה כָּרָאוּי, שֶׁהֲרֵי הוּא עָמַל בְּיִשְׂרָאֵל תַּחַת הַשָּׁמֶשׁ, תַּחַת מֹשֶׁה. בּא וּרְאֵה, אוֹי לְאוֹתָהּ בּוּשָׁה, אוֹי לְאוֹתָהּ כְּלִמָּה, מִשּׁוּם שֶׁעָבַד וְלֹא לָקַח מְקוֹמוֹ מַמָּשׁ, אֶלָּא תַּחַת הַשֶּׁמֶשׁ, וְלֹא הָיָה לוֹ אוֹר מִשֶּׁלּוֹ, אֶלָּא אוֹר שֶׁהֵאִיר לוֹ. וְאִם כָּךְ מַהוּ שִׁבְחוֹ, הוֹאִיל וְלֹא הִשְׁלִים לְכָאן וּלְכָאן?</p>\n<p>וּבְכָל מָקוֹם שֶׁאָמַר שְׁלֹמֹה תַּחַת הַשָּׁמֶשׁ, עַל דַּרְגָּתוֹ אָמַר. (קהלת ה) רָאִיתִי תַּחַת הַשָּׁמֶשׁ. (שם ג) וְעוֹד רָאִיתִי תַּחַת הַשָּׁמֶשׁ. (שם ט) שַׁבְתִּי וְרָאֹה תַחַת הַשֶּׁמֶשׁ. וְכֵן כֻּלָּם. וּמִשּׁוּם דַּרְגָּתוֹ אָמַר, וְזֶהוּ סוֹד הַדָּבָר בְּוַדַּאי.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, וַדַּאי מִי שֶׁנּוֹטֵל סַם הַמָּוֶת לְבַדּוֹ, עָלָיו כָּתוּב (שם א) בְּכָל עֲמָלוֹ שֶׁיַּעֲמֹל תַּחַת הַשָּׁמֶשׁ וַדַּאי. וּמִי הוּא תַּחַת הַשָּׁמֶשׁ? הֱוֵי אוֹמֵר זוֹ הַלְּבָנָה. וּמִי שֶׁאוֹחֵז הַלְּבָנָה בְּלִי הַשֶּׁמֶשׁ, עֲמָלוֹ תַּחַת הַשָּׁמֶשׁ וַדַּאי. וְזֶהוּ הַחֵטְא הַקַּדְמוֹן שֶׁל הָעוֹלָם. וְעַל זֶה מַה יִּתְרוֹן לָאָדָם בְּכָל עֲמָלוֹ, לְאָדָם הָרִאשׁוֹן, וְכֵן לְכָל מִי שֶׁבָּא אַחֲרָיו שֶׁחָטְאוּ בְּמָקוֹם זֶה.</p>"],[9522012391,"<p>הוֹלֵךָ אֶל דָּרוֹם וְסוֹבֵב אֶל צָפוֹן, הַיְנוּ שֶׁכָּתוּב (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ. יְמִינוֹ - זֶה דָרוֹם. אֵשׁ דָּת - זֶה צָפוֹן. וְזֶה כָּלוּל בָּזֶה.</p>\n<p>סוֹבֵב סבֵב הוֹלֵךְ הָרוּחַ. פָּסוּק זֶה קָשֶׁה. סוֹבֵב סוֹבֵב הַשֶּׁמֶשׁ הָיָה לוֹ לִכְתֹּב, מַה זֶּה הוֹלֵךְ הָרוּחַ? מִי רוּחַ זוֹ? זֶהוּ תַּחַת הַשֶּׁמֶשׁ, שֶׁנִּקְרָא רוּחַ הַקֹּדֶשׁ. וְזֶה (הוא) רוּחַ שֶׁהוֹלֵךְ וְסוֹבֵב לְאוֹתָם שְׁנֵי צְדָדִים לְהִתְחַבֵּר בְּגוּף, וְעַל זֶה כָּתוּב הָרוּחַ, אותו שִּנּודָע הַשִּמִשּ סתָם, שִּנּודָע (להתחבר בגוף שהוא השמש, אותו שנודע) חֵלֶק יִשְׂרָאֵל.</p>\n<p>וְעַל סְבִיבתָיו שָׁב הָרוּחַ. מִי זֶה סְבִיבתָיו? אֵלּוּ הָאָבוֹת, שֶׁהֵם מֶרְכָּבָה קְדוֹשָׁה, וְהֵם שְׁלֹשָׁה, וְדָוִד וְאַרְבָּעָה רוּחוֹת שֶׁהִתְחַבְּרוּ בָהֶם (ס\"י וזהו רוח שהתחבר בהם) (ודוד הוא רוח רביעי שהתחבר בהם), הֲרֵי הֵם מֶרְכָּבָה קְדוֹשָׁה שְׁלֵמָה. וְעַל זֶה כָּתוּב (תהלים קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה.</p>\n<p>מִשּׁוּם שֶׁכָּל דִּבְרֵי שְׁלֹמֹה הַמֶּלֶךְ נִסְתָּרִים כֻּלָּם בְּחָכְמָה, וְכֻלָּם פְּנִים פְּנִימָה שֶׁל הֵיכַל הַקָּדוֹשׁ, וּבְנֵי אָדָם לֹא מִסְתַּכְּלִים בָּהֶם, וְרוֹאִים דְּבָרָיו כְּדִבְרֵי אָדָם אַחֵר. אִם כָּךְ, מַהוּ הַשֶּׁבַח לִשְׁלֹמֹה הַמֶּלֶךְ בְּחָכְמָתוֹ מִשְּׁאָר בְּנֵי אָדָם? אֶלָּא וַדַּאי כָּל דָּבָר וְדָבָר שֶׁל שְׁלֹמֹה הַמֶּלֶךְ נִסְתָּר בְּחָכְמָה.</p>"],[9522012392,"<p>פָּתַח וְאָמַר, (קהלת ז) טוֹבָה חָכְמָה עִם נַחֲלָה וְיֹתֵר לְרֹאֵי הַשָּׁמֶשׁ. אִם לֹא הִתְגַּלָּה דָבָר זֶה, לֹא (שמענו ולא) יָדַעְנוּ מָה אָמַר. טוֹבָה חָכְמָה - זוֹהִי חָכְמָה שֶׁהִיא תַּחַת הַשֶּׁמֶשׁ, (לכסא) כִּסֵּא מְתֻקֶּנֶת לוֹ. טוֹבָה חָכְמָה עִם נַחֲלָה, יָפָה וְנָאָה כְּשֶׁהִיא שׁוֹרָה עִם יִשְׂרָאֵל, שֶׁהֵם נַחֲלָתָהּ וְחֶלְקָהּ לְהִתְקַשֵּׁר בָּהּ.</p>\n<p>אֲבָל שֶׁבַח יוֹתֵר לְרֹאֵי הַשָּׁמֶשׁ, לְאוֹתָם שֶׁזָּכוּ לְהִתְחַבֵּר בַּשֶּׁמֶשׁ וּלְהִתְקַשֵּׁר בּוֹ, שֶׁהֲרֵי אָחוּז בְּעֵץ הַחַיִּים, וּמִי שֶׁאוֹחֵז בּוֹ, אוֹחֵז בַּכֹּל, בְּחַיֵּי הָעוֹלָם הַזֶּה וּבְחַיֵּי הָעוֹלָם הַבָּא. וְזֶהוּ שֶׁכָּתוּב (שם) וְיִתְרוֹן דַּעַת הַחָכְמָה תְּחַיֶּה בְעָלֶיהָ. מַה זֶּה וְיִתְרוֹן דַּעַת? זֶה עֵץ הַחַיִּים. יִתְרוֹנוֹ מַהוּ? הַחָכְמָה וַדַּאי, שֶׁהֲרֵי תּוֹרָה יוֹצֵאת מֵחָכְמָה עֶלְיוֹנָה.</p>\n<p>עוֹד טוֹבָה חָכְמָה עִם נַחֲלָה - טוֹבָה חָכְמָה וַדַּאי עִם נַחֲלָה, זֶה צַדִּיק הָעוֹלָם שֶׁהוּא אוֹר הַשֶּׁמֶשׁ, שֶׁהֲרֵי שְׁתֵּי דְרָגוֹת אֵלּוּ יוֹשְׁבוֹת כְּאֶחָד, וְזֶהוּ יָפְיָן, אֲבָל וְיֹתֵר לְרֹאֵי הַשָּׁמֶשׁ, לְאוֹתָם שֶׁנֶּאֱחָזִים בַּשֶּׁמֶשׁ, חֹזֶק הַכֹּל, שֶׁבַח הַכֹּל.</p>\n<p>וְזְהִוּ דַּעַת, עֵץ הַחַיִּים, וַהֲרֵי פֵּרְשׁוּהוּ, (משלי יט) בְּלֹא דַעַת נֶפֶשׁ לֹא טוֹב. אֵיזוֹ נֶפֶשׁ? זוֹ נֶפֶשׁ טוֹבָה שֶׁל דָּוִד הַמֶּלֶךְ, וְזוֹ הַחָכְמָה שֶׁאָמַרְנוּ. וּמִשּׁוּם זֶה יִתְרוֹן דַּעַת הַחָכְמָה, שֶׁמִּשָּׁם נִשְׁרַשׁ עֵץ וְנִנְטַע לְכָל הַצְּדָדִים, וְכֵן לְכָל אֵלּוּ שֶׁאֲחוּזִים בָּעֵץ הַזֶּה. וְעַל זֶה שְׁלֹמֹה הַמֶּלֶךְ לֹא נִמְצָא אֶלָּא בְּאוֹתָהּ דַּרְגָּה שֶׁלּוֹ, וּמִשָּׁם יָדַע הַכֹּל, וְהָיָה אוֹמֵר: עוֹד רָאִיתִי תַּחַת הַשָּׁמֶשׁ, וְשַׁבְתִּי וְרָאִיתִי וְגוֹ'. וְכֵן כֻּלָּם. אַשְׁרֵי אוֹתָם צַדִּיקִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה וְיוֹדְעִים דַּרְכֵי הַמֶּלֶךְ הַקָּדוֹשׁ וְנִסְתָּרוֹת עֶלְיוֹנִים שֶׁגְּנוּזִים בַּתּוֹרָה, שֶׁכָּתוּב (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה' וְגוֹ'.</p>"],[9522012393,"<p>יֵאָסֵף אַהֲרֹן אֶל עַמָּיו וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (קהלת ד) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ וְגוֹ'. פָּסוּק זֶה נֶאֱמַר וּפֵרְשׁוּהוּ. בֹּא וּרְאֵה, כָּל מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּדִין וֶאֱמֶת, וְאֵין מִי שֶׁיַּקְשֶׁה כְּנֶגְדּוֹ וְיִמְחֶה בְיָדוֹ וְיֹאמַר לוֹ מָה אַתָּה עוֹשֶׂה, וְכִרְצוֹנוֹ עוֹשֶׂה הַכֹּל.</p>\n<p>וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים. וְכִי שְׁלֹמֹה הַמֶּלֶךְ מְשַׁבֵּחַ אֶת הַמֵּתִים יוֹתֵר מֵהַחַיִּים? וַהֲרֵי לֹא נִקְרָא חַי אֶלָּא מִי שֶׁהוּא בְּדֶרֶךְ אֱמֶת בָּעוֹלָם הַזֶּה, כְּמוֹ שֶׁנֶּאֱמַר (שמואל בכג) וּבְנָיָהוּ בֶן יְהוֹיָדָע בֶּן אִישׁ חַי, וַהֲרֵי פֵּרְשׁוּהוּ הַחֲבֵרִים, וְרָשָׁע שֶׁלֹּא הוֹלֵךְ בְּדֶרֶךְ אֱמֶת נִקְרָא מֵת, וְהוּא מְשַׁבֵּחַ אֶת הַמֵּתִים מֵהַחַיִּים?</p>\n<p>אֶלָּא וַדַּאי כָּל דִּבְרֵי שְׁלֹמֹה הַמֶּלֶךְ בְּחָכְמָה נֶאֶמְרוּ, וַהֲרֵי נִתְבָּאֵר. וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים, אִלּוּ לֹא כָתוּב יוֹתֵר, הָיִיתִי אוֹמֵר כָּךְ. אֲבָל כֵּיוָן שֶׁכָּתוּב שֶׁכְּבָר מֵתוּ, נִמְצָא דָבָר אַחֵר בְּחָכְמָה. שֶׁכְּבָר מֵתוּ - זְמַן אַחֵר הִסְתַּלְּקוּ מֵהָעוֹלָם, וְהִתְתַּקְּנוּ בֶעָפָר, (שהזדמן הממנה עליו ומת בחיי עולם כדי שיתתקן (שהזדּמן עָלָיו ושָב בָּעולָם הזּה כּדי שיּתתּקּן) (הממנּה עָלָיו וּמת בָּעולָם הזּה ונתקן בּעָפָר כּדי שיּתתּקּן בּמָקום שיּשלם זמנּו מת הוּא ודּאי, זהוּ שבח משאָר מתי הָעולָם. אם תּאמר לא ידּון פּעם אחרת בּאותו עולָם, הרי כָּתוּב לא תָקוּם וגו') לאחר שנשלם זמנו מת, ודאי הוא שבח משאר מתי העולם. אם תאמר לא ידון פעם אחרת באותו עולם, שכתוב לא תקום פעמים צרה) כָּל שֶׁכֵּן שֶׁזֶּה קִבֵּל עֹנֶשׁ פַּעַם וּפַעֲמַיִם, וְזֶה וַדַּאי מְקוֹמוֹ נִתְקָן בְּשֶׁבַח יוֹתֵר מֵאוֹתָם חַיִּים שֶׁעֲדַיִן לֹא קִבְּלוּ עָנְשָׁם.</p>\n<p>וְעַל זֶה כָּתוּב וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, דַּוְקָא. אֵלֶּה אוֹתָם חַיִּים, וְנִקְרָאִים מֵתִים. מָה הַטַּעַם נִקְרָאִים מֵתִים? מִשּׁוּם שֶׁהֲרֵי טָעֲמוּ טַעַם הַמָּוֶת. וְאַף עַל גַּב שֶׁעוֹמְדִים בָּעוֹלָם הַזֶּה, הֵם מֵתִים, וּמִבֵּין הַמֵּתִים חָזְרוּ, וְעוֹד עַל מַעֲשִׂים רִאשׁוֹנִים עוֹמְדִים לְתִקּוּן, וְנִקְרָאִים מֵתִים. מִן הַחַיִּים אֲשֶׁר הֵמָּה חַיִּים - שֶׁעוֹד לֹא טָעֲמוּ טַעַם מָוֶת וְלֹא קִבְּלוּ עָנְשָׁם, וְלֹא יוֹדְעִים אִם זַכָּאִים בְּאוֹתוֹ הָעוֹלָם וְאִם לֹא.</p>\n<p>בֹּא וּרְאֵה, צַדִּיקִים שֶׁזּוֹכִים לְהִתְקַשֵּׁר בִּצְרוֹר הַחַיִּים, הֵם זַכָּאִים לִרְאוֹת בִּכְבוֹד הַמֶּלֶךְ הָעֶלְיוֹן הַקָּדוֹשׁ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים כז) לַחֲזוֹת בְּנֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ. וְאוֹתָם מְדוֹרֵיהֶם יוֹתֵר וְעֶלְיוֹן מִכָּל אוֹתָם מַלְאָכִים קְדוֹשִׁים וְכָל דַּרְגוֹתֵיהֶם. שֶׁהֲרֵי אוֹתוֹ מָקוֹם (חדוה) עֶלְיוֹן לֹא זוֹכִים עֶלְיוֹנִים וְתַחְתּוֹנִים לִרְאוֹתוֹ. זֶהוּ שֶׁכָּתוּב (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ וְגוֹ'.</p>\n<p>וְאוֹתָם שֶׁלֹּא זוֹכִים לַעֲלוֹת כָּל כָּךְ כְּאוֹתָם אֵלֶּה, (מקום יש וכו') מְקוֹמוֹת יֵשׁ לָהֶם לְמַטָּה כְּפִי דַרְכֵיהֶם, וְאֵלֶּה לֹא זוֹכִים לְאוֹתוֹ מָקוֹם וְלִרְאוֹת כְּפִי שֶׁרוֹאִים אֵלּוּ שֶׁלְּמַעְלָה, וְאֵלֶּה עוֹמְדִים בְּקִיּוּם שֶׁל עֵדֶן הַתַּחְתּוֹן וְלֹא יוֹתֵר. וְאִם תֹּאמַר, מַה זֶּה עֵדֶן תַּחְתּוֹן? אֶלָּא זֶה עֵדֶן שֶׁנִּקְרָא חָכְמָה תַחְתּוֹנָה, וְזֶה עוֹמֵד עַל גַּן שֶׁבָּאָרֶץ, וְהַשְׁגָּחַת עֵדֶן זֶה עָלָיו (ולא יותר), וְאֵלֶּה עוֹמְדִים בְּגַן זֶה וְנֶהֱנִים מֵעֵדֶן זֶה.</p>\n<p>מַה בֵּין עֵדֶן תַּחְתּוֹן לָעֶלְיוֹן? (קהלת ב) כִּיתְרוֹן הָאוֹר מִן הַחֹשֶׁךְ. עֵדֶן תַּחְתּוֹן נִקְרָא עֵדֶן נְקֵבָה, עֵדֶן עֶלְיוֹן נִקְרָא עֵדֶן זָכָר, עָלָיו כָּתוּב עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ. עֵדֶן תַּחְתּוֹן זֶה נִקְרָא גַּן לְעֵדֶן שֶׁלְּמַעְלָה, וְגַן זֶה נִקְרָא עֵדֶן לַגָּן שֶׁלְּמַטָּה. וְאֵלֶּה שֶׁנִּמְצָאִים בַּגָּן הַתַּחְתּוֹן נֶהֱנִים מֵהָעֵדֶן הַזֶּה שֶׁעֲלֵיהֶם בְּכָל שַׁבָּת וְשַׁבָּת וּבְכָל חֹדֶשׁ וְחֹדֶשׁ. זֶהוּ שֶׁכָּתוּב (ישעיה סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ.</p>\n<p>וְעַל אֵלֶּה אָמַר שְׁלֹמֹה, מִן הַחַיִּים אֲשֶׁר הֵמָּה חַיִּים עֲדֶנָה. שֶׁהֲרֵי אֵלֶּה בְּדַרְגָּה עֶלְיוֹנָה יוֹתֵר מֵהֶם. מִי אֵלּוּ? אֵלּוּ שֶׁכְּבָר מֵתוּ וְקִבְּלוּ עֹנֶשׁ פַּעֲמַיִם, וְאֵלֶּה נִקְרָאִים כֶּסֶף מְזֻקָּק, שֶׁנִּכְנָס לָאֵשׁ פַּעֲמַיִם וּשְׁנַיִם, וְיוֹצֵא מִמֶּנּוּ זֻהֲמָא, וְהִתְבָּרֵר וְהִתְנַקָּה. וְטוֹב מִשְּׁנֵיהֶם אֵת אֲשֶׁר עֲדֶן לֹא הָיָה - אוֹתָהּ רוּחַ שֶׁעוֹמֶדֶת לְמַעְלָה וְהִתְעַכְּבָה לָרֶדֶת לְמַטָּה, שֶׁהֲרֵי עוֹמֵד בְּעָמְדוֹ וְאֵין לוֹ לְקַבֵּל עֹנֶשׁ, וְיֵשׁ לוֹ מָזוֹן מֵאוֹתוֹ מָזוֹן עֶלְיוֹן שֶׁלְּמַעְלָה לְמַעְלָה.</p>\n<p>טוֹב מִכֻּלָּם מִי שֶׁלֹּא הִתְפָּרֵשׁ וְלֹא הִתְגַּלָּה וְכָל דְּבָרָיו בְּנִסְתָּר הֵם, זֶהוּ זַכַּאי חָסִיד שֶׁשָּׁמַר מִצְווֹת הַתּוֹרָה וְקִיְּמָן, וְהִשְׁתַּדֵּל בַּתּוֹרָה יוֹמָם וָלַיְלָה. זֶה נֶאֱחָז וְנֶהֱנֶה בְּדַרְגָּה עֶלְיוֹנָה עַל כָּל שְׁאָר בְּנֵי אָדָם, וְכֻלָּם נֶאֱחָזִים (נכוים) מֵחֻפָּתוֹ.</p>\n<p>בֹּא וּרְאֵה, בְּשָׁעָה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה יֵאָסֵף אַהֲרֹן אֶל עַמָּיו, נֶחֱלַשׁ כֹּחוֹ, וְיָדַע שֶׁנִּשְׁבְּרָה זְרוֹעוֹ הַיְמָנִית, וְהִזְדַּעֲזַע כָּל גּוּפוֹ. כֵּיוָן שֶׁאָמַר קַח אֶת אַהֲרֹן וְאֶת אֶלְעָזָר בְּנוֹ, אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: מֹשֶׁה, הֲרֵי זְרוֹעַ אַחֶרֶת הִלְוֵיתִי לְךְ (זמנתי לך), וְהַפְשֵׁט אֶת אַהֲרֹן וְגוֹ', וְאַהֲרֹן יֵאָסֵף, הֲרֵי אֶלְעָזָר יִהְיֶה אֶצְלְךְ בִּזְמַן (ימין) זֶה תַּחַת אָבִיו. וְעִם כָּל זֶה לֹא הִשְׁלִים מָקוֹם בְּאוֹתוֹ זְמַן כְּאָבִיו, שֶׁהֲרֵי עַנְנֵי הַכָּבוֹד הִסְתַּלְּקוּ, וְלֹא חָזְרוּ אֶלָּא בִּזְכוּת מֹשֶׁה, וְלֹא בִּזְכוּת אֶלְעָזָר.</p>\n<p>וַיַּעַשׂ מֹשֶׁה כַּאֲשֶׁר צִוָּה וְגוֹ'. לָמָּה לְעֵינֵי כָּל הָעֵדָה? אֶלָּא מִשּׁוּם שֶׁאַהֲרֹן הָיָה אֲהוּב הָעָם יוֹתֵר מֵהַכֹּל, וְלֹא יֹאמְרוּ שֶׁזֶּה נִמְשָׁךְ עַל יְדֵי מֹשֶׁה. וּמֹשֶׁה מָשַׁךְ לְאַהֲרֹן בִּדְבָרִים עַד שֶׁעָלוּ לָהָר, וְכָל יִשְׂרָאֵל הָיוּ רוֹאִים בְּשָׁעָה שֶׁהִפְשִׁיט מֹשֶׁה לְבוּשֵׁי אַהֲרֹן וְהִלְבִּישָׁם לְאֶלְעָזָר.</p>\n<p>מָה הַטַּעַם מֹשֶׁה (ולאהרן) ? אֶלָּא מֹשֶׁה הִלְבִּישָׁם אֶת אַהֲרֹן כְּשֶׁעָלָה לַכְּהֻנָּה, זֶהוּ שֶׁכָּתוּב וַיַּלְבֵּשׁ מֹשֶׁה אֶת אַהֲרֹן אֶת בְּגָדָיו, וְכָתוּב (ויקרא ח) וַיַּלְבֵּשׁ אֹתוֹ אֶת הַמְּעִיל. כָּעֵת מֹשֶׁה הוֹרִיד מִמֶּנּוּ מַה שֶּׁנָּתַן לוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הוֹרִיד מִמֶּנּוּ מַה שֶּׁנָּתַן לוֹ, וּשְׁנֵיהֶם הִפְשִׁיטוּ אֶת אַהֲרֹן מֵהַכֹּל, וּמֹשֶׁה הוֹרִיד מִבַּחוּץ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִבִּפְנִים. וְעַד שֶׁמֹּשֶׁה הוֹרִיד, הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא הוֹרִיד. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה.</p>\n<p>אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִּכְבוֹדָם. הִתְקִין הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַהֲרֹן מִטָּה וּמְנוֹרַת זָהָב שֶׁמְּאִירָה. וּמִשֶּׁלּוֹ לָקַח, מֵאוֹתָהּ מְנוֹרָה שֶׁהִדְלִיק בְּכָל יוֹם פַּעֲמַיִם, וְנִסְתַּם פִּי הַמְּעָרָה וְיָרְדוּ.</p>\n<p>רַבִּי יְהוּדָה אָמַר, פִּי הַמְּעָרָה הָיָה פָּתוּחַ, שֶׁכָּל יִשְׂרָאֵל רָאוּ אֶת אַהֲרֹן שׁוֹכֵב וְנֵר הַמְּנוֹרָה דּוֹלֵק לְפָנָיו, וּמִטָּתוֹ יוֹצֵאת וְנִכְנֶסֶת, וְעָנָן אֶחָד עוֹמֵד עָלָיו. וְאָז יָדְעוּ יִשְׂרָאֵל שֶׁהֲרֵי מֵת אַהֲרֹן, וְרָאוּ שֶׁהֲרֵי הִסְתַּלְּקוּ עַנְנֵי הַכָּבוֹד. זֶהוּ שֶׁכָּתוּב וַיִּרְאוּ כָּל הָעֵדָה כִּי גָוַע אַהֲרֹן וְגוֹ', וַהֲרֵי פֵּרְשׁוּהָ. וְעַל זֶה בָּכוּ לְאַהֲרֹן כָּל בֵּית יִשְׂרָאֵל, גְּבָרִים וְנָשִׁים וָטַף, שֶׁהֲרֵי אָהוּב מִכֻּלָּם הָיָה.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, שְׁלֹשֶׁת אַחִים עֶלְיוֹנִים קְדוֹשִׁים אֵלּוּ לָמָּה לֹא נִקְבְּרוּ בְמָקוֹם אֶחָד, וְהָאֵיבָרִים הִתְפַּזְּרוּ, אֶחָד כָּאן וְאֶחָד כָּאן וְאֶחָד בְּמָקוֹם אַחֵר? אֶלָּא יֵשׁ אוֹמְרִים, בְּמָקוֹם שֶׁצְּרִיכִים יִשְׂרָאֵל לְהִסְתַּכֵּן בּוֹ, מֵת כָּל אֶחָד וְאֶחָד, בִּשְׁבִיל לְהָגֵן עֲלֵיהֶם, וְנִצְּלוּ. אֲבָל כָּל אֶחָד וְאֶחָד מֵת כָּרָאוּי עֲלֵיהֶם. מִרְיָם בְּקָדֵשׁ, בֵּין צָפוֹן לְדָרוֹם. אַהֲרֹן לְצַד יָמִין. מֹשֶׁה כָּרָאוּי לוֹ. אָחַז אוֹתוֹ הַר לְהַר אַהֲרֹן, וְכָנַס לִקְבוּרַת מִרְיָם לְגַבֵּי אוֹתוֹ הָהָר, אָחַז לִשְׁנֵי צְדָדִים. וְעַל זֶה נִקְרָא (דברים לב) הַר הָעֲבָרִים, שֶׁשְּׁנֵי צִדֵּי הָהָר שֶׁעוֹבְרִים, וְאָחַז לְצַד זֶה וּלְצַד זֶה.</p>\n<p>אַשְׁרֵי חֵלֶק הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. וְאַף עַל גַּב שֶׁהֵם בְּמָקוֹם אַחֵר, בְּעוֹלָם אַחֵר עֶלְיוֹן, זְכוּתָם עוֹמֶדֶת בָּעוֹלָם הַזֶּה לְדוֹרֵי דוֹרוֹת. וּבְשָׁעָה שֶׁיִּשְׂרָאֵל חוֹזְרִים בִּתְשׁוּבָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּגְזֵרָה נִגְזֶרֶת עֲלֵיהֶם, אָז קוֹרֵא הַקָּדוֹשׁ בָּרוּךְ הוּא לַצַּדִּיקִים שֶׁעוֹמְדִים לְפָנָיו לְמַעְלָה וּמוֹדִיעַ לָהֶם, וְהֵם מְבַטְּלִים אוֹתָהּ גְּזֵרָה, וְחָס הַקָּדוֹשׁ בָּרוּךְ הוּא עַל יִשְׂרָאֵל. אַשְׁרֵי הַצַּדִּיקִים, שֶׁעֲלֵיהֶם כָּתוּב (ישעיה נח) וְנָחֲךְ ה' תָּמִיד וְגוֹ'.</p>"],[9522012394,"<p>וַיְדַבֵּר הָעָם בֵּאלֹהִים וּבְמֹשֶׁה וְגוֹ'. פָּרָשָׁה זוֹ בְּמָקוֹם אַחֵר עָלְתָה עִם אוֹתָם מֵי מְרִיבָה שֶׁל מֹשֶׁה וְאַהֲרֹן.</p>\n<p>רַבִּי יִצְחָק פָּתַח, (אסתרה) וַיְהִי בַּיּוֹם הַשְּׁלִישִׁי וַתִּלְבַּשׁ אֶסְתֵּר מַלְכוּת וְגוֹ'. מְגִלַּת אֶסְתֵּר בְּרוּחַ הַקֹּדֶשׁ נֶאֶמְרָה, וּמִשּׁוּם זֶה כְּתוּבָה בֵּין הַכְּתוּבִים. וַיְהִי בַּיּוֹם הַשְּׁלִישִׁי, שֶׁנֶּחֱלָשׁ כֹּחַ הַגּוּף, וַהֲרֵי קַיָּם בָּרוּחַ בְּלֹא גוּף, אָז - וַתִּלְבַּשׁ אֶסְתֵּר מַלְכוּת. אֵיזוֹ מַלְכוּת? אִם תֹּאמַר בִּלְבוּשׁ כָּבוֹד וְאַרְגָּמָן, הֲרֵי לֹא כָּךְ נִקְרָא. אֶלָּא וַתִּלְבַּשׁ אֶסְתֵּר מַלְכוּת, שֶׁהִתְלַבְּשָׁה בְמַלְכוּת עֶלְיוֹנָה קְדוֹשָׁה, וַדַּאי לָבְשָׁה רוּחַ הַקֹּדֶשׁ. מָה הַטַּעַם זָכְתָה לְמָקוֹם זֶה? מִשּׁוּם שֶׁשָּׁמְרָה פִיהָ שֶׁלֹּא לְהַרְאוֹת דָּבָר. זֶהוּ שֶׁכָּתוּב (אסתר ב) אֵין אֶסְתֵּר מַגֶּדֶת מוֹלַדְתָּהּ. וְלָמַדְנוּ, כָּל מִי שֶׁשּׁוֹמֵר פִּיו וּלְשׁוֹנוֹ, זוֹכֶה לְהִתְלַבֵּשׁ בְּרוּחַ הַקֹּדֶשׁ. וְכָל מִי שֶׁסּוֹטֶה פִיו לְדָבָר רָע, הֲרֵי וַדַּאי אתוֹ דָּבָר רָע עָלָיו. (ואם לא,) הֲרֵי נְגָעִים אוֹ צָרַעַת שֶׁשּׂוֹרְפִים כְּנָחָשׁ עָלָיו, וַהֲרֵי פֵּרְשׁוּהוּ.</p>\n<p>וַיְדַבֵּר הָעָם בֵּאלֹהִים וּבְמֹשֶׁה, שֶׁאָמְרוּ דָבָר רָע בַּקָּדוֹשׁ-בָּרוּךְ- הוּא, וּכְתַרְגּוּמוֹ - וְעִם מֹשֶׁה נְצוּ. לָמָּה הֶעֱלִיתֻנוּ, שָׂמוּ כָּל הַפָּנִים שָׁווֹת, בִּגְלַל זֶה הִזְדַּמְּנוּ לָהֶם נְחָשִׁים, שֶׁשּׂוֹרְפִים אוֹתָם כָּאֵשׁ וּמַכְנִיסִים אֵשׁ לִמְעֵיהֶם וְנוֹפְלִים מֵתִים, כְּמוֹ שֶׁנֶּאֱמַר וַיְשַׁלַּח ה' בָּעָם אֵת הַנְּחָשִׁים הַשְּׂרָפִים.</p>\n<p>רַבִּי חִיָּיא אָמַר, נְחָשִׁים הָיוּ בָאִים, מְלַחֲשִׁים בְּפִיהֶם, וְנוֹשְׁכִים וּמֵתִים. מַה מְלַחֲשִׁים? כְּמוֹ שֶׁנֶּאֱמַר (קהלת י) אִם יִשֹּׁךְ הַנָּחָשׁ בְּלוֹא לָחַשׁ. אֵשׁ הָיוּ מְלַהֲטִים בְּפִיהֶם, וְנוֹשְׁכִים וְזוֹרְקִים בָּהֶם אֵשׁ, וּמְעֵיהֶם יוֹקְדִים וּמֵתִים. וַהֲרֵי דְּבָרִים אֵלּוּ עָלוּ לְמָקוֹם אַחֵר.</p>"],[9522012395,"<p>וּמִשָּׁם בְּאֵרָה הִוא הַבְּאֵר. מַה שּׁוֹנֶה שֶׁכָּאן בְּאֵרָה וְאַחַר כָּךְ בְּאֵר? אֶלָּא בְּאֵרָה, לְאַחַר שֶׁמִּתְכַּנְּסִים הַמַּיִם לְתוֹךְ הַיָּם וְיוֹרְדִים לְמַטָּה. בְּאֵר, בְּשָׁעָה שֶׁיִּצְחָק מְמַלֵּא אוֹתָם. הִוא הַבְּאֵר, הוּא כָּתוּב, וְסוֹד זֶה כְּמוֹ שֶׁכָּתוּב (במדבר יח) וְעָבַד הַלֵּוִי הוּא.</p>\n<p>רַבִּי אַבָּא אָמַר, בְּכָל מָקוֹם הוּא, וְקוֹרְאִים הִיא - זָכָר וּנְקֵבָה כְּאֶחָד. וּכְלָל עֶלְיוֹן - ה' נְקֵבָה, ו' זָכָר, א' כְּלַל הַכֹּל, שֶׁהֲרֵי א' בִּשְׁלֵמוּת שׁוֹרָה. אַשְׁרֵיהֶם יִשְׂרָאֵל. אַף עַל גַּב שֶׁהֵם לְמַטָּה, הֵם אֲחוּזִים בַּכְּלָל הָעֶלְיוֹן שֶׁל הַכֹּל, וּמִשּׁוּם זֶה כָּתוּב (תהלים ק) הוּא עָשָׂנוּ וְלֹא אֲנַחְנוּ, בְּאָלֶף כָּתוּב. כְּלַל שֶׁל ו\"ה, וְא' שֶׁכּוֹלֵל הַכֹּל.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, רוּחַ הַמַּיִם זוֹהִי רוּחַ הַקֹּדֶשׁ שֶׁנָּשְׁבָה בַּהַתְחָלָה, כְּמוֹ שֶׁנֶּאֱמַר (שיר השירים ד) הָפִיחִי גַנִּי. אַחַר כָּךְ נוֹזְלִים מַיִם לְמַלֵּא אוֹתָהּ (כלה), זֶהוּ שֶׁכָּתוּב (תהלים קמז) יַשֵּׁב רוּחוֹ יִזְּלוּ מָיִם. יַשֵּׁב רוּחוֹ בַּהַתְחָלָה, וְאַחַר כָּךְ יִזְּלוּ מָיִם. וְעַד שֶׁלֹּא נוֹשֶׁבֶת רוּחַ זוֹ, לֹא נוֹזְלִים מַיִם. מַה בָּא לְהַשְׁמִיעֵנוּ? מַשְׁמִיעַ שֶׁצָּרִיךְ בַּכֹּל לְעוֹרֵר הַדָּבָר, בְּמַעֲשֶׂה אוֹ בְדָבָר, אוֹ לְהַרְאוֹת כְּמַרְאֵה הַמַּעֲשֶׂה. וְכָאן, עַד שֶׁרוּחַ לֹא נוֹשֶׁבֶת, לֹא נוֹזְלִים אֵלֶיהָ מַיִם לְגַבֵּי אוֹתָהּ הָרוּחַ.</p>\n<p>הוּא הַבְּאֵר, קוֹרְאִים הִיא הַבְּאֵר. מַה שּׁוֹנֶה שֶׁבַּהַתְחָלָה בְּאֵרָה וְכָאן בְּאֵר? אֶלָּא בַּהַתְחָלָה נְקֵבָה לְבַדָּהּ, וְכָעֵת שֶׁאָמַר הוּא - כְּלָל שֶׁל זָכָר וּנְקֵבָה - נִקְרָא בְּאֵר. וּבְמָקוֹם שֶׁנִּמְצָא זָכָר, אֲפִלּוּ (מאה) מִלָּה נְקֵבָה, נִקְרָא זָכָר לַכֹּל.</p>\n<p>אֲשֶׁר אָמַר ה' לְמֹשֶׁה אֱסֹף אֶת הָעָם, מִשּׁוּם שֶׁבְּאֵר זוֹ לֹא זָזָה (באר) מֵהֶם. וְאִם תֹּאמַר, אֵיךְ יָכְלוּ לִשְׁאֹב מִמֶּנָּה כֻּלָּם? אֶלָּא הוּא מוֹצִיא לִשְׁלֹשָׁה עָשָׂר נְחָלִים, וְהַמַּעְיָן מִתְמַלֵּא וְיוֹצֵא לְכָל הַצְּדָדִים, וְאָז הָיוּ יִשְׂרָאֵל בְּשָׁעָה שֶׁחוֹנִים וְרוֹצִים מַיִם, עוֹמְדִים עָלֶיהָ וְאוֹמְרִים שִׁירָה. וּמָה אוֹמְרִים? עֲלִי בְאֵר. הַעֲלִי מֵימַיִךְ לְהוֹצִיא מַיִם לַכֹּל וְלִהְיוֹת מֻשְׁקִים מִמֵּךְ. וְכֵן אוֹמְרִים שֶׁבַח שֶׁל בְּאֵר זֹּאת, בְּאֵר חֲפָרוּהָ שָׂרִים וְגוֹ'. דְּבַר אֱמֶת הָיוּ אוֹמְרִים, וְכָךְ הוּא.</p>\n<p>מִכָּאן לָמַדְנוּ (בא ראה), כָּל מִי שֶׁרוֹצֶה לְעוֹרֵר דְּבָרִים שֶׁל מַעְלָה, בֵּין בְּמַעֲשֶׂה בֵּין בְּדִבּוּר - אִם אוֹתוֹ מַעֲשֶׂה אוֹ אוֹתוֹ דִּבּוּר לֹא נַעֲשֶׂה כָּרָאוּי, לֹא מְעוֹרֵר דָּבָר. כָּל בְּנֵי הָעוֹלָם הוֹלְכִים לְעוֹרֵר בְּבֵית הַכְּנֶסֶת דָּבָר שֶׁלְּמַעְלָה, אֲבָל מְעַטִּים אֵלּוּ שֶׁיּוֹדְעִים לְעוֹרֵר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא קָרוֹב לְכָל הַיּוֹדְעִים לִקְרֹא לוֹ וּלְעוֹרֵר הַדָּבָר כָּרָאוּי. אֲבָל אִם לֹא יוֹדְעִים לִקְרֹא לוֹ, הוּא אֵינוֹ קָרוֹב, שֶׁכָּתוּב (שם קמה) קָרוֹב ה' לְכָל קֹרְאָיו וְגוֹ'. מַה זֶּה בֶּאֱמֶת? שֶׁיּוֹדְעִים לְעוֹרֵר דְּבַר אֱמֶת כָּרָאוּי, וְכֵן בַּכֹּל.</p>\n<p>גַּם כָּאן הָיוּ יִשְׂרָאֵל אוֹמְרִים דִּבּוּרִים אֵלֶּה, דִּבְרֵי אֱמֶת, כְּדֵי לְעוֹרֵר בְּאֵר הַזֹּאת וּלְהַשְׁקוֹתָם לְיִשְׂרָאֵל, וְעַד שֶׁאוֹמְרִים מִלִּים אֵלּוּ, לֹא מִתְעוֹרֶרֶת. וְכֵן אֲפִלּוּ בְּאוֹתָם מְכַשְּׁפֵי הָעוֹלָם שֶׁמִּשְׁתַּמְּשִׁים בְּמִינִים רָעִים, עַד שֶׁעוֹשִׂים מַעֲשֵׂיהֶם שֶׁל אֱמֶת אֲלֵיהֶם - אִם לֹא אוֹמְרִים דִּבְרֵי אֱמֶת בִּשְׁבִיל לְהַמְשִׁיךְ אוֹתָם בִּגְוָנִים אֵלּוּ שֶׁרוֹצִים, לֹא מִתְעוֹרְרִים לְגַבֵּיהֶם. וַאֲפִלּוּ שֶׁצּוֹוְחִים כָּל הַיּוֹם בִּדְבָרִים אֲחֵרִים אוֹ בְּמַעֲשֶׂה אַחֵר, לֹא מוֹשְׁכִים אוֹתָם אֲלֵיהֶם לְעוֹלָמִים וְלֹא מִתְעוֹרְרִים אֲלֵיהֶם.</p>\n<p>בֹּא וּרְאֵה, כָּתוּב (מלכים א יח) וַיִּקְרְאוּ בְשֵׁם הַבַּעַל וְגוֹ'. מָה הַטַּעַם? אֶחָד, שֶׁאֵין רְשׁוּת בְּאוֹתוֹ בַּעַל בָּזֶה. וְעוֹד, שֶׁהַדְּבָרִים לֹא מֻכְשָׁרִים בֵּינֵיהֶם, וְהִשְׁכִּיחָם הַקָּדוֹשׁ בָּרוּךְ הוּא מֵהֶם. זֶהוּ שֶׁכָּתוּב (שם) וְאַתָּה הֲסִבּתָ אֶת לִבָּם אֲחֹרַנִּית. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁיּוֹדְעִים לִקְרֹא לְרִבּוֹנָם כָּרָאוּי.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כָּאן צָרִיךְ לְגַלּוֹת דָּבָר. בֹּא וּרְאֵה, כָּל מִי שֶׁיּוֹדֵעַ לְסַדֵּר מַעֲשֶׂה כָּרָאוּי וּלְסַדֵּר דְּבָרִים כָּרָאוּי, זֶה בְּוַדַּאי מְעוֹרֵר אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַמְשִׁיךְ דְּבָרִים עֶלְיוֹנִים שֶׁמֻּכְשָׁרִים. (ואם לא, לא יכשר להם). וְלֹא הֻכְשַׁר לָהֶם. אִם כָּךְ, כָּל הָעוֹלָם יוֹדְעִים לְסַדֵּר מַעֲשֶׂה וּלְסַדֵּר דְּבָרִים, מַה חֲשִׁיבוּת הַצַּדִּיקִים שֶׁיּוֹדְעִים עִקַּר הַדָּבָר וְהַמַּעֲשֶׂה, וְיוֹדְעִים לְכַוֵּן לֵב וְרָצוֹן יוֹתֵר מֵאֵלּוּ הָאֲחֵרִים שֶׁלֹּא יוֹדְעִים כָּל כָּךְ?</p>\n<p>אֶלָּא אֵלֶּה שֶׁלֹּא יוֹדְעִים עִקַּר הַמַּעֲשֶׂה כָּל זֶה, אֶלָּא סִדּוּר בְּעָלְמָא וְלֹא יוֹתֵר, מוֹשְׁכִים עֲלֵיהֶם מְשִׁיכוּת שֶׁאַחַר כִּתְפֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא טָס בָּאֲוִיר, שֶׁהַשְׁגָּחָה נִקְרָא.</p>\n<p>וְאֵלֶּה שֶׁיּוֹדְעִים וּמְכַוְּנִים לֵב וְרָצוֹן, מוֹצִיאִים בְּרָכוֹת מִמְּקוֹם הַמַּחֲשָׁבָה, וְיוֹצְאִים בְּכָל הַגְּזָעִים וְהַשָּׁרָשִׁים בְּדֶרֶךְ יָשָׁר כָּרָאוּי, עַד שֶׁמִּתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים, וְשֵׁם הַקָּדוֹשׁ מִתְבָּרֵךְ עַל יָדָם. אַשְׁרֵי חֶלְקָם, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא קָרוֹב אֲלֵיהֶם וּמְזֻמָּן כְּנֶגְדָּם. בְּשָׁעָה שֶׁקּוֹרְאִים לוֹ הוּא מְזֻמָּן אֲלֵיהֶם. בְּשָׁעָה שֶׁהֵם בְּצָרָה הוּא אֶצְלָם. הוּא מְכַבֵּד אוֹתָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. זֶהוּ שֶׁכָּתוּב (תהלים צא) כִּי בִי חָשַׁק וַאֲפַלְּטֵהוּ אֲשַׂגְּבֵהוּ כִּי יָדַע שְׁמִי.</p>"],[9522012396,"<p>וַיֹּאמֶר ה' אֶל מֹשֶׁה אַל תִּירָא אֹתוֹ וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (משלי לא) לֹא תִירָא לְבֵיתָהּ מִשָּׁלֶג כִּי כָל בֵּיתָהּ לָבֻשׁ שָׁנִים. בֹּא וּרְאֵה, כְּנֶסֶת יִשְׂרָאֵל יוֹנֶקֶת מִשְּׁנֵי צְדָדִים, כָּעֵת בְּרַחֲמִים, כָּעֵת בְּדִין. כְּשֶׁרוֹצָה לִינֹק בְּרַחֲמִים, נִמְצָא מָקוֹם לְהִתְיַשֵּׁב בּוֹ. כְּשֶׁרוֹצֶה לִינֹק בְּדִין, מָקוֹם נִמְצָא לְהִתְיַשֵּׁב בּוֹ וְלִשְׁרוֹת עָלָיו, שֶׁכָּךְ הוּא בְּכָל מָקוֹם - לֹא שׁוֹרֶה דָבָר שֶׁלְּמַעְלָה עַד שֶׁנִּמְצָא מָקוֹם לִשְׁרוֹת עָלָיו. וְעַל כָּךְ כְּנֶסֶת יִשְׂרָאֵל לֹא תִירָא לְבֵיתָהּ מִשָּׁלֶג, מָה הַטַּעַם? מִשּׁוּם שֶׁכָּל בֵּיתָהּ לָבֻשׁ שָׁנִים, לֹא שׁוֹרֶה זֶה אֶלָּא בָּזֶה, לָבָן בְּאָדם וְאָדם בְּלָבָן, וַהֲרֵי פֵּרְשׁוּהָ. (בא ראה, כתוב)</p>\n<p>וַיֹּאמֶר ה' אֶל מֹשֶׁה אַל תִּירָא אֹתוֹ (אותו). שְׁנֵי אוֹתוֹ הֵם שְׁלֵמִים בַּתּוֹרָה בִּשְׁנֵי וָוִי\"ם, אֶחָד זֶה, וְאֶחָד - (דברים כב) עַד דְּרֹשׁ אָחִיךְ אֹתוֹ (אותו). מָה הַטַּעַם? מִשּׁוּם שֶׁהֵם אוֹת מַמָּשׁ. עַד דְּרשׁ אָחִיךְ (אחיך ממש) אֹתוֹ (אותו), שֶׁצָּרִיךְ לְפָרֵשׁ אֶת אוֹתוֹ הָאוֹת שֶׁל אוֹתָהּ אֲבֵדָה.</p>\n<p>גַּם כָּךְ אוֹתוֹ הַזֶּה, זֶה עוֹג שֶׁנִּדְבַּק בְאַבְרָהָם, וּמֵאַנְשֵׁי בֵיתוֹ הָיָה, וּכְשֶׁנִּמּוֹל אַבְרָהָם מַה כָּתוּב? (בראשית יז) וְכָל אַנְשֵׁי בֵיתוֹ וְגוֹ'. זֶה עוֹג שֶׁנִּמּוֹל עִמּוֹ וְקִבֵּל אוֹת הַקָּדוֹשׁ הַזֶּה. כֵּיוָן שֶׁרָאָה עוֹג שֶׁיִּשְׂרָאֵל מִתְקָרְבִים אֵלָיו, אָמַר: הֲרֵי וַדַּאי אֲנִי הִקְדַּמְתִּי זְכוּת שֶׁעוֹמֶדֶת לָהֶם, וְזֶה שָׂם לְמוּלוֹ.</p>\n<p>בְּאוֹתָהּ שָׁעָה פָּחַד מֹשֶׁה, אֵיךְ יָכוֹל לַעֲקֹר רשֶׁם שֶׁרָשַׁם אַבְרָהָם? אָמַר, בְּוַדַּאי הַיָּמִין שֶׁלִּי מֵת, שֶׁהֲרֵי הַיָּמִין צָרִיךְ לָזֶה. אִם נֹאמַר הֲרֵי אֶלְעָזָר - יְמִין הַלְּבָנָה הוּא וְלֹא יְמִינִי. וְהָאוֹת הַזֶּה לְיָמִין הוּא, שֶׁאַבְרָהָם הוּא לְיָמִין.</p>\n<p>מִיָּד אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אַל תִּירָא אֹתוֹ. אַל תִּירָא אֶת אוֹתוֹ הָאוֹת שֶׁלּוֹ, וַאֲפִלּוּ לַיָּמִין לֹא צָרִיךְ. כִּי בְיָדְךְ נָתַתִּי. שְׂמֹאלְךְ תַּעֲקֹר אוֹתוֹ מֵהָעוֹלָם, שֶׁהֲרֵי הוּא פָּגַם הָרֹשֶׁם שֶׁלּוֹ, וּמִי שֶׁפּוֹגֵם אוֹת זוֹ רָאוּי לְהֵעָקֵר מֵהָעוֹלָם, כָּל שֶׁכֵּן שְׂמֹאל שֶׁלְּךְ, שֶׁהִיא יָדְךְ, יַעֲקֹר אוֹתוֹ מֵהָעוֹלָם, בִּגְלַל זֶה נֶעֱקַר מֵהָעוֹלָם. וַאֲפִלּוּ שֶׁהוּא תַּקִּיף מִבְּנֵי הַגִּבּוֹרִים וְרָצָה לְהַשְׁמִיד אֶת יִשְׂרָאֵל, נָפַל בִּידֵי מֹשֶׁה וְהֻשְׁמַד.</p>\n<p>בִּגְלַל זֶה הַכֹּל הִשְׁמִידוּ יִשְׂרָאֵל, בָּנָיו וְכָל עַמּוֹ וְכָל אֲשֶׁר לוֹ, כְּמוֹ שֶׁכָּתוּב וַיַּכּוּ אֹתוֹ וְאֶת בָּנָיו וְאֶת כָּל עַמּוֹ, וְכָתוּב (דברים ב) וַנַּךְ אֹתוֹ וְאֶת בָּנָו. בְּנוֹ כָּתוּב, חָסֵר יוֹ\"ד, וְקוֹרְאִים בָּנָיו, וַהֲרֵי פֵּרְשׁוּהוּ הַחֲבֵרִים.</p>\n<p>אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁמֹּשֶׁה הַנָּבִיא הָיָה בֵּינֵיהֶם, שֶׁבִּגְלָלוֹ עָשָׂה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא כָּל הָאוֹתוֹ הַלָּלוּ, וּפֵרְשׁוּהָ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא גָזַר בְּרִיתוֹ עִם שְׁאָר הָעַמִּים לְהִתְקַשֵּׁר בּוֹ, אֶלָּא עִם יִשְׂרָאֵל, שֶׁהֵם בְּנֵי אַבְרָהָם, שֶׁכָּתוּב בּוֹ (בראשית יז) וּבֵין זַרְעֲךְ אַחֲרֶיךְ לְדרֹתָם לִבְרִית עוֹלָם. וְכָתוּב (ישעיה נט) וַאֲנִי זֹּאת בְּרִיתִי אוֹתָם אָמַר ה' רוּחִי אֲשֶׁר עָלֶיךְ וְגוֹ', לֹא יָמוּשׁוּ מִפִּיךְ וְגוֹ'. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522012397,"<p>וַיַּרְא בָּלָק בֶּן צִפּוֹר וְגוֹ'. רַבִּי שִׁמְעוֹן אָמַר, וַיַּרְא, אֵיזוֹ רְאִיָּה רָאָה? וַדַּאי רְאִיָּה מַמָּשׁ רָאָה בְּמַשְׁקוֹף הַחָכְמָה, וְרָאָה בְעֵינָיו. רָאָה בְּמַשְׁקוֹף הַחָכְמָה, כְּמוֹ שֶׁכָּתוּב (בראשיתכו) וַיַּשְׁקֵף אֲבִימֶלֶךְ מֶלֶךְ פְּלִשְׁתִּים בְּעַד הַחַלּוֹן. מַה זֶּה בְּעַד הַחַלּוֹן? כְּמוֹ שֶׁנֶּאֱמַר (שופטים ה) בְּעַד הַחַלּוֹן נִשְׁקְפָה וַתְּיַבֵּב אֵם סִיסְרָא. (אלא) (ודאי) חַלּוֹן הַחָכְמָה שֶׁל זַנְבוֹת שׁוּלֵי הַכּוֹכָבִים, וְהֵם חַלּוֹנֵי הַחָכְמָה. וְיֵשׁ חַלּוֹן אֶחָד שֶׁכָּל הַחָכְמָה שׁוֹרָה בּוֹ, וּבוֹ רוֹאֶה מִי שֶׁרוֹאֶה בְּעִקַּר הַחָכְמָה. אַף כָּאן וַיַּרְא בָּלָק, בְּחָכְמָתוֹ.</p>\n<p>בֶּן צִפּוֹר, כְּמוֹ שֶׁאָמְרוּ. אֲבָל בֶּן צִפּוֹר מַמָּשׁ, שֶׁהֲרֵי כְּשָׁפָיו הָיוּ בְכַמָּה מִינִים שֶׁל אוֹתָהּ צִפּוֹר. לוֹקֵחַ צִפּוֹר, מְכַשְׁכֵּשׁ בְּעֵשֶׂב, מַפְרִיחַ בָּאֲוִיר, עוֹשֶׂה מַעֲשִׂים וְלוֹחֵשׁ לְחָשִׁים, וְאוֹתָהּ צִפּוֹר הָיְתָה בָּאָה וְאוֹתוֹ עֵשֶׂב בְּפִיהָ, (פורחת באויר) מְצַפְצֶפֶת לְפָנָיו. וּמַכְנִיסָהּ בִּכְלוּב אֶחָד. מְקַטֵּר קְטֹרֶת לְפָנֶיהָ, וּמוֹדִיעָה לוֹ כַּמָּה דְבָרִים. עוֹשֶׂה כְשָׁפָיו, וְהָעוֹף מְצַפְצֵף, פּוֹרֵחַ וְטָס אֵצֶל גְּלוּי עֵינַיִם וּמוֹדִיעַ לוֹ, וְהוּא בָּא. וְכָל דְּבָרָיו בְּאוֹתָהּ צִפּוֹר הָיוּ.</p>\n<p>יוֹם אֶחָד עָשָׂה מַעֲשָׂיו, וְלָקַח אוֹתָהּ צִפּוֹר, וּפָרְחָה וְהָלְכָה וְהִתְעַכְּבָה וְלֹא בָאָה. הָיָה מִצְטַעֵר בְּנַפְשׁוֹ. עַד שֶׁהִגִּיעָה, רָאָה שַׁלְהֶבֶת אֵשׁ אַחַת טָסָה אַחֲרֶיהָ וְשׂוֹרֶפֶת כְּנָפֶיהָ. אָז רָאָה מַה שֶּׁרָאָה, וּפָחַד מִלִּפְנֵי יִשְׂרָאֵל. מַה שְּׁמָהּ שֶׁל אוֹתָהּ צִפּוֹר? יָדוּ\"עַ. וְכָל אֵלּוּ שֶׁמְּשַׁמְּשִׁים וְיוֹדְעִים לְהִשְׁתַּמֵּשׁ בַּצִּפּוֹר הַזּוֹ, לֹא יוֹדְעִים כְּשָׁפֶיהָ כְּמוֹ שֶׁבָּלָק יָדַע.</p>\n<p>וְכָל הַחָכְמָה שֶׁיָּדַע, בְּאוֹתָהּ צִפּוֹר הָיָה יוֹדֵעַ. וְכָךְ הָיָה עוֹשֶׂה: גּוֹחֵן לְפָנֶיהָ וּמְקַטֵּר קְטֹרֶת, מְכַסֶּה רֹאשׁוֹ וְגוֹחֵן וְאוֹמֵר. הוּא אוֹמֵר הָעָם, וְהַצִּפּוֹר מְשִׁיבָה יִשְׂרָאֵל. הוּא אוֹמֵר מְאֹד, וְהַצִּפּוֹר מְשִׁיבָה רַב, עַל שׁוּם הַגָּדוֹל הָעֶלְיוֹן שֶׁהוֹלֵךְ אִתָּם. שִׁבְעִים פְּעָמִים צִפְצְפוּ זֶה וָזֶה. הוּא אָמַר דַּל, וְהַצִּפּוֹר אוֹמֶרֶת גָּדוֹל. וְאָז פָּחַד, שֶׁכָּתוּב וַיָּגָר מוֹאָב מִפְּנֵי הָעָם מְאֹד כִּי רַב הוּא. רַב הוּא בְּוַדַּאי.</p>\n<p>וּבְמִינֵי הַכְּשָׁפִים (של קסריא\"ל) שֶׁל קַסְדִּיאֵ\"ל (נ\"א כשדיא\"ל) הָרִאשׁוֹן מָצָאנוּ, שֶׁצִפּוֹר זוֹ הָיוּ עוֹשִׂים לוֹ בִּזְמַנִּים יְדוּעִים מִכֶּסֶף מְעֹרָב בְּזָהָב. רֹאשׁ מִזָּהָב, פֶּה מִכֶּסֶף, כְּנָפַיִם מִנְּחֹשֶׁת קָלָל מְעֹרֶבֶת בְּכֶסֶף, גּוּף מִזָּהָב, נְקֻדּוֹת שֶׁל הַנּוֹצוֹת בְּכֶסֶף, רַגְלַיִם מִזָּהָב. וְשָׂמִים בַּפֶּה לָשׁוֹן שֶׁל אוֹתָהּ צִפּוֹר יָדוּ\"עַ.</p>\n<p>וְשָׂמִים אוֹתָהּ צִפּוֹר בְּחַלּוֹן אֶחָד, וּפוֹתְחִים חַלּוֹנוֹת מוּל הַשֶּׁמֶשׁ, וּבַלַּיְלָה פּוֹתְחִים חַלּוֹנוֹת לַלְּבָנָה, מְקַטְּרִים קְטֹרֶת וְעוֹשִׂים כְּשָׁפִים, וּמַשְׁבִּיעִים אֶת הַשֶּׁמֶשׁ, וּבַלַּיְלָה מַשְׁבִּיעִים אֶת הַלְּבָנָה, וְאֶת זֶה עוֹשִׂים שִׁבְעָה יָמִים. מִכָּאן וָהָלְאָה אוֹתָהּ לָשׁוֹן מְכַשְׁכֶּשֶׁת בַּפֶּה שֶׁל אוֹתָהּ צִפּוֹר, נוֹקְדִים אוֹתָהּ לָשׁוֹן בְּמַחַט זָהָב וְהִיא מְדַבֶּרֶת גְּדוֹלוֹת מֵעַצְמָהּ, וְהַכֹּל הָיָה יוֹדֵעַ בָּלָק מִצִּפּוֹר זוֹ (ודאי). לָכֵן בֶּן צִפּוֹר, וּמִשּׁוּם זֶה רָאָה מַה שֶּׁאִישׁ אַחֵר לֹא יָכוֹל לָדַעַת וְלֹא יָכוֹל לִרְאוֹת.</p>"],[9522012398,"<p>כָּתוּב (תהלים סח) אָמַר ה' מִבָּשָׁן אָשִׁיב אָשִׁיב מִמְּצֻלוֹת יָם. יֵשׁ לָנוּ לָשִׂים לֵב לֶאֱמוּנַת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּל דְּבָרָיו דִּבְרֵי אֱמֶת וֶאֱמוּנָּה רַבָּה. שֶׁכֵּיוָן שֶׁאוֹמֵר דָּבָר, הַכֹּל נַעֲשֶׂה. וְזֶה הָאִישׁ דּוֹחֵק הַלֵּב, וְאוֹמֵר: לְכַמָּה שָׁנִים וּלְכַמָּה זְמַנִּים יִשְׁתַּלֵּם זֶה, שֶׁהוּא כָּךְ. כְּפִי גְדֻלָּתוֹ, שֶׁכָּל הָעוֹלָמוֹת מְלֵאִים כְּבוֹדוֹ, כָּךְ זֶה. דְּבָרָיו אָדָם קָטָן, וְכָל דְּבָרָיו הֵם לְפִי שָׁעָה, כָּךְ הוּא לְפִי שָׁעָה. אֲבָל בִּתְשׁוּבָה וּבְבַקָּשָׁה וּמַעֲשִׂים טוֹבִים וּבִדְמָעוֹת רַבּוֹת, הוּא קָדוֹשׁ גָּדוֹל וְעֶלְיוֹן עַל כָּל הָעוֹלָם, מַזְהִיר אוֹרוֹ, וּמְקַמֵּט קְדֻשָּׁתוֹ לָאָדָם לַעֲשׂוֹת רְצוֹנוֹ.</p>\n<p>אָמַר ה'. לֶעָתִיד לָבא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְעוֹרֵר וּלְהָשִׁיב מִבָּשָׁן כָּל אוֹתָם שֶׁהֲרָגוּם חַיּוֹת הַשָּׂדֶה וְאָכְלוּ אוֹתָם. מִשּׁוּם שֶׁיֵּשׁ בָּעוֹלָם (אף כאן מלך הבשן) מְקוֹם מוֹשָׁב שֶׁל כָּל חַיּוֹת גְּדוֹלוֹת וְהָרִים רָמִים וּגְדוֹלִים וְנִסְתָּרִים אֵלּוּ בְאֵלּוּ, וַעֲרֹד הַמִּדְבָּר הַתַּקִּיף שָׁם, הוּא עוֹג, (בין) עֲרוֹדֵי הַמִּדְבָּר הָיָה, וּמָצוּי שָׁם כֹּחוֹ, מִשּׁוּם שֶׁהָיָה מֶלֶךְ הַבָּשָׁן, שֶׁכָּל מַלְכֵי הָעוֹלָם לֹא יָכְלוּ לַעֲרֹךְ נֶגְדּוֹ קְרָב בִּגְלַל חֹזֶק הַבָּשָׁן, וּבָא מֹשֶׁה וְעָרַךְ נֶגְדּוֹ קְרָב.</p>\n<p>סִיחוֹן - סְיָח בַּמִּדְבָּר הָיָה סִיחוֹן, וּבִטְחוֹן מוֹאָב הָיָה עָלָיו, (במדבר כא) כִּי אַרְנוֹן גְּבוּל מוֹאָב בֵּין מוֹאָב וּבֵין הָאֱמֹרִי. בּא וּרְאֵה, בְּשָׁעָה שֶׁהֶחֱרִיבוּ יִשְׂרָאֵל עִיר סִיחוֹן, הָעֳבַר כְּרוּז בְּמַלְכוּת הַשָּׁמַיִם: הִתְכַּנְּסוּ גְבָרִים שֶׁשּׁוֹלְטִים עַל שְׁאָר עַמִּים, וְתִרְאוּ אֵיךְ מַלְכוּת הָאֱמֹרִי תֵּחָרֵב בַּמַּלְכוּת.</p>\n<p>בְּאוֹתָהּ שָׁעָה כָּל אוֹתָם שַׁלִּיטִים שֶׁהָיוּ מְמֻנִּים עַל שִׁבְעָה עֲמָמִים הִתְכַּנְּסוּ, וְרָצוּ לְהַחֲזִיר מַלְכוּת לְיָשְׁנָהּ. כֵּיוָן שֶׁרָאוּ עָצְמַת מֹשֶׁה, חָזְרוּ לְאָחוֹר. זֶהוּ שֶׁכָּתוּב (שם) עַל כֵּן יֹאמְרוּ הַמֹּשְׁלִים בֹּאוּ חֶשְׁבּוֹן. אוֹתָם שַׁלִּיטִים הַמְמֻנִּים עֲלֵיהֶם שֶׁהִתְכַּנְּסוּ וְאָמְרוּ בֹּאוּ חֶשְׁבּוֹן, מִי הוּא זֶה שֶׁהֶחֱרִיבָהּ? תִּבָּנֶה וְתִכּוֹנֵן כְּבַתְּחִלָּה, וְתַחֲזֹּר מַלְכוּת לְיָשְׁנָהּ.</p>\n<p>כְּשֶׁרָאוּ גְבוּרַת מֹשֶׁה וְשַׁלְהֶבֶת הַמַּלְכוּת, אָמְרוּ, כִּי אֵשׁ יָצְאָה מֵחֶשְׁבּוֹן לֶהָבָה מִקִּרְיַת סִיחֹן. כֵּיוָן שֶׁכָּתוּב מֵחֶשְׁבּוֹן, לָמָּה מִקִּרְיַת סִיחֹן, שֶׁהֲרֵי קִרְיַת סִיחֹן הָיְתָה חֶשְׁבּוֹן, שֶׁכָּתוּב כִּי חֶשְׁבּוֹן עִיר סִיחֹן מֶלֶךְ הָאֱמֹרִי?</p>\n<p>אֶלָּא, שַׁלְהֶבֶת שֶׁל מַלְכוּת הַשָּׁמַיִם יָצְאָה וְהֶחֱרִיבָה הַכֹּל. בְּשָׁעָה שֶׁאָמְרוּ תִּבָּנֶה וְתִכּוֹנֵן עִיר סִיחוֹן סְתָם, וְלֹא אָמְרוּ חֶשְׁבּוֹן, שֶׁחָשְׁבוּ שֶׁבִּגְלַל זֶה תִּבָּנֶה לְמוֹשֶׁבֶת הָאֱמֹרִי, אָז הֵשִׁיבוּ וְאָמְרוּ לֹא יְכוֹלִים. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּל הַדְּרָכִים וְהַשְּׁבִילִים נִסְתְּמוּ בְּעָצְמַת הַגָּדוֹל הָעֶלְיוֹן שֶׁלָּהֶם. אִם נַחֲזֹר וְנֹאמַר וְנִזְכֹּר חֶשְׁבּוֹן שֶׁתִּבָּנֶה, הֲרֵי אֵשׁ יָצְאָה מֵחֶשְׁבּוֹן. אִם נַחֲזֹּר וְנֹאמַר (סתם) קִרְיַת סִיחֹן, הֲרֵי לֶהָבָה יָצְאָה מִקִּרְיַת סִיחֹן וַדַּאי. כֵּיוָן שֶׁאוֹתָהּ שַׁלְהֶבֶת אֵשׁ שָׁרְתָה שָׁם עָלֶיהָ, אֵין מִי שֶׁיָּכוֹל לָהּ לְהַחֲזִירָהּ מִיָּשְׁנָהּ, שֶׁהֲרֵי מִכָּל הַצְּדָדִים אֵין לָנוּ רְשׁוּת.</p>\n<p>מִכָּאן וָהָלְאָה - אוֹי לְךְ מוֹאָב, שֶׁהֲרֵי אוֹתוֹ שֶׁהֵגֵן עָלֶיךְ נִשְׁבַּר. וּמִשּׁוּם זֶה, כֵּיוָן שֶׁרָאָה מוֹאָב שֶׁמְּגִנּוֹ נִשְׁבַּר, אָז וַיָּגָר מוֹאָב מִפְּנֵי הָעָם מְאֹד. מַה זֶּה מְאֹד? יוֹתֵר מֵהַמָּוֶת.</p>\n<p>כִּי רַב הוּא. שֶׁהֲרֵי אָז הוּא הָיָה גָּדוֹל, וְגָדוֹל הָיָה קָטָן, שֶׁכָּתוּב (עובדיה א) הִנֵּה קָטֹן נְתַתִּיךְ בַּגּוֹיִם. וְיִשְׂרָאֵל הָיָה גָּדוֹל בַּמָּקוֹם שֶׁל עֵשָׂו, שֶׁכָּתוּב בּוֹ וְרַב. מָה הַטַּעַם? מִשּׁוּם שֶׁרָאוּ שֶׁשָּׁלְטוּ יִשְׂרָאֵל לְמַעְלָה וּלְמַטָּה, שֶׁכָּתוּב אֵת כָּל אֲשֶׁר עָשָׂה יִשְׂרָאֵל לָאֱמֹרִי. אֲשֶׁר עָשָׂה יִשְׂרָאֵל הָיָה צָרִיךְ לוֹ לִכְתֹּב, מַה זֶּה אֵת כָּל? לְרַבּוֹת מַעְלָה וּמַטָּה. מַעְלָה, שֶׁאֲפִלּוּ מִשַּׁלִּיטֵיהֶם הַגְּדוֹלִים וְהַשַּׁלִּיטִים שֶׁלְּמַעְלָה, וַאֲפִלּוּ מִשַּׁלִּיטֵיהֶם הַגְּדוֹלִים וְהַשַּׁלִּיטִים שֶׁלְּמַטָּה. וְלָכֵן אֵת כָּל אֲשֶׁר עָשָׂה. וְלָכֵן כִּי רַב הוּא, בְּמָקוֹם שֶׁגָּדוֹל בְּכוֹר קָדוֹשׁ, שֶׁכָּתוּב (שמות ד) בְּנִי בְכֹרִי יִשְׂרָאֵל.</p>\n<p>וְאִם תֹּאמַר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה כָּךְ וְלֹא מִן הַדִּין - בֹּא וּרְאֵה. עֵשָׂו קְלִפָּה הָיָה וְצַד אַחֵר הָיָה. כֵּיוָן שֶׁיָּצְאָה קְלִפָּה וְהָעָבְרָה, הֲרֵי הַמֹּחַ מָצוּי (שפחה), עָרְלָה רִאשׁוֹנָה עוֹמֶדֶת בַּחוּץ. בְּרִית הִיא (גדולה ועליונה) וְנִכְבָּדָה מֵהַכֹּל, וְהִיא מִתְגַּלָּה אַחַר כָּךְ.</p>"],[9522012399,"<p>וַיֹּאמֶר מוֹאָב אֶל זִקְנֵי מִדְיָן עַתָּה יְלַחֲכוּ וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (זכריה ג) וַיַּרְאֵנִי אֶת יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל עֹמֵד לִפְנֵי מַלְאַךְ ה' וְגוֹ'. כַּמָּה יֵשׁ לוֹ לָאָדָם לִשְׁמֹר דְּרָכָיו בָּעוֹלָם הַזֶּה וְלָלֶכֶת בְּדֶרֶךְ אֱמֶת, מִשּׁוּם שֶׁכָּל מַעֲשֵׂי הָאָדָם כְּתוּבִים לִפְנֵי הַמֶּלֶךְ וּרְשׁוּמִים לְפָנָיו, וְכֻלָּם בְּמִנְיָן. שׁוֹמְרֵי הַשְּׁעָרִים עוֹמְדִים וּמְעִידִים, עוֹמְדִים וְתוֹבְעִים דִּינִים צוֹדְקִים. וְהַדַּיָּן עוֹמֵד לְקַבֵּל עֵדוּת, וְאוֹתָם שֶׁטּוֹעֲנִים טְעָנוֹת מְרַחֲשִׁים, וְלֹא יוֹדְעִים אִם יֵלְכוּ מִיָּמִין, אִם יַשְׂמְאִילוּ מִשְּׂמֹאל.</p>\n<p>שֶׁהֲרֵי כְּשֶׁרוּחוֹת בְּנֵי אָדָם יוֹצְאוֹת מֵהָעוֹלָם הַזֶּה, כַּמָּה הֵם מְקַטְרְגִים שֶׁעוֹמְדִים לִפְנֵיהֶם, וְהַכְּרוּזִים יוֹצְאִים הֵן לְטוֹב הֵן לְרָע, כְּפִי מַה שֶּׁיּוֹצֵא מֵהַדִּין. שֶׁשָּׁנִינוּ, בְּכַמָּה דִינִים נִדּוֹן הָאָדָם בָּעוֹלָם הַזֶּה, בֵּין בְּחַיָּיו בֵּין אַחַר כָּךְ, שֶׁהֲרֵי כָּל דְּבָרָיו הֵם בְּדִין, וְהַקָּדוֹשׁ בָּרוּךְ הוּא תָּמִיד בְּרַחֲמָנוּת וְרַחֲמָיו עַל הַכֹּל, וְלֹא רוֹצֶה לָדוּן בְּנֵי אָדָם כְּפִי מַעֲשֵׂיהֶם. שֶׁכָּךְ אָמַר דָּוִד, (תהלים קל) אִם עֲונוֹת תִּשְׁמָר יָהּ אֲדנָי מִי יַעֲמֹד. כָּאן יֵשׁ לְהִסְתַּכֵּל, כֵּיוָן שֶׁאָמַר אִם עֲונוֹת תִּשְׁמָר יָהּ, לָמָּה ה' (אדני) ?</p>\n<p>אֶלָּא, שָׁלֹשׁ דַּרְגוֹת רַחֲמִים הִזְכִּיר כָּאן דָּוִד. אִם עֲונוֹת תִּשְׁמָר יָהּ, אִם רַבִּים הָעֲונוֹת עַד שֶׁעוֹלִים לְמַעְלָה לְאַבָּא וְאִמָּא, הֲרֵי ה' (אדני), שֶׁהוּא רַחֲמִים. וְאִם שֵׁם זֶה, אַף עַל גַּב שֶׁהוּא רַחֲמִים, יִתְעוֹרֵר בְּדִין וְכָל הַדְּרָגוֹת נִסְתְּמוּ בְדִין - דַּרְגָּה אַחַת יֵשׁ לַחֲזֹּר אֵלֶיהָ, שֶׁכָּל הָרְפוּאוֹת יוֹצְאוֹת מִמֶּנָּה, הִיא תָּחוּס עָלֵינוּ. וּמִי הִיא? מִי. מִ\"י תַּעֲמֹד בְּוַדַּאי. מִ\"י יִרְפָּא לָךְ. (כמו שנאמר (איכה ב) כי גדול כים שברך מי ירפא לך) וְלָכֵן יָהּ ה' (אדני). אִם הַשֵּׁמוֹת הַלָּלוּ יִסְתַּתְּמוּ מֵאִתָּנוּ, מִ\"י יַעֲמֹד, שֶׁכָּל דַּרְכֵי הַתְּשׁוּבָה פְּתוּחִים מִמֶּנָּה.</p>"],[9522012400,"<p>בֹּא וּרְאֵה, יְהוֹשֻׁעַ בֶּן יְהוֹצָדָק הָיָה צַדִּיק גָּמוּר, גֶּבֶר שֶׁהָיָה נִכְנָס לִפְנַי וְלִפְנִים, שֶׁהִכְנִיסוּהוּ לִישִׁיבַת הָרָקִיעַ. הִתְכַּנְּסוּ כָּל בְּנֵי הַיְשִׁיבָה שָׁם לְעַיֵּן בְּדִינוֹ. וְכָךְ דַּרְכֵי אוֹתָהּ יְשִׁיבַת הָרָקִיעַ: כְּשֶׁמַּכְנִיסִים אוֹתוֹ לְדִין, הַכָּרוֹז יוֹצֵא וּמַכְרִיז: כָּל בְּנֵי הַיְשִׁיבָה הִכָּנְסוּ לַגֹּרֶן הַנֶּעְלָם. וּבֵית הַדִּין מִתְכַּנֵּס.</p>\n<p>וְאוֹתָהּ רוּחַ הָאִישׁ עוֹלָה עַל יְדֵי שְׁנֵי מְמֻנִּים. כֵּיוָן שֶׁנִּכְנָס, קָרֵב אֶל עַמּוּד אֶחָד שֶׁל שַׁלְהֶבֶת לוֹהֶטֶת שֶׁעוֹמֶדֶת שָׁם, וּמִתְגַּלֵּם בְּרוּחַ הָאֲוִיר שֶׁנּוֹשֵׁב בְּאוֹתוֹ עַמּוּד. וְכַמָּה הֵם שֶׁמַּעֲלִים אוֹתָם לְשָׁם, מִשּׁוּם שֶׁכָּל אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה וּמְחַדְּשִׁים בָּהּ חִדּוּשִׁים, מִיָּד נִכְתָּבִים הַדְּבָרִים אֶל בְּנֵי הַיְשִׁיבָה, וְאָז כָּל בְּנֵי הַיְשִׁיבָה בָּאִים לִרְאוֹתוֹ. אוֹתָם שְׁנֵי מְמֻנִּים יוֹצְאִים, וּמַעֲלִים אוֹתוֹ לְאוֹתָהּ יְשִׁיבַת הָרָקִיעַ. מִיָּד מִתְקָרֵב אֶל אוֹתוֹ עַמּוּד שֶׁמִּתְגַּלֵּם שָׁם.</p>\n<p>נִכְנָס לַיְשִׁיבָה וְרוֹאִים אוֹתוֹ. אִם הַדָּבָר כָּרָאוּי - זַכַּאי הוּא, כַּמָּה עֲטָרוֹת נוֹצְצוֹת מְעַטְּרִים אוֹתוֹ כָּל בְּנֵי הַיְשִׁיבָה. וְאִם דָּבָר אַחֵר הָיָה - אוֹי לְאוֹתָהּ בּוּשָׁה! דּוֹחִים אוֹתוֹ הַחוּצָה, וְעוֹמֵד תּוֹךְ הָעַמּוּד עַד שֶׁמַּעֲלִים אוֹתוֹ לְדִין. הָרַחֲמָן יַצִּילֵנוּ.</p>\n<p>וְיִשִׁ אֲחֵרִים שֶׁמַּעֲלִים אוֹתָם לְשָׁם כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַחֲלֹקֶת עִם בְּנֵי הַיְשִׁיבָה, וְאוֹמְרִים מִי מוֹכִיחַ? הֲרֵי פְּלוֹנִי הוֹכִיחַ הַדָּבָר. אָז מַעֲלִים אוֹתוֹ לְשָׁם, וּמוֹכִיחַ אוֹתוֹ הַדָּבָר בֵּין הַקָּדוֹשׁ בָּרוּךְ הוּא וּבֵין בְּנֵי הַיְשִׁיבָה. וְיֵשׁ אֲחֵרִים שֶׁמַּעֲלִים אוֹתָם שָׁם לְדִין, וְדָנִים אוֹתוֹ שָׁם לְבָרְרָם וּלְלַבְּנָם.</p>\n<p>אָמַר לוֹ רַבִּי יוֹסֵי, אִם כָּךְ, בְּלִי דִין נִפְטָר אָדָם וּמִסְתַּלֵּק מֵהָעוֹלָם הַזֶּה? וְאִם בְּדִין הִסְתַּלֵּק, מַדּוּעַ נִדּוֹן פַּעַם אַחֶרֶת? אָמַר לוֹ, כָּךְ לָמַדְנוּ וְכָךְ שָׁמַעְנוּ, שֶׁהֲרֵי וַדַּאי בְּדִין הִסְתַּלֵּק הָאָדָם מֵהָעוֹלָם הַזֶּה. אֲבָל עַד שֶׁלֹּא יִכָּנֵס לִמְחִצַּת הַצַּדִּיקִים, מַעֲלִים אוֹתוֹ לְדִין, וְשָׁם נִדּוֹן בְּאוֹתָהּ יְשִׁיבַת הָרָקִיעַ.</p>\n<p>וְשָׁם עוֹמֵד אוֹתוֹ מְמֻנֵּה הַגֵּיהִנֹּם לְהַשְׂטִין. אַשְׁרֵי מִי שֶׁזּוֹכֶה בַדִּין. וְאִם לֹא, אוֹתוֹ מְמֻנֵּה הַגֵּיהִנֹּם לוֹקֵחַ אוֹתוֹ בְּשָׁעָה שֶׁמּוֹסְרִים אוֹתוֹ בְּיָדָיו, וּמְקַלֵּעַ אוֹתוֹ מִשָּׁם לְמַטָּה כְּמוֹ שֶׁקּוֹלֵעַ אֶבֶן בְּקֶלַע (בכף הקלע), שֶׁכָּתוּב (שמואל אכ ה) וְאֵת נֶפֶשׁ אֹיְבֶיךְ יְקַלְּעֶנָּה בְּתוֹךְ כַּף הַקָּלַע וְגוֹ'. וְזוֹרְקוֹ לַגֵּיהִנֹּם, וּמְקַבֵּל עָנְשׁוֹ כְּפִי מַה שֶּׁנִּדּוֹן.</p>"],[9522012401,"<p>בֹּא וּרְאֵה, (זכריה ג) וַיַּרְאֵנִי אֶת יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל עֹמֵד לִפְנֵי מַלְאַךְ וְגוֹ'. שֶׁהֶעֱלוּהוּ לְדִין לְתוֹךְ אוֹתָהּ יְשִׁיבַת הָרָקִיעַ בְּשָׁעָה שֶׁנִּפְטַר מֵהָעוֹלָם הַזֶּה. עֹמֵד לִפְנֵי מַלְאַךְ ה' - זֶהוּ אוֹתוֹ נַעַר רֹאשׁ הַיְשִׁיבָה, שֶׁהוּא חוֹתֵךְ דִּין עַל הַכֹּל.</p>\n<p>וְהַשָּׂטָן, מִי זֶה וְהַשָּׂטָן? אוֹתוֹ מְמֻנֶּה עַל הַנְּפָשׁוֹת בַּגֵּיהִנֹּם, שֶׁתַּאֲוָתוֹ לְקַחְתּוֹ, וְתָמִיד עוֹמֵד וְאוֹמֵר הַב הַב, תְּנוּ רְשָׁעִים לַגֵּיהִנֹּם. לְשִׂטְנוֹ - לְהַזְכִּיר חֲטָאָיו. וְאָז - וַיֹּאמֶר ה' אֶל הַשָּׂטָן יִגְעַר ה' בְּךְ הַשָּׂטָן וְיִגְעַר ה' בְּךְ. שְׁתֵּי גְעָרוֹת לָמָּה? אֶלָּא אֶחָד לְדוּמָהִ, וְאֶחָד לְאוֹתוֹ שֶׁיּוֹצֵא מִגֵּיהִנּם שֶׁעוֹמֵד תָּמִיד לְהַשְׂטִין.</p>\n<p>בֹּא וּרְאֵה, אוֹתוֹ שָׂטָן עֶלְיוֹן יוֹרֵד כְּמוֹ שֶׁפֵּרְשׁוּהוּ, שֶׁהִתְגַּלֵּם בִּדְמוּת שׁוֹר, וְכָל אוֹתָן רוּחוֹת רָעוֹת שֶׁנִּדּוֹנוּ לְהִכָּנֵס לַגֵּיהִנֹּם, לוֹחֵךְ אוֹתָן בְּרֶגַע אֶחָד וְחוֹטְפָן, וְיוֹרֵד וְנוֹתְנָן לְדוּמָה לְאַחַר שֶׁבּוֹלְעָם. וְזֶהוּ שֶׁכָּתוּב וַיּאמֶר מוֹאָב אֶל זִקְנֵי מִדְיָן עַתָּה יְלַחֲכוּ הַקָּהָל אֶת כָּל סְבִיבֹתֵינוּ כִּלְחךְ הַשּׁוֹר, הַנּוֹדָע, הַשּׁוֹר שֶׁעוֹמֵד לְרַע עַל כָּל בְּנֵי הָעוֹלָם. אֶת יֶרֶק הַשָּׂדֶה - אוֹתָן רוּחוֹת בְּנֵי אָדָם, שֶׁהֵם יֶרֶק הַשָּׂדֶה. הַשָּׂדֶה - אוֹתוֹ הַשָּׂדֶה הַיָּדוּעַ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, אִם כָּךְ, בָּלָק הָיָה חָכָם. אָמַר לוֹ, בְּוַדַּאי, וְכָךְ הִצְטָרֵךְ לָדַעַת כָּל דַּרְכֵי אוֹתוֹ הַשּׁוֹר, וְאִם לֹא יוֹדֵעַ אוֹתָם, לֹא יָכוֹל לַעֲשׂוֹת כְּשָׁפָיו וּקְסָמָיו. אָמַר רַבִּי יוֹסֵי, וַדַּאי כָּךְ הוּא, וְנָאֶה אָמַרְתָּ. וְכֹחַ אוֹתוֹ הַשּׁוֹר מִכְּשֶׁמַּכְרִיזִים עַל הַתְּבוּאָה. כָּל אוֹתָם יָמִים שֶׁמַּכְרִיזִים וְכָל הַיָּמִים שֶׁמַּכְרִיזִים עַל רוּחוֹת בְּנֵי אָדָם, וְהֵם יְמֵי נִיסָן, וִימֵי תִשְׁרֵי, וַהֲרֵי נִתְבָּאֵר.</p>"]]});
